  ui_story_5082_50820100_1_dialog_content = "<color=#e8d9bb>En un raro día soleado, decides tumbarte en la hierba fuera de la sede temporal y dejar que tu mente divague...</color>",
  ui_story_5082_50820100_2_dialog_content = "¿Quieres escuchar los últimos informes?!",
