  ui_story_5082_50820100_33_dialog_content = "Espera... ¿Yo?",
  ui_story_5082_50820100_34_dialog_content = "¡Sí, tú!",
  ui_story_5082_50820100_35_dialog_content = "Este es el nuevo campo de entrenamiento del Comandante Barton, donde pone en forma a nuestros reclutas inexpertos! Es el lugar perfecto para ti, PlayerName!",
