  ui_story_5082_50820100_42_dialog_content = "¡S-Sí señor!",
  ui_story_5082_50820100_43_dialog_content = "(La presencia de Barton es tan abrumadora... Ni siquiera pensé en decir que no justo ahora...)",
  ui_story_5082_50820100_44_dialog_content = "Bueno escuchar.",
  ui_story_5082_50820100_45_dialog_content = "Veamos, ¿cómo puedo convertir a un pequeño Caelestite en una máquina de lucha en el menor tiempo posible?",
  ui_story_5082_50820100_46_dialog_content = "Um, ¿por qué no puedo simplemente hacer el mismo entrenamiento que todos los demás?",
  ui_story_5082_50820100_47_dialog_content = "Hmph, discútelo con esos viejos tontos del Comité. Ellos son los que insisten en que usemos sus nuevos métodos de entrenamiento \"científicos\".",
  ui_story_5082_50820100_48_dialog_content = "¡Han establecido todo tipo de referencias y plantillas, como si estuvieran tratando de dictar cada segundo de entrenamiento!",
  ui_story_5082_50820100_49_dialog_content = "¿Pero no es ese más o menos el punto?",
  ui_story_5082_50820100_50_dialog_content = "Tal vez solo para el entrenamiento físico, seguro.",
  ui_story_5082_50820100_51_dialog_content = "¡Pero aquí entreno a soldados reales, no a un montón de marionetas producidas en masa! Mi trabajo es prepararlos para luchar contra enemigos en el frente de batalla!",
  ui_story_5082_50820100_52_dialog_content = "Métodos de entrenamiento rígidos como este nunca producirán soldados verdaderamente sobresalientes. Eso es lo que pienso de todos modos.",
  ui_story_5082_50820100_53_dialog_content = "En el pasado, el Gran Mariscal y yo siempre participábamos en entrenamientos de combate en vivo con otros, incluso si no estábamos en el frente.",
