  ui_story_5082_50820100_55_dialog_content = "Aparte de un escaso número de municiones y suministros, todo lo que teníamos para confiar eran nuestros cuerpos y nuestro ingenio.",
  ui_story_5082_50820100_56_dialog_content = "Bajo esas circunstancias, los altos y poderosos no necesariamente estaban por delante de la competencia. Incluso los participantes menos notables tenían una oportunidad de ganar.",
  ui_story_5082_50820100_57_dialog_content = "Combate, estrategia, derrota y victoria.",
  ui_story_5082_50820100_58_dialog_content = "El dolor de ser pisoteado en el barro por los fuertes, y la determinación de ganar por cualquier medio necesario.",
  ui_story_5082_50820100_59_dialog_content = "Solo experimentando estas cosas de primera mano puede un soldado convertirse en algo verdaderamente poderoso.",
  ui_story_5082_50820100_60_dialog_content = "¡Un escenario de combate realista donde cualquier cosa puede suceder en cualquier momento es la mejor manera de afilar las habilidades de uno!",
  ui_story_5082_50820100_61_dialog_content = "Bien dicho, Barton.",
  ui_story_5082_50820100_62_dialog_content = "Reinhardt! ¿También estás aquí?",
  ui_story_5082_50820100_63_dialog_content = "Vine a ver el progreso de nuestros soldados antes de entrar en la Zona Oscura. Parece que llegué en el momento adecuado.",
  ui_story_5082_50820100_64_dialog_content = "Hace tiempo que no nos enfrentamos, Barton. ¿Te gustaría ver quién de nosotros ha mejorado más desde la última vez?",
  ui_story_5082_50820100_65_dialog_content = "¡Eso es todo lo que podría pedir!",
  ui_story_5082_50820100_66_dialog_content = "Espera, ustedes dos no van a...",
  ui_story_5082_50820100_67_dialog_content = "¡Así es! Estamos teniendo un ejercicio de combate en vivo, ¡aquí y ahora!",
  ui_story_5082_50820100_68_dialog_content = "¡No huyas, lo entiendes, niño?!",
  ui_story_5082_50820100_69_dialog_content = "¡Yo-Yo nunca! ¡No soy del tipo que se rinde antes de empezar!",
  ui_story_5082_50820100_70_dialog_content = "Bien, entonces considera esto una parte de tu entrenamiento especial, PlayerName. Naturalmente, tu manejador también participará.",
  ui_story_5082_50820100_71_dialog_content = "¿No es así, Jefe de Inteligencia Philyshy?",
  ui_story_5082_50820100_72_dialog_content = "Ahora que lo mencionas, no la he escuchado decir nada en un rato... ¡Oye! ¿Cuándo te escabulliste por allí?!",
  ui_story_5082_50820100_73_dialog_content = "Suspiro... Si tú lo dices, Gran Mariscal.",
  ui_story_5082_50820100_74_dialog_content = "¡Philyshy se ha unido a la batalla!",
  ui_story_5082_50820100_75_dialog_content = "<color=#e8d9bb>Momentos después</color>",
  ui_story_5082_50820100_76_dialog_content = "Buenas tardes a todos. Aunque no era parte del programa original—",
  ui_story_5082_50820100_77_dialog_content = "A petición del Gran Mariscal, he venido a servir como juez para este ejercicio de entrenamiento.",
  ui_story_5082_50820100_78_dialog_content = "El ejercicio, que durará dos días y dos noches, estará compuesto por cuatro equipos de dos personas cada uno. Siéntase libre de echar un vistazo a la lista de participantes.",
  ui_story_5082_50820100_79_dialog_content = "El equipo 1 es Reinhardt y Philyshy.",
