  ui_story_5082_50820100_85_dialog_content = "¡Ja! Parece que llevaremos esta pequeña competencia a esa Entrañas cercana.",
  ui_story_5082_50820100_86_dialog_content = "Tienes suerte, niño. Esa Subciudad ha estado abandonada durante mucho tiempo, y estoy en el proceso de adquirirla para mis campos de entrenamiento.",
  ui_story_5082_50820100_87_dialog_content = "Es una zona enorme con toneladas de estructuras abandonadas.",
