  ui_story_5082_50820100_90_dialog_content = "Los Eclipsites no tienen en cuenta estas cosas cuando atacan. Este nivel de incertidumbre es solo otra parte de la simulación de combate; te sugiero que te acostumbres a ello.",
  ui_story_5082_50820100_91_dialog_content = "Espera... Como juez, ¿no debería ser yo el que designe la ubicación?",
  ui_story_5082_50820100_92_dialog_content = "¡Jajajaja! Lo siento, me emocioné tanto que terminé haciendo el trabajo de la Jefa de Personal por ella!",
