  ui_story_5082_50820100_94_dialog_content = "Simplemente ve con la elección de Barton, Vivian.",
  ui_story_5082_50820100_95_dialog_content = "Muy bien entonces. Cada uno de ustedes tiene treinta minutos para prepararse antes de entrar al sitio del concurso. Cuando suene la campana, el combate comenzará oficialmente.",
  ui_story_5082_50820100_96_dialog_content = "Esta es una valiosa oportunidad para obtener experiencia de combate valiosa, así que por favor tómalo en serio y lucha con todas tus fuerzas.",
  ui_story_5082_50820100_97_dialog_content = "¡Entendido!",
  ui_story_5082_50820100_98_dialog_content = "La Subciudad cercana... Apenas tenemos información sobre ella. Barton definitivamente sabe cómo elegir sus batallas.",
  ui_story_5082_50820201_1_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5082_50820201_2_dialog_content = "¡Jajajaja, no está mal! ¡Veamos cómo nos detiene el Gran Mariscal ahora que su fortaleza está en ruinas!",
  ui_story_5082_50820201_3_dialog_content = "*tos*",
  ui_story_5082_50820201_4_dialog_content = "Tanto humo y escombros... Ugh... Una explosión así seguramente revelará nuestra posición.",
  ui_story_5082_50820201_5_dialog_content = "¿No deberíamos intentar alejarnos de este lugar?",
