  ui_story_5082_50820201_7_dialog_content = "¡Dividámonos y recojamos cualquier comida y recursos que podamos encontrar, PlayerName!",
  ui_story_5082_50820201_8_dialog_content = "¡Entendido!",
  ui_story_5082_50820201_9_dialog_content = "Solo iré por este camino... ¿Eh?",
  ui_story_5082_50820201_10_dialog_content = "Se siente como si alguien me estuviera observando...",
  ui_story_5082_50820201_11_dialog_content = "Suspiro... Trabajé tan duro en esa fortaleza también.",
  ui_story_5082_50820201_12_dialog_content = "¡No tenías que volarlo de esa manera, sabes!",
  ui_story_5082_50820201_13_dialog_content = "(¿¡Ella ya ha vuelto?!)",
  ui_story_5082_50820201_14_dialog_content = "(Pero parece que Philyshy está solo...)",
  ui_story_5082_50820201_15_dialog_content = "Espera, Philyshy! ¡Solo escúchame!",
  ui_story_5082_50820201_16_dialog_content = "Barton no está demasiado lejos de nuestra ubicación. Si me atacas ahora mismo, él estará aquí antes de que te des cuenta.",
  ui_story_5082_50820201_17_dialog_content = "Luchar contra ambos por tu cuenta no es lo mejor para ti.",
  ui_story_5082_50820201_18_dialog_content = "¿Por qué no te retiras por ahora? Si lo haces, prometo que no atacaremos a tu equipo durante las próximas dos horas.",
  ui_story_5082_50820201_19_dialog_content = "¡Incluso te ayudaremos derribando a los otros dos equipos! Tendrás dos horas completas para hacer lo que quieras, ¡incluso si no haces nada en absoluto!",
  ui_story_5082_50820201_20_dialog_content = "Hmm, eso suena bien.",
  ui_story_5082_50820201_21_dialog_content = "Entonces-",
