  ui_story_5082_50820201_24_dialog_content = "¡Es muy tarde ahora!",
  ui_story_5082_50820201_25_dialog_content = "(Si no puedo negociar para salir de esto... ¡Entonces solo tengo que correr!)",
  ui_story_5082_50820201_26_dialog_content = "¡Quédate quieto, ¿quieres?!",
  ui_story_5082_50820201_27_dialog_content = "¡No soporto cuando mi presa sigue corriendo por todos lados!",
