  ui_story_5082_50820201_31_dialog_content = "¡¡!!",
  ui_story_5082_50820201_32_dialog_content = "Eso es... ¡Es Reinhardt! ¡Ahora sí que estoy acabado!",
  ui_story_5082_50820201_33_dialog_content = "Sabía que construir una fortaleza en un lugar tan obvio era la decisión correcta.",
  ui_story_5082_50820201_34_dialog_content = "Lo siento PlayerName, pero parece que tu entrenamiento especial se va a cortar pronto.",
