  ui_story_5082_50820201_36_dialog_content = "¡Apúrate y corre!",
  ui_story_5082_50820201_37_dialog_content = "Puedes correr tan rápido como quieras, pero—",
  ui_story_5082_50820201_38_dialog_content = "¡Corre!",
  ui_story_5082_50820201_39_dialog_content = "¡Corre!",
  ui_story_5082_50820201_40_dialog_content = "... ¿Quién está ahí?",
