  ui_story_5082_50820201_42_dialog_content = "Esa voz.",
  ui_story_5082_50820201_43_dialog_content = "¡Corre!",
  ui_story_5082_50820201_44_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5082_50820201_45_dialog_content = "¡...!",
  ui_story_5082_50820201_46_dialog_content = "¡Nada es más desagradable que perder una batalla debido a tu propia indecisión!",
  ui_story_5082_50820201_47_dialog_content = "Barton— ¡Ah!",
  ui_story_5082_50820201_48_dialog_content = "¡PlayerName ha sido asegurado!",
  ui_story_5082_50820201_49_dialog_content = "\"¿Asegurado\"? ¿Qué soy, un paquete?!",
  ui_story_5082_50820201_50_dialog_content = "¿Es esto... Un carro de mina? ¿De dónde vino esto?!",
  ui_story_5082_50820201_51_dialog_content = "Aquí tienes otra lección valiosa, niño: en la batalla, ¡no existe tal cosa como un objeto inútil!",
  ui_story_5082_50820201_52_dialog_content = "Y a eso, me gustaría agregar algunas palabras mías.",
  ui_story_5082_50820201_53_dialog_content = "En la batalla, no existe tal cosa como una solución perfecta para cada problema.",
  ui_story_5082_50820201_54_dialog_content = "¡Reinhardt se está acercando!",
  ui_story_5082_50820201_55_dialog_content = "Incluso si su corazón no está en ello, supongo que ella sigue siendo la Gran Mariscal.",
  ui_story_5082_50820201_56_dialog_content = "Algunas viejas heridas se han reavivado ahora, eso es todo. Confía en mí, no tendrás otra oportunidad como esa de nuevo.",
  ui_story_5082_50820201_57_dialog_content = "¡Tch! Aférrate fuerte, PlayerName!",
  ui_story_5082_50820201_58_dialog_content = "El Expreso Barton va a toda velocidad adelante!",
  ui_story_5082_50820201_59_dialog_content = "¡Ahhhhh—!",
  ui_story_5082_50820201_60_dialog_content = "¡Si vas a tratarme como una carga, al menos manéjame con cuidado!",
  ui_story_5082_50820201_61_dialog_content = "¡Jajajaja!",
  ui_story_5082_50820201_62_dialog_content = "¡Espera, mira allá! ¡Es un callejón sin salida! ¡Vamos a estrellarnos—!",
  ui_story_5082_50820201_63_dialog_content = "¡Entonces nos abriremos paso a la fuerza!",
  ui_story_5082_50820201_64_dialog_content = "¡¿Qué?!",
  ui_story_5082_50820201_65_dialog_content = "¡No hay tiempo para explicar! ¡Cuidado con la cabeza!",
  ui_story_5082_50820201_66_dialog_content = "Espera—",
  ui_story_5082_50820201_67_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5082_50820201_68_dialog_content = "<color=#e8d9bb>¡Ping! ¡Bam! ¡Clang, clang, clang!</color>",
  ui_story_5082_50820201_69_dialog_content = "Urgh...",
  ui_story_5082_50820201_70_dialog_content = "Finalmente nos detuvimos... Pensé que estaba muerto seguro...",
  ui_story_5082_50820201_71_dialog_content = "¿De qué hay que tener miedo? Te salvé del Gran Mariscal, ¿no es así?",
  ui_story_5082_50820201_72_dialog_content = "No, ese no es el punto... Oye Barton?",
  ui_story_5082_50820201_73_dialog_content = "¿Sí?",
  ui_story_5082_50820201_74_dialog_content = "Realmente no deberías tener permiso para conducir.",
  ui_story_5082_50820201_75_dialog_content = "?",
  ui_story_5082_50820201_76_dialog_content = "De todos modos, ¿qué es este lugar?",
  ui_story_5082_50820201_77_dialog_content = "Estuvimos corriendo tanto tiempo que perdí mi sentido de la dirección. Quizás debería usar mis poderes para percibir nuestro entorno.",
  ui_story_5082_50820201_78_dialog_content = "Antes de hacer eso, intenta observar tu entorno primero.",
  ui_story_5082_50820201_79_dialog_content = "¿Mis alrededores?",
  ui_story_5082_50820201_80_dialog_content = "¡Vaya, mira todas estas cajas! ¿Podrían ser...?!",
  ui_story_5082_50820201_81_dialog_content = "¡Ellos son! ¡Cajas de suministro!",
  ui_story_5082_50820201_82_dialog_content = "No pensaste que solo te estaba llevando a un paseo salvaje, ¿verdad?",
  ui_story_5082_50820201_83_dialog_content = "En la batalla, ninguna acción individual es completamente independiente del resto de la situación.",
  ui_story_5082_50820201_84_dialog_content = "Ser capaz de absorber todo en tu campo de visión te acercará un paso más a la victoria.",
  ui_story_5082_50820201_85_dialog_content = "El primer día de la competencia está casi terminado. Tomar el control de estos suministros nos dará una de las mayores ventajas posibles.",
  ui_story_5082_50820201_86_dialog_content = "Desafortunadamente, esa gran ventaja también te convierte en un objetivo principal para todos los demás.",
  ui_story_5082_50820201_87_dialog_content = "No es diferente a tener una lanza apuntándote a la cabeza todo el tiempo.",
  ui_story_5082_50820201_88_dialog_content = "Barton!",
  ui_story_5082_50820201_89_dialog_content = "Relájate, chico. Aún no hemos perdido.",
  ui_story_5082_50820201_90_dialog_content = "Ven ahora, Gran Mariscal. Incluso los escolares saben que quien tenga los mejores bocadillos siempre será el objetivo de los celos.",
  ui_story_5082_50820201_91_dialog_content = "Encontré estos suministros primero, así que no hay manera de que los entregue tan fácilmente.",
  ui_story_5082_50820201_92_dialog_content = "PlayerName tiene un detonador en sus manos. Con solo presionar un botón, los explosivos de baja calidad que he esparcido entre los suministros explotarán, convirtiendo todo en cenizas.",
  ui_story_5082_50820201_93_dialog_content = "(¿Eh? ¿Detonador?)",
  ui_story_5082_50820201_94_dialog_content = "Deberías saber exactamente lo que significa para una persona destruir sus propios suministros en batalla.",
  ui_story_5082_50820201_95_dialog_content = "Este ejercicio dura dos días enteros. Como Gran Mariscal, ¿estás realmente dispuesto a dejar que tus subordinados luchen sin comida en sus barrigas?",
  ui_story_5082_50820201_96_dialog_content = "Jajaja, casi olvido cómo es enfrentarte en combate.",
  ui_story_5082_50820201_97_dialog_content = "Pero incluso si eso significa pasar hambre—",
  ui_story_5082_50820201_98_dialog_content = "(... ¿Eh? Qué demonios es...)",
  ui_story_5082_50820201_99_dialog_content = "(Ya es el segundo día del ejercicio de entrenamiento. Esta situación... no va a terminar pronto.)",
  ui_story_5082_50820201_100_dialog_content = "(Soy el único que encontró munición el primer día. No me encontré con nadie más que tuviera raciones.)",
  ui_story_5082_50820201_101_dialog_content = "(No lo lograré a este ritmo...)",
  ui_story_5082_50820201_102_dialog_content = "¿Así que tú eres el que tomó la munición, eh?",
  ui_story_5082_50820201_103_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50820201_104_dialog_content = "¿Disparar antes de discernir la identidad de la otra persona? Eso no es muy agradable.",
  ui_story_5082_50820201_105_dialog_content = "Eres el que se coló en mi campamento. No tienes derecho a ninguna cortesía.",
  ui_story_5082_50820201_106_dialog_content = "¡Jajajaja! Entonces trabajemos juntos, Reinhardt!",
  ui_story_5082_50820201_107_dialog_content = "Se supone que esto es un ejercicio de combate real. ¿Por qué debería aceptar unirme a un infiltrado como tú?",
  ui_story_5082_50820201_108_dialog_content = "Bueno, para empezar, bloqueé tu ataque hace un momento sin mucho esfuerzo, y no te estabas conteniendo, ¿verdad?",
  ui_story_5082_50820201_109_dialog_content = "También hay otros beneficios de trabajar conmigo. Las raciones, por ejemplo.",
  ui_story_5082_50820201_110_dialog_content = "Todavía hay muchos otros luchadores fuertes en este ejercicio. Solo es cuestión de tiempo antes de que se decida un vencedor.",
  ui_story_5082_50820201_111_dialog_content = "No se puede negar que necesito munición, y algo me dice que no quieres luchar con el estómago vacío, ¿verdad?",
  ui_story_5082_50820201_112_dialog_content = "Tch...",
  ui_story_5082_50820201_113_dialog_content = "Acuerdo.",
  ui_story_5082_50820201_114_dialog_content = "<color=#e8d9bb>Dos días después</color>",
  ui_story_5082_50820201_115_dialog_content = "No esperaba derribar a otro equipo tan rápido. Eres bastante bueno.",
  ui_story_5082_50820201_116_dialog_content = "¡Claro que soy yo!",
  ui_story_5082_50820201_117_dialog_content = "Parece que hemos terminado de luchar por hoy. Tuviste que usar mi munición, así que entrega tus raciones y—",
  ui_story_5082_50820201_118_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5082_50820201_119_dialog_content = "Urgh...",
  ui_story_5082_50820201_120_dialog_content = "Un ataque furtivo... Debí saberlo.",
  ui_story_5082_50820201_121_dialog_content = "Ella se ha ido... junto con toda mi munición.",
  ui_story_5082_50820201_122_dialog_content = "Ugh... No puedo creer que caí en eso.",
  ui_story_5082_50820201_123_dialog_content = "No he comido en dos días, y esa batalla de ahora me agotó mucho. Cada vez es más difícil aguantar.",
  ui_story_5082_50820201_124_dialog_content = "Tendré que descansar aquí por el día y conservar la poca energía que aún tengo. Cuando llegue mañana, yo...",
  ui_story_5082_50820201_125_dialog_content = "<color=#e8d9bb>Dos días más después</color>",
  ui_story_5082_50820201_126_dialog_content = "(Mi cabeza da vueltas... Y mi cuerpo se siente tan pesado.)",
  ui_story_5082_50820201_127_dialog_content = "(Pero la batalla aún no ha terminado. Tengo que seguir adelante...)",
  ui_story_5082_50820201_128_dialog_content = "(En lugar de enfadarme, necesito pensar en mi próximo movimiento—)",
  ui_story_5082_50820201_129_dialog_content = "Vaya, ¿todavía puedes moverte?",
  ui_story_5082_50820201_130_dialog_content = "Tienes algo de valor, mostrándote a mi alrededor.",
  ui_story_5082_50820201_131_dialog_content = "¿Por qué? Es tu propia culpa por no descubrir mis motivos antes.",
  ui_story_5082_50820201_132_dialog_content = "Al final del día, supongo que incluso los mejores estudiantes no valen mucho!",
  ui_story_5082_50820201_133_dialog_content = "Dime, ¿qué duele más ahora mismo? ¿Tus heridas o tu hambre?",
  ui_story_5082_50820201_134_dialog_content = "Simplemente cállate y sácame de aquí. Eso es por lo que estás aquí, ¿verdad?",
  ui_story_5082_50820201_135_dialog_content = "Oh, ya veo. Apenas puedes mantenerte de pie ahora, ¿verdad? Pobrecito.",
  ui_story_5082_50820201_136_dialog_content = "¡Dije cállate!",
  ui_story_5082_50820201_137_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5082_50820201_138_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5082_50820201_139_dialog_content = "¡Esquiva, PlayerName!",
  ui_story_5082_50820201_140_dialog_content = "Barton!",
  ui_story_5082_50820201_141_dialog_content = "¡Qué alboroto... Así que las raciones estaban aquí todo el tiempo!",
  ui_story_5082_50820201_142_dialog_content = "¿Ves eso? El Gran Mariscal y el Comandante Barton están dando todo... ¿Realmente queremos interponernos en eso?",
  ui_story_5082_50820201_143_dialog_content = "...",
  ui_story_5082_50820201_144_dialog_content = "¡...!",
  ui_story_5082_50820201_145_dialog_content = "(¿Fue eso... mi memoria justo ahora?)",
  ui_story_5082_50820201_146_dialog_content = "Y aquí pensé que estabas distraído... Pero si tomamos esta pelea en serio, veamos cuánto has mejorado, ¡Gran Mariscal!",
  ui_story_5082_50820301_1_dialog_content = "... Me alegra que decidimos no interferir. Ese ataque de ahora nos habría matado cien veces.",
  ui_story_5082_50820301_2_dialog_content = "Están en un nivel completamente diferente, después de todo. No podrías decirlo al ver al Comandante Barton cuando lucha contra los Eclipsites...",
  ui_story_5082_50820301_3_dialog_content = "El Gran Mariscal Reinhardt lo tenía contra las cuerdas hace un momento, ¡pero no tiene ni un rasguño! ¿De qué está hecho su cuerpo...?",
  ui_story_5082_50820301_4_dialog_content = "... ¿Podrían ser ciertas esos rumores? Dicen que el Comandante Barton debe su inmenso poder a una serie de experimentos especiales.",
  ui_story_5082_50820301_5_dialog_content = "También escucho que algunos de nuestros reclutas más recientes, los más cercanos a nuestros científicos, han pasado por el mismo programa. ¿Cuántos de ellos están en Illumina...?",
  ui_story_5082_50820301_6_dialog_content = "Pareces bastante interesado en ellos.",
  ui_story_5082_50820301_7_dialog_content = "¿Quién no lo estaría? Si es cierto, ¡todo lo que se necesitaría para unirse a las fuerzas especiales son unos pocos procedimientos!",
  ui_story_5082_50820301_8_dialog_content = "Pero quién sabe a qué tipo de experimentos locos fueron sometidos—",
  ui_story_5082_50820301_9_dialog_content = "Bueno, al menos no me he convertido en un Eclipsite, ¿verdad?",
  ui_story_5082_50820301_10_dialog_content = "C-C-Comandante Barton!!!",
  ui_story_5082_50820301_11_dialog_content = "...",
  ui_story_5082_50820301_12_dialog_content = "¿Por qué tan silencioso de repente?",
  ui_story_5082_50820301_13_dialog_content = "No hay ninguna regla que prohíba expresar tu opinión en la 2da Legión, o en cualquier otro lugar en Illumina.",
  ui_story_5082_50820301_14_dialog_content = "Si tienes algo que decirle a tu comandante, entonces dilo.",
  ui_story_5082_50820301_15_dialog_content = "P-Pero tú eres diferente a los demás, Comandante Barton!",
  ui_story_5082_50820301_16_dialog_content = "Todos dicen que Illumina estaba en grave peligro en aquel entonces, ¡y que solo hiciste ese sacrificio para cambiar el curso de la batalla!",
  ui_story_5082_50820301_17_dialog_content = "Pero los demás...",
  ui_story_5082_50820301_18_dialog_content = "¿Lucharon en las líneas de frente?",
  ui_story_5082_50820301_19_dialog_content = "yo, eh...",
  ui_story_5082_50820301_20_dialog_content = "¡Te hice una pregunta, soldado! ¿Estos \"otros\" de los que sigues hablando; lucharon contra los Eclipsites en el frente?!",
  ui_story_5082_50820301_21_dialog_content = "¡Sí señor!",
  ui_story_5082_50820301_22_dialog_content = "¿Lucharon ellos a través del mismo amargo entrenamiento por el que pasaste tú?!",
  ui_story_5082_50820301_23_dialog_content = "¡Sí señor!",
  ui_story_5082_50820301_24_dialog_content = "¿Pudieron disfrutar de vidas pacíficas y despreocupadas simplemente porque pasaron por esos experimentos?",
  ui_story_5082_50820301_25_dialog_content = "... No, señor.",
  ui_story_5082_50820301_26_dialog_content = "¡Entonces todavía son soldados de Illumina, y tus camaradas en armas!",
  ui_story_5082_50820301_27_dialog_content = "¡La sangre y el sudor que derraman no son diferentes a los tuyos!",
  ui_story_5082_50820301_28_dialog_content = "Han hecho sacrificios de formas que ni siquiera puedes imaginar, todo por el bien del futuro de Illumina.",
  ui_story_5082_50820301_29_dialog_content = "No son diferentes a mí en ningún aspecto. ¡Menospreciarlos es lo mismo que menospreciarme a mí!",
  ui_story_5082_50820301_30_dialog_content = "Pero si no tienes intención de verme como algún tipo de monstruo, entonces nunca olvides que aún son tus aliados.",
  ui_story_5082_50820301_31_dialog_content = "...",
  ui_story_5082_50820301_32_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5082_50820301_33_dialog_content = "<color=#e8d9bb>Nadie vio claramente el ataque de Barton. Todo lo que vieron fue un destello de plata.</color>",
  ui_story_5082_50820301_34_dialog_content = "<color=#e8d9bb>En el siguiente momento, las armas de los soldados se partieron en dos y cayeron al suelo.</color>",
  ui_story_5082_50820301_35_dialog_content = "Lo siento, pero has sido eliminado.",
  ui_story_5082_50820301_36_dialog_content = "Vete a casa y piensa mucho sobre lo que aprendiste aquí.",
  ui_story_5082_50820301_37_dialog_content = "Sí, señor...",
  ui_story_5082_50820301_38_dialog_content = "Y en cuanto a ti, PlayerName.",
  ui_story_5082_50820301_39_dialog_content = "¿Por qué la cara larga? Estaban hablando de nosotros, los soldados modificados, no de ti.",
  ui_story_5082_50820301_40_dialog_content = "Es porque aceptaste las modificaciones de Chord Link para protegernos a todos...",
  ui_story_5082_50820301_41_dialog_content = "Sigues pensando demasiado para alguien tan agotado.",
  ui_story_5082_50820301_42_dialog_content = "Escucha aquí, niño. No acepté la modificación para proteger a tu gente; lo hice para ganar.",
  ui_story_5082_50820301_43_dialog_content = "Y el poder que obtuve después es mío. Viste mi velocidad cuando esquivé el ataque del Gran Mariscal antes, ¿no es así?",
  ui_story_5082_50820301_44_dialog_content = "Todavía es un poco difícil de controlar, pero todo poder tiene un precio. Es perfectamente razonable, si me preguntas.",
  ui_story_5082_50820301_45_dialog_content = "Además, ¿quién dice que no seré yo el que mantenga al Gran Mariscal contra las cuerdas una vez que domine este poder? ¡Jajaja!",
  ui_story_5082_50820301_46_dialog_content = "Me alegra que no parezca afectarte... Pero hablando de Reinhardt...",
  ui_story_5082_50820301_47_dialog_content = "Algo parece extraño en ella. Perdió la concentración en medio de la batalla muchas veces hoy.",
  ui_story_5082_50820301_48_dialog_content = "Fue igual hace un momento. Solo pudimos escapar porque ella de repente dejó de atacar.",
  ui_story_5082_50820301_49_dialog_content = "Tú también lo notaste, ¿eh...? Siempre que la Gran Mariscal entra al campo de batalla, tiene la tendencia de estar en el centro de todo.",
  ui_story_5082_50820301_50_dialog_content = "Ya sean sus aliados o sus enemigos, ella es capaz de dictar el flujo de la lucha a su alrededor.",
  ui_story_5082_50820301_51_dialog_content = "Pero hoy es diferente. Aunque ella sigue salvando la situación al final, definitivamente no tiene el control de la misma. De hecho, parece ser al revés.",
  ui_story_5082_50820301_52_dialog_content = "Eso no es algo que una \"recurrencia\" de una vieja herida pudiera causar jamás.",
  ui_story_5082_50820301_53_dialog_content = "...",
  ui_story_5082_50820301_54_dialog_content = "...",
  ui_story_5082_50820301_55_dialog_content = "Agh...",
  ui_story_5082_50820301_56_dialog_content = "¿Qué es?",
  ui_story_5082_50820301_57_dialog_content = "Creo que de repente sentí algo...",
  ui_story_5082_50820301_58_dialog_content = "¿En un lugar como este?",
  ui_story_5082_50820301_59_dialog_content = "¡Intentaré obtener una mejor lectura!",
  ui_story_5082_50820301_60_option_content = "¡Escaneo psíquico!",
  ui_story_5082_50820301_61_dialog_content = "¿Dónde estaba...?",
  ui_story_5082_50820301_62_dialog_content = "<color=#e8d9bb>Retumbar-</color>",
  ui_story_5082_50820301_63_dialog_content = "El suelo... ¿Está temblando?",
  ui_story_5082_50820301_64_dialog_content = "La presencia que sentí justo ahora... No la reconocí, pero vincularme con ella se sintió extrañamente familiar.",
  ui_story_5082_50820301_65_dialog_content = "... Es ella.",
  ui_story_5082_50820301_66_dialog_content = "¡Ahí está!",
  ui_story_5082_50820301_67_dialog_content = "¿Quién eres? ¿Y por qué estás aquí?",
  ui_story_5082_50820301_68_dialog_content = "Es esa chica...",
  ui_story_5082_50820301_69_dialog_content = "¿Una chica? ¿De quién estás hablando?",
  ui_story_5082_50820301_70_dialog_content = "¡La chica con un dragón detrás de ella!",
  ui_story_5082_50820301_71_dialog_content = "¿Qué eres tú-",
  ui_story_5082_50820301_72_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_5082_50820301_73_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5082_50820302_1_dialog_content = "¡PlayerName! ¿¡Estás bien!?",
  ui_story_5082_50820302_2_dialog_content = "*tos* Estoy bien... Gracias, Barton.",
  ui_story_5082_50820302_3_dialog_content = "¿Pero qué hizo que este edificio se derrumbara? No hay ninguna pelea cerca, hasta donde puedo decir.",
  ui_story_5082_50820302_4_dialog_content = "Ven a ver esto.",
  ui_story_5082_50820302_5_dialog_content = "... ¡Qué espacio tan enorme! Todo está destrozado más allá de la reparación... ¿Qué tipo de batalla podría haber tenido lugar aquí?",
  ui_story_5082_50820302_6_dialog_content = "Estábamos tan enfocados en el ejercicio de entrenamiento que nunca lo notamos.",
  ui_story_5082_50820302_7_dialog_content = "Pero si una batalla como esta tuvo lugar tan cerca de la ciudad de Gannon, no hay forma de que nos la hubiéramos perdido.",
  ui_story_5082_50820302_8_dialog_content = "¿O tal vez esto ocurrió cuando se derrumbó en aquel entonces...?",
  ui_story_5082_50820302_9_dialog_content = "¡Así es, acabo de sentir una presencia extraña!",
  ui_story_5082_50820302_10_dialog_content = "Seguía diciendo cosas que no podía entender. ¿Quizás tiene algo que ver con este lugar?",
  ui_story_5082_50820302_11_dialog_content = "Intentaré sentirlo de nuevo—",
  ui_story_5082_50820302_12_dialog_content = "Un momento, por favor.",
  ui_story_5082_50820302_13_dialog_content = "... ¿Vivian? ¿Qué estás haciendo aquí?",
  ui_story_5082_50820302_14_dialog_content = "¿No me digas que estábamos haciendo mucho ruido? ¡Jajaja! No te preocupes, ya me he encargado del problema.",
  ui_story_5082_50820302_15_dialog_content = "Pero si todos están aquí, ¿eso significa que buscan una revancha, Gran Mariscal?",
  ui_story_5082_50820302_16_dialog_content = "Quizás la próxima vez.",
  ui_story_5082_50820302_17_dialog_content = "No compliques las cosas para el Gran Mariscal, Barton.",
  ui_story_5082_50820302_18_dialog_content = "Vine a compartir una notificación importante de la sede. Ya he informado al Gran Mariscal y a Philyshy sobre ello.",
  ui_story_5082_50820302_19_dialog_content = "¿Cuál es la situación?",
  ui_story_5082_50820302_20_dialog_content = "Debido a un descuido en el registro, acabamos de darnos cuenta de que esta área está estrictamente prohibida.",
  ui_story_5082_50820302_21_dialog_content = "Y considerando el agravamiento de las viejas heridas del Gran Mariscal, creemos que continuar con el ejercicio de entrenamiento resultará en más daño—",
  ui_story_5082_50820302_22_dialog_content = "Por lo tanto, lamento informarles que este ejercicio de entrenamiento ha terminado.",
  ui_story_5082_50820302_23_dialog_content = "Pero acabo de sentir...",
  ui_story_5082_50820302_24_dialog_content = "Manejaremos el resto del asunto, así que por favor comprende, PlayerName. Después de todo, es una zona restringida.",
  ui_story_5082_50820302_25_dialog_content = "(Reinhardt se ve tan serio. ¿Sucedió algo en la ciudad de Gannon...?)",
  ui_story_5082_50820302_26_dialog_content = "... Bien.",
  ui_story_5082_50820302_27_dialog_content = "¿De verdad ya se acabó? ¡Y yo apenas estaba calentando!",
  ui_story_5082_50820302_28_dialog_content = "Me he aburrido hasta la saciedad haciendo que mis tropas realicen exactamente los mismos ejercicios todos los días.",
  ui_story_5082_50820302_29_dialog_content = "Este concurso fue un cambio de ritmo tan agradable. Cortarlo así me deja un mal sabor de boca.",
  ui_story_5082_50820302_30_dialog_content = "Estoy de acuerdo. Aunque el ejercicio tenga que terminar, odiaría arruinar la diversión de todos.",
  ui_story_5082_50820302_31_dialog_content = "Ya que todos ya están aquí, ¿por qué no hacemos una celebración con una hoguera esta noche en su lugar?",
  ui_story_5082_50820302_32_dialog_content = "Puedo dejarte los preparativos, ¿verdad Barton?",
  ui_story_5082_50820302_33_dialog_content = "... Oye, tú eres el jefe por aquí, ¿no? ¡Por supuesto que puedo manejarlo! ¡Haré que mis subordinados comiencen a mover cosas de inmediato!",
  ui_story_5082_50820302_34_dialog_content = "Entonces iré con—",
  ui_story_5082_50820302_35_dialog_content = "¡Oh no, tú no! ¡Vienes conmigo primero!",
  ui_story_5082_50820302_36_dialog_content = "¡O-Oye! ¡No me arrastres así, Philyshy! ¿Y dónde has estado todo este tiempo, por cierto?!",
  ui_story_5082_50820302_37_dialog_content = "Relajándome, naturalmente... Pero parece que incluso yo he estado en la oscuridad sobre este lugar, miau.",
  ui_story_5082_50820302_38_dialog_content = "Los escuché hablando hace un momento.",
  ui_story_5082_50820302_39_dialog_content = "\"No estamos ocultando nada de ellos. Simplemente no es el momento adecuado, eso es todo\". Eso es lo que escuché decir al Gran Mariscal Reinhardt y al Oficial Vivian.",
  ui_story_5082_50820302_40_dialog_content = "¡Ahora apúrate y usa tus poderes psíquicos, PlayerName! ¡Quiero escuchar de qué están hablando ahora!",
  ui_story_5082_50820302_41_dialog_content = "¡Eso no es para lo que sirven mis poderes, Philyshy!",
  ui_story_5082_50820302_42_dialog_content = "Nyeh, eres un verdadero aguafiestas. ¡Entonces lo haré yo mismo!",
  ui_story_5082_50820302_43_dialog_content = "Y ella se ha ido... No hay quien la detenga cuando siente curiosidad por algo, ¿verdad?",
  ui_story_5082_50820302_44_dialog_content = "(Aún así, me pregunto qué le pasó a Reinhardt...)",
  ui_story_5082_50820401_1_dialog_content = "<color=#e8d9bb>En medio de la noche, durante la fogata...</color>",
  ui_story_5082_50820401_2_dialog_content = "... Ven.",
  ui_story_5082_50820401_3_dialog_content = "Esa presencia... ¡Eres tú otra vez!",
  ui_story_5082_50820401_4_dialog_content = "Eres el que me sintió... Caelestite.",
  ui_story_5082_50820401_5_dialog_content = "¿Me conoces? ¿Quién eres? ¿Y por qué te estás acercando a mí?",
  ui_story_5082_50820401_6_dialog_content = "Ayúdame a salir de este lugar.",
  ui_story_5082_50820401_7_dialog_content = "!!!",
  ui_story_5082_50820401_8_dialog_content = "¿Eres un Coloso?!",
  ui_story_5082_50820401_9_dialog_content = "Me llaman Punta de Lanza.",
  ui_story_5082_50820401_10_dialog_content = "¿Cuándo consiguió Illumina poner sus manos en un Coloso consciente?!",
  ui_story_5082_50820401_11_dialog_content = "Espera un minuto... Un Colossus consciente... ¿Eso significa que tienes un Navegador Caelestite como yo?",
  ui_story_5082_50820401_12_dialog_content = "&>!#%$^!#$",
  ui_story_5082_50820401_13_dialog_content = "¡Illumina! ¡Su gente no puede ser confiada!",
  ui_story_5082_50820401_14_dialog_content = "¡Me encarcelaron! ¡Me alteraron! ¡Desean convertirme en un arma de guerra!",
  ui_story_5082_50820401_15_dialog_content = "Intenté escapar tantas veces, solo para ser destruido en mi último intento.",
  ui_story_5082_50820401_16_dialog_content = "Era esa chica... ¡la chica con un $^%%$ detrás de ella!",
  ui_story_5082_50820401_17_dialog_content = "(¿Una niña? Y hay algo detrás de ella... ¿?)",
  ui_story_5082_50820401_18_dialog_content = "^#!^#%$&&! ^&*tite... Ven a buscarme.",
  ui_story_5082_50820401_19_dialog_content = "Ven a buscarme.",
  ui_story_5082_50820401_20_dialog_content = "¿Dónde estás?",
  ui_story_5082_50820401_21_dialog_content = "Ven a buscarme. Ayúdame a salir—",
  ui_story_5082_50820401_22_dialog_content = "¡Espera, todavía tengo más preguntas que hacerte!",
  ui_story_5082_50820401_23_dialog_content = "¡Sobre los Celestitas y Eraveil! ¡Sobre Soroz y—",
  ui_story_5082_50820401_24_dialog_content = "Entonces ven a buscarme—",
  ui_story_5082_50820401_25_dialog_content = "¡Oye!",
  ui_story_5082_50820401_26_dialog_content = "¿Qué pasa, niño? ¡Animarse!",
  ui_story_5082_50820401_27_dialog_content = "Justo ahora, yo...",
  ui_story_5082_50820401_28_dialog_content = "Je, ¿tienes miedo de tus propios sueños eh? Parece que definitivamente necesitas más entrenamiento.",
  ui_story_5082_50820401_29_dialog_content = "Miau... Sé todo sobre cómo conseguir un sueño reparador. ¡Deberías intentar aprender de mí alguna vez!",
  ui_story_5082_50820401_30_dialog_content = "Eso no se sintió como un sueño hace un momento...",
  ui_story_5082_50820401_31_dialog_content = "¡Tengo que ir a buscarlo!",
  ui_story_5082_50820401_32_dialog_content = "¡Oye, ¿a dónde crees que vas?! Al menos espera por nosotros—",
  ui_story_5082_50820401_33_dialog_content = "*bostezo* Parece que ni el Gran Mariscal ni el Oficial Vivian están por aquí.",
  ui_story_5082_50820401_34_dialog_content = "Aunque apenas puedo sentirlo, puedo decir que está en alguna parte en esta dirección. Las ruinas donde se canceló el ejercicio de ayer...",
  ui_story_5082_50820401_35_dialog_content = "¿Eh? Escucho voces más adelante...",
  ui_story_5082_50820401_36_dialog_content = "¿PlayerName? ¿No te dije que esta es una zona restringida?",
  ui_story_5082_50820401_37_dialog_content = "Está bien, Vivian. PlayerName no se apresuraría aquí si no fuera por una buena razón.",
  ui_story_5082_50820401_38_dialog_content = "Reinhardt, Vivian... Yo...",
  ui_story_5082_50820401_39_dialog_content = "Esta es una reunión bastante grande, y en medio de la noche, nada menos. ¿Estamos decidiendo si reiniciar o no el ejercicio de entrenamiento?",
  ui_story_5082_50820401_40_dialog_content = "Preferiría estar durmiendo, pero no si eso significa perderme algo importante.",
  ui_story_5082_50820401_41_dialog_content = "¡Siento la presencia de un Coloso en algún lugar cercano!",
  ui_story_5082_50820401_42_dialog_content = "!",
  ui_story_5082_50820401_43_dialog_content = "... Lo sabía.",
  ui_story_5082_50820401_44_dialog_content = "Dime, ¿no es esta la base de investigación donde se realizaron los experimentos del navegador de reserva, verdad?",
  ui_story_5082_50820401_45_dialog_content = "Base de investigación... ¿te refieres a la que explotó hace todos esos años?",
  ui_story_5082_50820401_46_dialog_content = "... Recuerdo que Vice dijo que participó en algo llamado \"Proyecto: Navegador\".",
  ui_story_5082_50820401_47_dialog_content = "Pero aparentemente el proyecto fue un fracaso, y Vice perdió la mayoría de sus recuerdos de antes y después de ese tiempo.",
  ui_story_5082_50820401_48_dialog_content = "¿Estaba Illumina intentando entrenar a alguien para ser el Navigator de Spearhead?",
  ui_story_5082_50820401_49_dialog_content = "Espera... Vice debió haber sido una pequeña niña cuando eso sucedió, ¿verdad?",
  ui_story_5082_50820401_50_dialog_content = "Todos ustedes tienen razón. Durante la Crisis de Darkover, Illumina lanzó ese programa para mejorar nuestras posibilidades de un futuro más brillante.",
  ui_story_5082_50820401_51_dialog_content = "Pero perdimos a demasiadas personas y la base de investigación quedó enterrada bajo tierra. Nuestros registros del incidente también son pocos y distantes...",
  ui_story_5082_50820401_52_dialog_content = "Ese programa trajo vergüenza a toda Illumina y para mí... No poder realizar una investigación de seguimiento a pesar de mi participación en el programa fue aún más vergonzoso.",
  ui_story_5082_50820401_53_dialog_content = "... ¿Eso significa que participaste en el experimento junto con Vice?",
  ui_story_5082_50820401_54_dialog_content = "No. Fui yo quien lo destruyó.",
  ui_story_5082_50820401_55_dialog_content = "...",
  ui_story_5082_50820401_56_dialog_content = "Dijeron que rescaté a Vice, pero para decir la verdad, nada de eso me pareció especialmente real.",
  ui_story_5082_50820401_57_dialog_content = "Y así es como me sentí hasta la batalla de ayer con Barton. Cuando peleamos, los recuerdos comenzaron a surgir en mi mente...",
  ui_story_5082_50820401_58_dialog_content = "Sentí que había un secreto enterrado en algún lugar aquí, así que vine a verlo por mí mismo.",
  ui_story_5082_50820401_59_dialog_content = "Lo que dijiste justo ahora confirmó mis sospechas, PlayerName.",
  ui_story_5082_50820401_60_dialog_content = "Ese Coloso nunca fue movido de este lugar.",
  ui_story_5082_50820401_61_dialog_content = "—Está justo debajo de nuestros pies.",
  ui_story_5082_50820401_62_dialog_content = "... Si realmente ese es el caso, entonces necesito ir a verlo.",
  ui_story_5082_50820401_63_dialog_content = "Vice nunca lo dijo, pero estoy seguro de que a cualquiera le molestaría si perdiera sus recuerdos.",
  ui_story_5082_50820401_64_dialog_content = "Ella me ha ayudado tanto desde que nos conocimos. Solo es correcto que yo haga algo por ella.",
  ui_story_5082_50820401_65_dialog_content = "Como esta es una zona restringida, permitirte entrar sería una violación de las regulaciones de Illumina.",
  ui_story_5082_50820401_66_dialog_content = "Pero-",
  ui_story_5082_50820401_67_dialog_content = "Sin embargo, el Gran Mariscal también está presente.",
  ui_story_5082_50820401_68_dialog_content = "Con su consentimiento, se te puede conceder permiso para entrar.",
  ui_story_5082_50820401_69_dialog_content = "Ya planeaba ir allí de todos modos. No me importaría si PlayerName me acompañara.",
  ui_story_5082_50820401_70_dialog_content = "Pero tienes que prometerme algo.",
  ui_story_5082_50820401_71_dialog_content = "Puede ser diferente a lo que tú sabes, pero según siglos de informes de inteligencia de Illumina—",
  ui_story_5082_50820401_72_dialog_content = "De los Colossus que has encontrado hasta ahora, este podría ser mucho más hostil de lo que esperas.",
  ui_story_5082_50820401_73_dialog_content = "Estoy seguro de que no tenía muchas cosas agradables que decir sobre Illumina cuando se puso en contacto contigo.",
  ui_story_5082_50820401_74_dialog_content = "... Eso es cierto.",
  ui_story_5082_50820401_75_dialog_content = "Después del incidente con el Ingeniero, juré que no correría el riesgo de dejarte percibir algo peligroso como eso nunca más.",
  ui_story_5082_50820401_76_dialog_content = "Especialmente cuando el peligro está dirigido a Illumina.",
  ui_story_5082_50820401_77_dialog_content = "Pero decirte que no uses tus únicos poderes psíquicos no es diferente a decirte que no respires.",
  ui_story_5082_50820401_78_dialog_content = "Todo lo que pido es que me digas cuando sientas algo en el momento en que sucede.",
  ui_story_5082_50820401_79_dialog_content = "¿Entonces también puedo hacer una solicitud?",
  ui_story_5082_50820401_80_dialog_content = "Adelante, te escucho.",
  ui_story_5082_50820401_81_dialog_content = "No intentaré ocultar nada de lo que percibo, pero me gustaría que todos siguieran la misma regla.",
  ui_story_5082_50820401_82_dialog_content = "Ya sea que algo parezca extraño, o si te sientes un poco raro...",
  ui_story_5082_50820401_83_dialog_content = "Incluso si crees que no es gran cosa, por favor informa al grupo de inmediato. De esa manera, podemos trabajar en una solución juntos.",
  ui_story_5082_50820401_84_dialog_content = "Has madurado mucho más desde que nos conocimos por primera vez.",
  ui_story_5082_50820401_85_dialog_content = "Acuerdo.",
  ui_story_5082_50820401_86_dialog_content = "No me importa particularmente este incidente, pero tuvo un efecto enorme y duradero en Illumina. Si vas a investigarlo, entonces cuéntame dentro.",
  ui_story_5082_50820401_87_dialog_content = "Para ser honesto, realmente no me apetece unirme a todos.",
  ui_story_5082_50820401_88_dialog_content = "Pero estas ruinas esconden algo que quiero saber, así que supongo que también me uniré.",
  ui_story_5082_50820401_89_dialog_content = "Da la casualidad de que vamos en la misma dirección, ¡así que no esperes que ayude mucho!",
  ui_story_5082_50820401_90_dialog_content = "¿Qué vamos a hacer contigo, Philyshy...",
  ui_story_5082_50820401_91_dialog_content = "¡Muy bien, basta de rodeos. Yo guiaré el camino, ahora vamos a irnos!",
  ui_story_5082_50820401_92_dialog_content = "Creo que debería explorar un camino primero, Barton. No te preocupes, no intentaré detectar al Coloso.",
  ui_story_5082_50820401_93_dialog_content = "Solo echaré un vistazo a nuestros alrededores para asegurarme de que estén seguros antes de continuar.",
  ui_story_5082_50820401_94_dialog_content = "*Tos* El espacio debajo de nosotros es enorme, pero en su mayoría son solo ruinas...",
  ui_story_5082_50820401_95_dialog_content = "<color=#e8d9bb>Desmoronarse...</color>",
  ui_story_5082_50820401_96_dialog_content = "¡Vaya! Casi me tropiezo justo ahora.",
  ui_story_5082_50820401_97_dialog_content = "El suelo está cubierto de cables. Cuidado con vuestro paso, todos.",
  ui_story_5082_50820401_98_dialog_content = "<color=#e8d9bb>Bzzz—</color>",
  ui_story_5082_50820401_99_dialog_content = "¿Qué es ese sonido?",
  ui_story_5082_50820401_100_dialog_content = "¡Miau! ¡Algo está volando hacia nosotros!",
  ui_story_5082_50820401_101_dialog_content = "Zumbido—",
  ui_story_5082_50820401_102_dialog_content = "¡Esquívalo, PlayerName!",
  ui_story_5082_50820401_103_dialog_content = "—!",
  ui_story_5082_50820401_104_dialog_content = "...",
  ui_story_5082_50820401_105_dialog_content = "PlayerName? PlayerName!",
  ui_story_5082_50820401_106_dialog_content = "Creo que escucho a alguien gritando mi nombre.",
  ui_story_5082_50820501_1_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820501_2_dialog_content = "¿Fue eso... una corneta?",
  ui_story_5082_50820501_3_dialog_content = "Juraría que escuché a una chica gritando justo ahora... ¿Eh?",
  ui_story_5082_50820501_4_dialog_content = "¿Es esto... una academia militar?",
  ui_story_5082_50820501_5_dialog_content = "¡Vaya! ¡Reinhardt gana de nuevo!!",
  ui_story_5082_50820501_6_dialog_content = "¿Reinhardt?",
  ui_story_5082_50820501_7_dialog_content = "¿Alguien más siente como dar un paso al frente?",
  ui_story_5082_50820501_8_dialog_content = "Dale un descanso, Reinhardt. Ya has vencido a todos en toda la escuela; nadie es lo suficientemente tonto como para desafiarte de nuevo.",
  ui_story_5082_50820501_9_dialog_content = "Sí, pero aún no te has rendido, ¿verdad?",
  ui_story_5082_50820501_10_dialog_content = "Simplemente no tengo ganas de vencerte en algo tan estúpido como la lucha de brazos.",
  ui_story_5082_50820501_11_dialog_content = "Nuestro instructor dice que haremos un circuito de obstáculos después de la clase de hoy. Ese será el momento en que finalmente te pondré en tu lugar.",
  ui_story_5082_50820501_12_dialog_content = "Reinhardt volvió a ocupar el primer lugar en la carrera de obstáculos! ¡La persona en segundo lugar fue más de diez segundos más lenta también!",
  ui_story_5082_50820501_13_dialog_content = "Eso apenas es sorprendente. ¿Cuándo NO ha estado ella en primer lugar?",
  ui_story_5082_50820501_14_dialog_content = "Entonces, ¿quién quedó en segundo lugar? No me digas que fue Wrath otra vez?",
  ui_story_5082_50820501_15_dialog_content = "¡Seguro que lo fue!",
  ui_story_5082_50820501_16_dialog_content = "Siempre ha sido así desde que me uní a la academia y me convertí en su estudiante. Cada concurso termina exactamente igual para ellos.",
  ui_story_5082_50820501_17_dialog_content = "Honestamente, me siento tan inútil en comparación con ellos.",
  ui_story_5082_50820501_18_dialog_content = "Colonia, Vaughn.",
  ui_story_5082_50820501_19_dialog_content = "¿Estoy escuchando cosas, o Reinhardt acaba de decir nuestros nombres?",
  ui_story_5082_50820501_20_dialog_content = "Estoy bastante seguro de que también lo escuché.",
  ui_story_5082_50820501_21_dialog_content = "Eso es porque los estoy llamando, ¡ahora vengan aquí!",
  ui_story_5082_50820501_22_dialog_content = "¿P-Por qué...",
  ui_story_5082_50820501_23_dialog_content = "¿Por qué Reinhardt sabe nuestros nombres?!",
  ui_story_5082_50820501_24_dialog_content = "Estaba viendo la batalla simulada de tu clase hace un momento.",
  ui_story_5082_50820501_25_dialog_content = "Colonia, tus habilidades logísticas son algunas de las más efectivas que he visto en nuestro año.",
  ui_story_5082_50820501_26_dialog_content = "Y Vaughn, tu velocidad de reacción tampoco es para reírse.",
  ui_story_5082_50820501_27_dialog_content = "Así que pensé que vendría a saludar. Si alguna vez surge la oportunidad, me gustaría mucho hacer equipo con ustedes dos.",
  ui_story_5082_50820501_28_dialog_content = "¡Reinhardt! ¡El instructor nos ordenó reunirnos!",
  ui_story_5082_50820501_29_dialog_content = "¡Tengo que irme! Los veré por ahí.",
  ui_story_5082_50820501_30_dialog_content = "Reinhardt... dijo que estaba impresionada con nosotros.",
  ui_story_5082_50820501_31_dialog_content = "Oye... ¿Deberíamos correr unas vueltas alrededor de la pista?",
  ui_story_5082_50820501_32_dialog_content = "¡Sí! ¡Hagámoslo! ¡Ahora mismo!",
  ui_story_5082_50820501_33_dialog_content = "¡Entra en formación!",
  ui_story_5082_50820501_34_dialog_content = "Todos han sido asignados a una misión urgente.",
  ui_story_5082_50820501_35_dialog_content = "Recientemente, varias Subciudades, incluyendo las Subciudades 38, 42 y 59, han sido atacadas simultáneamente por un nuevo tipo de Eclipsite.",
  ui_story_5082_50820501_36_dialog_content = "Estos nuevos Eclipsites no son particularmente poderosos, pero compensan con su abrumador número, que sigue creciendo. ¡Las condiciones de vida y la productividad de estas Subciudades ya se han visto seriamente afectadas!",
  ui_story_5082_50820501_37_dialog_content = "Serán divididos en tres pequeños equipos y enviados a las siguientes Subciudades para proporcionar apoyo.",
  ui_story_5082_50820501_38_dialog_content = "¡Sí señor!",
  ui_story_5082_50820501_39_dialog_content = "...",
  ui_story_5082_50820501_40_dialog_content = "<color=#e8d9bb>Después de que terminó la crisis</color>",
  ui_story_5082_50820501_41_dialog_content = "¡Reinhardt!",
  ui_story_5082_50820501_42_dialog_content = "¡Tus órdenes eran llevar a tu equipo a Subciudad 42 y proporcionar refuerzos! ¿Qué estás haciendo en Subciudad 28?!",
  ui_story_5082_50820501_43_dialog_content = "¡Señor! Cuando nos dieron nuestras asignaciones, noté que las Subciudades en cuestión estaban relativamente distantes entre sí.",
  ui_story_5082_50820501_44_dialog_content = "Para que el mismo tipo de Eclipsite aparezca en cada Subciudad al mismo tiempo, debe significar que hay algún tipo de conexión entre ellos.",
  ui_story_5082_50820501_45_dialog_content = "Después de llegar a Subciudad 42 y despachar a los Eclipsites allí, determiné que eran extremadamente vulnerables al ataque.",
  ui_story_5082_50820501_46_dialog_content = "Sin embargo, descubrí la presencia de un Eclipsite único en medio de ellos, ¡uno que se mueve rápidamente y parece ser capaz de regenerarse rápidamente!",
  ui_story_5082_50820501_47_dialog_content = "Tras una observación más detallada, confirmé que este tipo de Eclipsite comparte múltiples características con las plantas esporádicas.",
  ui_story_5082_50820501_48_dialog_content = "Y después de cruzar referencias con mi mapa, me di cuenta de que todas estas Subciudades están directamente conectadas por ferrocarriles, con la Subciudad 28 en su centro.",
  ui_story_5082_50820501_49_dialog_content = "Esto me lleva a creer que estos Eclipsites se propagaron a cada una de las Subciudades afectadas a través de nuestros carros de ferrocarril, y que el cuerpo principal se encuentra en algún lugar de Subciudad 28.",
  ui_story_5082_50820501_50_dialog_content = "¡Así que traje a mi equipo aquí para cazar y destruir la fuente de la invasión!",
  ui_story_5082_50820501_51_dialog_content = "Después, recibí confirmación de las otras Subciudades de que los Eclipsites ya no estaban aumentando en número.",
  ui_story_5082_50820501_52_dialog_content = "... ¡Tú descubriste! ¡Tú determinaste! ¡Tú observaste!",
  ui_story_5082_50820501_53_dialog_content = "¡No te estoy preguntando sobre lo que has hecho, Reinhardt! ¡Te estoy preguntando por qué lo hiciste!!",
  ui_story_5082_50820501_54_dialog_content = "¿Crees que tus superiores son un montón de tontos? ¿Piensas que eres el soldado más inteligente de Illumina solo porque descubriste la verdad?!",
  ui_story_5082_50820501_55_dialog_content = "¡Abandonando tu misión, actuando por tu cuenta e ignorando las órdenes urgentes de retirada! ¿Y te llamas soldado?",
  ui_story_5082_50820501_56_dialog_content = "Soy consciente de las consecuencias de mis acciones y estoy preparado para aceptar cualquier castigo. Sin embargo, sigo creyendo que erradicar la fuente de la invasión de Eclipsites lo más pronto posible fue la mejor opción de acción!",
  ui_story_5082_50820501_57_dialog_content = "¡¡¡Vete al infierno!!!",
  ui_story_5082_50820501_58_dialog_content = "!",
  ui_story_5082_50820501_59_dialog_content = "¿Me estabas esperando o algo así?",
  ui_story_5082_50820501_60_dialog_content = "Solo vine a entregar mi informe de trabajo al instructor.",
  ui_story_5082_50820501_61_dialog_content = "... ¿Estás bien?",
  ui_story_5082_50820501_62_dialog_content = "¿Por qué no lo estaría? Solo me regañaron, eso es todo.",
  ui_story_5082_50820501_63_dialog_content = "Desearía saber por qué el instructor la tenía contra mí.",
  ui_story_5082_50820501_64_dialog_content = "¿Eso es realmente lo que tienes en mente? No importa.",
  ui_story_5082_50820501_65_dialog_content = "Al final del día, ambos fuimos enviados a las Subciudades para proporcionar refuerzos, pero no logré descubrir la verdad detrás de esos Eclipsites. Parece que ganas de nuevo, Reinhardt.",
  ui_story_5082_50820501_66_dialog_content = "¡Pero recuerda lo que te digo! ¡No perderé contra ti la próxima vez!",
  ui_story_5082_50820501_67_dialog_content = "Seguro.",
  ui_story_5082_50820501_68_dialog_content = "... ¿Qué fue eso? Te desafío, ¿y eso es todo lo que tienes que decir?",
  ui_story_5082_50820501_69_dialog_content = "Me desafías todos los días, ¿no es así?",
  ui_story_5082_50820501_70_dialog_content = "Por eso siempre estoy preparado para cualquier cosa.",
  ui_story_5082_50820501_71_dialog_content = "¡No... No te atrevas a dar por sentado mis desafíos!",
  ui_story_5082_50820501_72_dialog_content = "Eres la única persona digna de ser mi rival, así que hasta que te derrote, ¡no tienes permitido perder contra nadie más!",
  ui_story_5082_50820501_73_dialog_content = "Jaja, haré lo mejor que pueda.",
  ui_story_5082_50820501_74_dialog_content = "(Así que esto ocurrió en el pasado.)",
  ui_story_5082_50820501_75_dialog_content = "(Reinhardt y Wrath eran muy cercanos durante sus días de academia...)",
  ui_story_5082_50820501_76_dialog_content = "¡Capitán! Es una emergencia—",
  ui_story_5082_50820501_77_dialog_content = "(La escena está cambiando de nuevo...)",
  ui_story_5082_50820501_78_dialog_content = "¿Eh...?",
  ui_story_5082_50820501_79_dialog_content = "Detener-!",
  ui_story_5082_50820501_80_dialog_content = "El entrenamiento de hoy ha terminado, ¡ahora regresa a tu cuartel! El toque de queda está en efecto, ¡así que no salgas después de oscurecer!",
  ui_story_5082_50820501_81_dialog_content = "Uf, me alegro de que haya terminado. Estoy vencido...",
  ui_story_5082_50820501_82_dialog_content = "Todavía es un poco temprano, ¿no? Normalmente, el instructor agrega entrenamiento extra si terminamos tan pronto.",
  ui_story_5082_50820501_83_dialog_content = "¿A quién le importa? ¡Esto solo significa que tenemos más tiempo para relajarnos! ¿Verdad, Reinhardt?",
  ui_story_5082_50820501_84_dialog_content = "... ¿Reinhardt?",
  ui_story_5082_50820501_85_dialog_content = "¡Oye! ¿A dónde vas?",
  ui_story_5082_50820501_86_dialog_content = "Para meterme en más problemas.",
  ui_story_5082_50820501_87_dialog_content = "Entonces yo también voy.",
  ui_story_5082_50820501_88_dialog_content = "¿No escuchaste lo que acabo de decir?",
  ui_story_5082_50820501_89_dialog_content = "¿Me estás subestimando?",
  ui_story_5082_50820501_90_dialog_content = "Si realmente fueras tan imprudente e inconsiderado, no te consideraría mi rival sin importar cuán fuerte fueras.",
  ui_story_5082_50820501_91_dialog_content = "El instructor te estaba mirando con furia hace un momento, y aún así estás empeñado en escabullirte. ¿Por qué? ¿Qué descubriste?",
  ui_story_5082_50820501_92_dialog_content = "Una invasión de Eclipsite.",
  ui_story_5082_50820501_93_dialog_content = "¡¿Qué?!",
  ui_story_5082_50820501_94_dialog_content = "¡Rooooooor!",
  ui_story_5082_50820501_95_dialog_content = "¡Comandante! Los Eclipsites siguen llegando, pero no tenemos suficientes soldados para contenerlos. Solicitando—",
  ui_story_5082_50820501_96_dialog_content = "¡Manténganlos a raya incluso si les cuesta la vida!",
  ui_story_5082_50820501_97_dialog_content = "¿De dónde en el mundo vinieron todos estos Eclipsites—",
  ui_story_5082_50820501_98_dialog_content = "¡Rugido!",
  ui_story_5082_50820501_99_dialog_content = "Ah—",
  ui_story_5082_50820501_100_dialog_content = "¡Mantenga la línea!",
  ui_story_5082_50820501_101_dialog_content = "¡Malditos monstruos sucios!",
  ui_story_5082_50820501_102_dialog_content = "¡Avance todo!",
  ui_story_5082_50820501_103_dialog_content = "¡Golpea! ¡Richthofen!",
  ui_story_5082_50820501_104_dialog_content = "¡¿Qué estás haciendo aquí?!",
  ui_story_5082_50820501_105_dialog_content = "Como dije, ¡no voy a perder contra ti!",
  ui_story_5082_50820501_106_dialog_content = "Graaah...",
  ui_story_5082_50820501_107_dialog_content = "¿Estudiantes?",
  ui_story_5082_50820501_108_dialog_content = "Estudiante de la Academia Militar de Illumina Reinhardt, ¡reportándose para el deber de apoyo!",
  ui_story_5082_50820501_109_dialog_content = "Estudiante de la Academia Militar Illumina Wrath, ¡reportándose para el deber de apoyo!",
  ui_story_5082_50820501_110_dialog_content = "¡Deja de hacer tonterías y regresa!",
  ui_story_5082_50820501_111_dialog_content = "Personalmente informaré a mi instructor después de que esto termine, pero como ciudadano de Illumina, ¡me niego a quedarme de brazos cruzados mientras los Eclipsites invaden nuestro hogar!",
  ui_story_5082_50820501_112_dialog_content = "¡Por favor, asigname a las defensas del flanco izquierdo!",
  ui_story_5082_50820501_113_dialog_content = "¡Y por favor asígneme al correcto!",
  ui_story_5082_50820501_114_dialog_content = "¿Ustedes dos? ¿Es esto algún tipo de broma?!",
  ui_story_5082_50820501_115_dialog_content = "Podemos ganar, lo prometo.",
  ui_story_5082_50820501_116_dialog_content = "Además, no somos los únicos aquí para ayudar.",
  ui_story_5082_50820501_117_dialog_content = "¡Dos Eclipsites están intentando emboscarnos desde un pozo a la una en punto! ¡Déjalos a mi cargo!",
  ui_story_5082_50820501_118_dialog_content = "¡La Legión Médica se encargará de los heridos graves! ¡Administraremos primeros auxilios a las lesiones leves aquí!",
  ui_story_5082_50820501_119_dialog_content = "Permítanme presentar a mis compañeros de clase y camaradas de armas: Vaughn y Cologne.",
  ui_story_5082_50820501_120_dialog_content = "Parece que esta es nuestra oportunidad de finalmente unirnos, Reinhardt!",
  ui_story_5082_50820501_121_dialog_content = "Perdónanos, comandante, pero cada soldado tiene el deber de defender a Illumina, ¡incluso los soldados en entrenamiento!",
  ui_story_5082_50820501_122_dialog_content = "Jaja, guarda tus disculpas para más tarde!",
  ui_story_5082_50820501_123_dialog_content = "¡Toma tus armas y prepárate para enfrentarte a los Eclipsites!",
  ui_story_5082_50820501_124_dialog_content = "¡Entendido!",
  ui_story_5082_50820501_125_dialog_content = "¿Y exactamente cuándo te ascendieron a comandante, eh?!",
  ui_story_5082_50820501_126_dialog_content = "... Reinhardt.",
  ui_story_5082_50820501_127_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5082_50820501_128_dialog_content = "¡Formen y comiencen a entrenar!",
  ui_story_5082_50820501_129_dialog_content = "¡Sí señor!",
  ui_story_5082_50820501_130_dialog_content = "De ninguna manera. ¿El instructor realmente nos está dejando escapar después del desastre de ayer?",
  ui_story_5082_50820501_131_dialog_content = "Reinhardt y Wrath tampoco parecen estar en problemas, pero eso solo me pone aún más nervioso...",
  ui_story_5082_50820501_132_dialog_content = "¡Espera, mira! ¿No es ese el Comandante de la 1ra Legión? ¿Qué está haciendo aquí?!",
  ui_story_5082_50820501_133_dialog_content = "Estudiante de la Academia Reinhardt! ¡Retírate e informa en la oficina de tu instructor!",
  ui_story_5082_50820501_134_dialog_content = "¡Sí señor!",
  ui_story_5082_50820501_135_dialog_content = "...",
  ui_story_5082_50820501_136_dialog_content = "<color=#e8d9bb>Sala de Guerra N° 3</color>",
  ui_story_5082_50820501_137_dialog_content = "¡Saludos, Comandante!",
  ui_story_5082_50820501_138_dialog_content = "Debido a tu sobresaliente desempeño individual, hemos preparado una serie de experimentos de entrenamiento especiales solo para ti.",
  ui_story_5082_50820501_139_dialog_content = "¡Rugido!",
  ui_story_5082_50820501_140_dialog_content = "Estos Eclipsites sujetos de prueba son una parte crucial del entrenamiento.",
  ui_story_5082_50820501_141_dialog_content = "En unos momentos, los liberaré en el área de combate. Me gustaría que los combatieras usando todo tu poder.",
  ui_story_5082_50820501_142_dialog_content = "Tch... Estos tipos golpean bastante fuerte.",
  ui_story_5082_50820501_143_dialog_content = "Los Eclipsites a los que te enfrentas actualmente son los especímenes más débiles en el experimento.",
  ui_story_5082_50820501_144_dialog_content = "Este entrenamiento está diseñado para convertirte en el soldado más poderoso de Illumina. Si no puedes derrotarlos, tendremos que reconsiderar tu candidatura para el programa.",
  ui_story_5082_50820501_145_dialog_content = "¿El soldado más poderoso de Illumina, eh? Je... ¿Quién dijo que no podía derrotarlos?!",
  ui_story_5082_50820501_146_dialog_content = "¡Vamos de nuevo!",
  ui_story_5082_50820502_1_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50820502_2_dialog_content = "¿¡Llamas a eso un puñetazo?! ¡Deja de contenerse ya!",
  ui_story_5082_50820502_3_dialog_content = "Jajaja, lo siento. Vamos de nuevo.",
  ui_story_5082_50820502_4_dialog_content = "Eres un... Espera, ¿qué le pasó a tus manos?!",
  ui_story_5082_50820502_5_dialog_content = "Es de ayer—",
  ui_story_5082_50820502_6_dialog_content = "¡Estudiante de la Academia Reinhardt! ¡Retírate e informa en la instalación de entrenamiento especial!",
  ui_story_5082_50820502_7_dialog_content = "¡Sí señor!",
  ui_story_5082_50820502_8_dialog_content = "¡Instructor! Las manos de Reinhardt están demasiado heridas para continuar con el entrenamiento. ¡Por favor, déle un día para recuperarse!",
  ui_story_5082_50820502_9_dialog_content = "Estudiante de la Academia Reinhardt! ¡Informe en la instalación de entrenamiento especial!",
  ui_story_5082_50820502_10_dialog_content = "Instructor—",
  ui_story_5082_50820502_11_dialog_content = "Wrath.",
  ui_story_5082_50820502_12_dialog_content = "¡Instructor! Por favor, disculpe la interrupción, pero ¿cuánto tiempo más continuará el entrenamiento especial de Reinhardt?",
  ui_story_5082_50820502_13_dialog_content = "Un soldado jura cumplir sus órdenes. ¡Ella continuará con su entrenamiento tanto tiempo como sus órdenes lo dicten!",
  ui_story_5082_50820502_14_dialog_content = "... Entendido, señor.",
  ui_story_5082_50820502_15_dialog_content = "(Sus manos... ¿Podrían ser estas las \"viejas heridas\" que Reinhardt mencionó antes?)",
  ui_story_5082_50820502_16_dialog_content = "(No importa cuán especial sea el entrenamiento, no vale la pena hacerle esto a tu propio cuerpo.)",
  ui_story_5082_50820502_17_dialog_content = "(Los Eclipsites no les importará que te duelan las manos.)",
  ui_story_5082_50820502_18_dialog_content = "(¿Es esa la voz del instructor?)",
  ui_story_5082_50820502_19_dialog_content = "(... La academia recibe su cuota de alborotadores cada año, pero esta es la primera vez que veo a un estudiante tan prometedor desobedecer órdenes con total impunidad...)",
  ui_story_5082_50820502_20_dialog_content = "(¡Mereces ser puesto en tu lugar más que nadie! Si te encanta tanto luchar contra los Eclipsites, te dejaremos luchar contra ellos hasta que te canses!)",
  ui_story_5082_50820502_21_dialog_content = "(¡Este tipo es terrible!)",
  ui_story_5082_50820502_22_dialog_content = "—!",
  ui_story_5082_50820502_23_dialog_content = "(Es el grito de esa niña de nuevo.)",
  ui_story_5082_50820502_24_dialog_content = "(¿Quién podría ser ella—)",
  ui_story_5082_50820502_25_dialog_content = "!",
  ui_story_5082_50820601_1_dialog_content = "¡Whoa!",
  ui_story_5082_50820601_2_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5082_50820601_3_dialog_content = "Una roca...",
  ui_story_5082_50820601_4_dialog_content = "¡Eso estuvo cerca! Si PlayerName lo hubiera notado un segundo antes, ¡ahora mismo todos estaríamos tan aplastados como panqueques!",
  ui_story_5082_50820601_5_dialog_content = "Iré a explorar más adelante. El resto de ustedes esperen aquí por mí.",
  ui_story_5082_50820601_6_dialog_content = "Iré contigo.",
  ui_story_5082_50820601_7_dialog_content = "¿Qué pasa, PlayerName? Parece que tienes algo que decir.",
  ui_story_5082_50820601_8_dialog_content = "Esa roca de hace un momento... No la noté en absoluto.",
  ui_story_5082_50820601_9_dialog_content = "Sentí a una chica justo ahora... O al menos creo que lo hice. De cualquier manera, me asustó hasta el punto de saltar a un lado.",
  ui_story_5082_50820601_10_dialog_content = "¿Ella... Estaba brillando en rojo, por casualidad?",
  ui_story_5082_50820601_11_dialog_content = "¿Cómo lo supiste?",
  ui_story_5082_50820601_12_dialog_content = "Porque la vi en mis recuerdos ayer.",
  ui_story_5082_50820601_13_dialog_content = "...",
  ui_story_5082_50820601_14_dialog_content = "Has tenido algo que decirme desde ayer, ¿verdad?",
  ui_story_5082_50820601_15_dialog_content = "No solo yo.",
  ui_story_5082_50820601_16_dialog_content = "Barton, Philyshy... Todos están preocupados por ti.",
  ui_story_5082_50820601_17_dialog_content = "¿Es realmente tan obvio que algo me pasa?",
  ui_story_5082_50820601_18_dialog_content = "Aprecio la preocupación, pero no hay necesidad de que te preocupes así, PlayerName.",
  ui_story_5082_50820601_19_dialog_content = "No tengo tiempo para perder en sentimentalismos, y no es que no pueda contarte lo que pasó tampoco.",
  ui_story_5082_50820601_20_dialog_content = "Durante el entrenamiento de ayer, de repente recordé un montón de cosas de las que no tengo recuerdo.",
  ui_story_5082_50820601_21_dialog_content = "Personas, lugares, emociones... todo se sentía tan desconocido.",
  ui_story_5082_50820601_22_dialog_content = "Desafortunadamente, esos recuerdos pasaron por mi mente tan rápido que no pude decir... Si realmente maté a esa mujer o no.",
  ui_story_5082_50820601_23_dialog_content = "¿L-La disparaste...?! ¿Es este el \"secreto enterrado\" del que hablabas? Entonces ese grito que escuché antes...",
  ui_story_5082_50820601_24_dialog_content = "Los recuerdos aún están demasiado fragmentados para que pueda entenderlos... Ni siquiera puedo recordar su nombre.",
  ui_story_5082_50820601_25_dialog_content = "Lo cual es extraño, considerando que recuerdo a cada una de las personas que asistieron a la academia conmigo.",
  ui_story_5082_50820601_26_dialog_content = "¿La academia? Así es. También tengo algunos recuerdos de tus días de entrenamiento.",
  ui_story_5082_50820601_27_dialog_content = "Pero esa chica nunca apareció en ninguno de ellos.",
  ui_story_5082_50820601_28_dialog_content = "¡Ay! Lo siento, no quise entrometerme en tu pasado de esa manera.",
  ui_story_5082_50820601_29_dialog_content = "Está bien, no me importa particularmente. Aun así, tengo curiosidad por saber qué viste en mis recuerdos.",
  ui_story_5082_50820601_30_dialog_content = "Bueno, hubo una parte en la que estabas luchando en un pulso con gente en el campo de entrenamiento... Y una parte en la que salvaste varias Subciudades desobedeciendo las órdenes de tu comandante...",
  ui_story_5082_50820601_31_dialog_content = "También vi lo que te pasó durante tu \"entrenamiento especial\"...",
  ui_story_5082_50820601_32_dialog_content = "Jaja, supongo que sí recuerdo que todo eso sucedió.",
  ui_story_5082_50820601_33_dialog_content = "Era joven y arrogante en aquel entonces. Pensé que podía resolver cualquier problema por mi cuenta.",
  ui_story_5082_50820601_34_dialog_content = "¿Estás seguro de que no viste a esa chica en ninguna de esas memorias?",
  ui_story_5082_50820601_35_dialog_content = "Estoy seguro...",
  ui_story_5082_50820601_36_dialog_content = "¿Por qué no intentas preguntarle a tu buen amigo Philyshy sobre eso? Después de todo, ¡me ocupo de este tipo de cosas todo el tiempo!",
  ui_story_5082_50820601_37_dialog_content = "Hemos pasado por todo tipo de aventuras juntos, sin embargo, la gente de alguna manera logra olvidarse de Yumi.",
  ui_story_5082_50820601_38_dialog_content = "Creo que la situación de Reinhardt es un poco diferente, Philyshy.",
  ui_story_5082_50820601_39_dialog_content = "Creo que el Comité puede saber más sobre estos recuerdos... Además, me deben muchos favores.",
  ui_story_5082_50820601_40_dialog_content = "Eche un vistazo a esto, Gran Mariscal. Esos extraños robots que nos acaban de atacar ahora se están moviendo en formación.",
  ui_story_5082_50820601_41_dialog_content = "<color=#e8d9bb>Zumbador—</color>",
  ui_story_5082_50820601_42_dialog_content = "Echamos un vistazo al que nos atacó antes. A juzgar por su diseño, parece ser un tipo de droide de combate.",
  ui_story_5082_50820601_43_dialog_content = "Pero lo que realmente es único acerca de su estructura, sin embargo, es que parece capaz de fusionarse con otras máquinas. ¿Me pregunto si estaban investigando este tipo de tecnología aquí?",
  ui_story_5082_50820601_44_dialog_content = "Su patrón de vuelo está totalmente coordinado. Parece que se están adentrando más en las ruinas.",
  ui_story_5082_50820601_45_dialog_content = "Sigámoslos.",
  ui_story_5082_50820601_46_dialog_content = "Exploraré adelante.",
  ui_story_5082_50820601_47_option_content = "Escaneo Psíquico—",
  ui_story_5082_50820601_48_dialog_content = "%^ buscar poder es $!#￥ buscar destrucción... $%^#$#^!$",
  ui_story_5082_50820601_49_dialog_content = "¡Punta de lanza! ¿Estás cerca? Necesito saber más sobre lo que pasó aquí—",
  ui_story_5082_50820601_50_dialog_content = "—!",
  ui_story_5082_50820601_51_dialog_content = "¡Es ella...!",
  ui_story_5082_50820601_52_option_content = "¡Potencia de fuerza!",
  ui_story_5082_50820601_53_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_54_dialog_content = "Ahí está la corneta otra vez.",
  ui_story_5082_50820601_55_dialog_content = "¿Por qué siempre me arrastran a estos recuerdos cada vez que intento hacer contacto con esa chica?",
  ui_story_5082_50820601_56_dialog_content = "Hay Reinhardt y Wrath.",
  ui_story_5082_50820601_57_dialog_content = "Esa fue la corneta. Deberías ir a unirte a ellos en formación.",
  ui_story_5082_50820601_58_dialog_content = "¿Mientras te escapas para más de tu \"entrenamiento especial\"?",
  ui_story_5082_50820601_59_dialog_content = "¿Es ese programa de entrenamiento incluso oficial? ¿O es algo que inventaron solo para ti?",
  ui_story_5082_50820601_60_dialog_content = "Sigues volviendo con heridas frescas todos los días. Ni siquiera los soldados que regresan del frente aparecen con lesiones como las tuyas.",
  ui_story_5082_50820601_61_dialog_content = "... ¡N-No estoy preocupado por ti ni nada! ¡Solo no quiero que nadie interfiera con nuestros desafíos!",
  ui_story_5082_50820601_62_dialog_content = "Estás pensando demasiado en las cosas. Acabo de llevar mi entrenamiento al siguiente nivel, así que todavía me estoy acostumbrando.",
  ui_story_5082_50820601_63_dialog_content = "No existe tal cosa como un entrenamiento inútil. Cualquier habilidad y experiencia que adquiera se sumará a mi propia fuerza.",
  ui_story_5082_50820601_64_dialog_content = "¡Reinhardt! ¿Crees que puedes ignorar tus deberes diarios solo por tu entrenamiento especial?!",
  ui_story_5082_50820601_65_dialog_content = "¡Bueno, no en mi reloj, ahora dame diez vueltas más!",
  ui_story_5082_50820601_66_dialog_content = "¡Instructor, por favor! ¡Reinhardt está demasiado agotada para seguir! ¡Ella necesita descansar!",
  ui_story_5082_50820601_67_dialog_content = "¿Han olvidado ambos la primera cosa que les enseñé? ¡Un soldado siempre sigue las órdenes!",
  ui_story_5082_50820601_68_dialog_content = "¡Son cinco vueltas más para ti, Wrath!",
  ui_story_5082_50820601_69_dialog_content = "¡Hazlo diez, señor!",
  ui_story_5082_50820601_70_dialog_content = "No tienes que seguirme a todas partes.",
  ui_story_5082_50820601_71_dialog_content = "\"No existe algo como un entrenamiento inútil\". Tú mismo lo dijiste, ¿no es así?",
  ui_story_5082_50820601_72_dialog_content = "Bien, pero no te estoy agradeciendo por esto.",
  ui_story_5082_50820601_73_dialog_content = "De todos modos, nadie pidió tu disculpa.",
  ui_story_5082_50820601_74_dialog_content = "(Desde entonces, todos los días eran iguales para Reinhardt.)",
  ui_story_5082_50820601_75_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_76_dialog_content = "<color=#e8d9bb>La llamada de la corneta de la mañana.</color>",
  ui_story_5082_50820601_77_dialog_content = "Estudiante de la Academia Reinhardt! ¡Informe en la instalación de entrenamiento especial!",
  ui_story_5082_50820601_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_79_dialog_content = "<color=#e8d9bb>La llamada de la corneta de la tarde.</color>",
  ui_story_5082_50820601_80_dialog_content = "¡Finalmente has vuelto, Reinhardt! Tus manos...",
  ui_story_5082_50820601_81_dialog_content = "Lo siento, estoy un poco cansado así que iré directo a la cama.",
  ui_story_5082_50820601_82_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_83_dialog_content = "Reinhardt, listo para el deber.",
  ui_story_5082_50820601_84_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_85_dialog_content = "Reinhardt—",
  ui_story_5082_50820601_86_dialog_content = "Ngh... ¿Eh? ¿Necesitas algo...?",
  ui_story_5082_50820601_87_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_88_dialog_content = "(Reinhardt fue directamente de su habitación a la instalación de entrenamiento especial y regresó, solo se detuvo lo suficiente para comer unos bocados de sus raciones.)",
  ui_story_5082_50820601_89_dialog_content = "(Su vida giraba completamente en torno al entrenamiento y al sueño, ambos dictados por el sonido de un clarín.)",
  ui_story_5082_50820601_90_dialog_content = "Hemos recopilado suficientes datos de esta parte del programa, lo que significa que estás listo para la siguiente fase: entrenamiento de fuerza explosiva.",
  ui_story_5082_50820601_91_dialog_content = "Para esta fase de tu entrenamiento, lucharás contra droides de combate que han sido modificados en base a tus atributos específicos.",
  ui_story_5082_50820601_92_dialog_content = "Al enfrentarte a ellos en batalla, sentirás como si estuvieras luchando contra ti mismo.",
  ui_story_5082_50820601_93_dialog_content = "Usa toda tu fuerza para superar tus límites y destruirlos.",
  ui_story_5082_50820601_94_dialog_content = "Entendido.",
  ui_story_5082_50820602_1_dialog_content = "(Duele tanto... Realmente aumentaron la dificultad para este llamado entrenamiento de \"fuerza explosiva\".)",
  ui_story_5082_50820602_2_dialog_content = "Interesante. Sus signos vitales habían desaparecido completamente hace un momento, y sin embargo, fue capaz de recuperar la conciencia y continuar luchando...",
  ui_story_5082_50820602_3_dialog_content = "¿Qué dijiste?",
  ui_story_5082_50820602_4_dialog_content = "Sin duda, un excelente sujeto de prueba. Los datos que hemos recopilado han superado completamente nuestras expectativas.",
  ui_story_5082_50820602_5_dialog_content = "Y mientras que el daño físico a su cuerpo es relativamente alto, todavía está dentro de los parámetros aceptables.",
  ui_story_5082_50820602_6_dialog_content = "Ahora bien, es hora de pasar a la siguiente fase...",
  ui_story_5082_50820602_7_dialog_content = "May ¿Hago una pregunta?",
  ui_story_5082_50820602_8_dialog_content = "Oh, eso es todo por el entrenamiento de hoy. Estás despedido.",
  ui_story_5082_50820602_9_dialog_content = "Teniendo en cuenta nuestros cálculos iniciales...",
  ui_story_5082_50820602_10_dialog_content = "Este entrenamiento especial... ¿Soy el único candidato, o hay otros como yo?",
  ui_story_5082_50820602_11_dialog_content = "Los parámetros necesarios son...",
  ui_story_5082_50820602_12_dialog_content = "...",
  ui_story_5082_50820602_13_dialog_content = "<color=#e8d9bb>Laboratorio Secreto</color>",
  ui_story_5082_50820602_14_dialog_content = "Tus heridas han sido tratadas. Intenta no mojarlas en los próximos días.",
  ui_story_5082_50820602_15_dialog_content = "Prepararé algunos medicamentos para ti antes de que te vayas. Recuerda cambiar tus vendajes todos los días y comer mucho—",
  ui_story_5082_50820602_16_dialog_content = "Puedes ahorrarte todo el discurso de doctor, Helios. No hará ninguna diferencia.",
  ui_story_5082_50820602_17_dialog_content = "Siempre que ella piensa que algo necesita hacerse, lo persigue a toda potencia sin escuchar a nadie más.",
  ui_story_5082_50820602_18_dialog_content = "Negador...",
  ui_story_5082_50820602_19_dialog_content = "Solo estoy diciendo la verdad. Es justo como acordamos encontrarnos aquí una vez a la semana.",
  ui_story_5082_50820602_20_dialog_content = "Y sin embargo, han pasado cuatro semanas completas desde que ella mostró su cara por aquí por última vez.",
  ui_story_5082_50820602_21_dialog_content = "Apenas puede mantener su palabra, y cuando aparece, está inconsciente y cubierta de heridas.",
  ui_story_5082_50820602_22_dialog_content = "Uno de estos días, ¡vas a pagarme por todo el equipo que has roto al desmayarte por todas partes!",
  ui_story_5082_50820602_23_dialog_content = "¡Basta, negador! Intenta no malinterpretar, Reinhardt. Estoy seguro de lo que ella quiere decir...",
  ui_story_5082_50820602_24_dialog_content = "Es que hay muchos materiales inflamables y explosivos por ahí, y ella no quiere que te lastimes.",
  ui_story_5082_50820602_25_dialog_content = "...",
  ui_story_5082_50820602_26_dialog_content = "Lo siento, negador. Sé que te hice preocupar al no aparecer durante tanto tiempo.",
  ui_story_5082_50820602_27_dialog_content = "Me aseguraré de conseguirte equipo de laboratorio completamente nuevo más tarde.",
  ui_story_5082_50820602_28_dialog_content = "...",
  ui_story_5082_50820602_29_dialog_content = "¡Ahí, ves? ¡Problema resuelto!",
  ui_story_5082_50820602_30_dialog_content = "...",
  ui_story_5082_50820602_31_dialog_content = "Mientras estamos en el tema, sé que construimos este laboratorio nosotros mismos...",
  ui_story_5082_50820602_32_dialog_content = "Pero está un poco mal ventilado, ¿no crees? Si Negador quiere continuar con sus experimentos...",
  ui_story_5082_50820602_33_dialog_content = "¿No representa este lugar un riesgo de asfixia?",
  ui_story_5082_50820602_34_dialog_content = "...",
  ui_story_5082_50820602_35_dialog_content = "¿Algo mal, Reinhardt?",
  ui_story_5082_50820602_36_dialog_content = "...",
  ui_story_5082_50820602_37_dialog_content = "... ¿Eh? Lo siento, estaba distraído.",
  ui_story_5082_50820602_38_dialog_content = "Estaba pensando en mi última sesión de entrenamiento. Por alguna razón, de repente sentí como si me estuviera ahogando...",
  ui_story_5082_50820602_39_dialog_content = "¿Estás seguro de que estás bien?",
  ui_story_5082_50820602_40_dialog_content = "¡Por supuesto! Ambos saben lo rápido que me recupero; puede que esté cubierto de heridas ahora mismo, pero se curarán en poco tiempo.",
  ui_story_5082_50820602_41_dialog_content = "He estado pasando por aún más entrenamiento últimamente, por lo que se ha vuelto un poco más difícil presentarme. Intentaré no llegar tarde la próxima vez.",
  ui_story_5082_50820602_42_dialog_content = "Estás evitando el tema, Reinhardt.",
  ui_story_5082_50820602_43_dialog_content = "No te importas a ti mismo, ni nada más por cierto. Todo lo que te importa es tu estúpido entrenamiento.",
  ui_story_5082_50820602_44_dialog_content = "¿Sabes siquiera lo que estás haciendo? El objetivo principal del entrenamiento es aumentar el potencial de combate de un soldado dentro de ciertos límites.",
  ui_story_5082_50820602_45_dialog_content = "No se trata de romper esos límites a expensas de tu propio cuerpo.",
  ui_story_5082_50820602_46_dialog_content = "Finalmente me estás diciendo lo que realmente piensas, Denier. Me alegra.",
  ui_story_5082_50820602_47_dialog_content = "Tú...",
  ui_story_5082_50820602_48_dialog_content = "No te preocupes. Sé lo que estoy haciendo.",
  ui_story_5082_50820602_49_dialog_content = "Después de todo, voy a ser el Gran Mariscal algún día. ¿Cómo se supone que debo liderar todo Illumina si ni siquiera puedo pasar mi entrenamiento en la academia?",
  ui_story_5082_50820602_50_dialog_content = "Hmph. Solo recuerda conseguirme un laboratorio más grande cuando finalmente te conviertas en Gran Mariscal.",
  ui_story_5082_50820602_51_dialog_content = "No soporto ver a los Eclipsites en batalla, así que prefiero convertirme en el mejor investigador de Illumina y estudiarlos desde mi mesa de operaciones.",
  ui_story_5082_50820602_52_dialog_content = "No tengo grandes aspiraciones como ustedes dos. Mientras pueda ser un buen explorador, eso es todo lo que necesito.",
  ui_story_5082_50820602_53_dialog_content = "¿Qué no es genial de eso?",
  ui_story_5082_50820602_54_dialog_content = "Cada soldado juega un papel importante en el poder de Illumina.",
  ui_story_5082_50820602_55_dialog_content = "Ya sean nuestros exploradores, nuestros investigadores o incluso el Gran Mariscal, todos nosotros constituimos la esencia de Illumina.",
  ui_story_5082_50820602_56_dialog_content = "De todos modos, es lo suficientemente difícil para nosotros encontrarnos así, así que hablemos de algo agradable para variar.",
  ui_story_5082_50820602_57_dialog_content = "Preferiblemente algo que podamos poner en nuestras memorias para que todo el mundo lo lea.",
  ui_story_5082_50820602_58_dialog_content = "Un futuro Gran Mariscal, un futuro científico líder y un futuro líder de exploradores—",
  ui_story_5082_50820602_59_dialog_content = "Los mejores camaradas que alguien podría pedir.",
  ui_story_5082_50820700_1_dialog_content = "¿Esos droides de combate están tratando de llevarnos allí abajo? ¡Qué táctica tan pésima!",
  ui_story_5082_50820700_2_dialog_content = "A juzgar por tu expresión, ¿supongo que acabas de sentir algo?",
  ui_story_5082_50820700_3_dialog_content = "Lo hice. Nos estamos acercando cada vez más a esa chica roja brillante.",
  ui_story_5082_50820700_4_dialog_content = "¿Sentiste su presencia de nuevo?",
  ui_story_5082_50820700_5_dialog_content = "Siempre aparece después de ese grito, pero cada vez que intento hacer contacto con ella, veo más y más de...",
  ui_story_5082_50820700_6_dialog_content = "¿Mi pasado?",
  ui_story_5082_50820700_7_dialog_content = "Sí...",
  ui_story_5082_50820700_8_dialog_content = "Esta vez, vi partes de tu entrenamiento de fuerza explosiva.",
  ui_story_5082_50820700_9_dialog_content = "Eso explica tu expresión.",
  ui_story_5082_50820700_10_dialog_content = "Fue... Bastante brutal de ver.",
  ui_story_5082_50820700_11_dialog_content = "Como si estuvieran tratando de hacerte abandonar todo lo que te hace una persona, y convertirte en un arma viviente.",
  ui_story_5082_50820700_12_dialog_content = "Eres una persona amable, PlayerName.",
  ui_story_5082_50820700_13_dialog_content = "Pero la guerra es solo brutal porque no hay muchos lugares donde la bondad pueda existir en el campo de batalla.",
  ui_story_5082_50820700_14_dialog_content = "Ya sea que estés de acuerdo o no, no tenemos más remedio que avanzar a través de esa brutalidad.",
  ui_story_5082_50820700_15_dialog_content = "En aquel entonces, quería convertirme en el soldado más grande y poderoso de la Federación. Naturalmente, lograr eso significaba ponerme a través de un infierno viviente.",
  ui_story_5082_50820700_16_dialog_content = "Pero... ¿No crees que fue injusto? ¿Nunca quisiste renunciar, o incluso defenderte?",
  ui_story_5082_50820700_17_dialog_content = "Por supuesto que lo hice. De hecho, todos los días.",
  ui_story_5082_50820700_18_dialog_content = "Actualmente, Illumina tiene algunos de los mejores líderes en su historia, pero no creo que eso haya ocurrido de la nada. En aquel entonces, ninguno de nosotros lo tenía fácil.",
  ui_story_5082_50820700_19_dialog_content = "Gran Mariscal, ¿todavía recuerdas lo que pasó en las Subciudades 13 y 19?",
  ui_story_5082_50820700_20_dialog_content = "...",
  ui_story_5082_50820700_21_dialog_content = "<color=#e8d9bb>Federación Illumina, Ciudad Gannon, Año 1986</color>",
  ui_story_5082_50820700_22_dialog_content = "¿El comandante aún no ha regresado?",
  ui_story_5082_50820700_23_dialog_content = "¡Aún no, Teniente Reinhardt! ¡El Gran Mariscal solicitó su presencia para una reunión!",
  ui_story_5082_50820700_24_dialog_content = "El comandante ha ordenado mantenerse en espera hasta nuevo aviso. Sin excepciones.",
  ui_story_5082_50820700_25_dialog_content = "¿Otra orden de espera? Pero todos los demás han sido desplegados para defender posiciones clave... ¿Qué diablos está pensando?",
  ui_story_5082_50820700_26_dialog_content = "Las Subciudades 13 y 19 han caído bajo el ataque de los Eclipsites, y todas las comunicaciones han sido cortadas. El único mensajero que logró escapar está solicitando refuerzos.",
  ui_story_5082_50820700_27_dialog_content = "... ¿Dónde exactamente aprendiste eso?",
  ui_story_5082_50820700_28_dialog_content = "Eso no es importante. Lo importante es que dos de nuestras Subciudades están al borde de la destrucción.",
  ui_story_5082_50820700_29_dialog_content = "¡Mientras los Eclipsites están invadiendo nuestro hogar, el Gran Mariscal y el comandante están ocupados jugando con sus pulgares en una reunión!",
  ui_story_5082_50820700_30_dialog_content = "El comandante nos ordenó estar a la espera.",
  ui_story_5082_50820700_31_dialog_content = "Quedarse de brazos cruzados ahora no es diferente a dejarlos morir. Tú, más que nadie, deberías saberlo.",
  ui_story_5082_50820700_32_dialog_content = "...",
  ui_story_5082_50820700_33_dialog_content = "¿Qué pasa? ¿Crees que aún puedes enterrar la cabeza en la arena y fingir ignorancia?",
  ui_story_5082_50820700_34_dialog_content = "Eres igual que esos comandantes pomposos, siempre dispuestos a fingir que todo está bien mientras la sangre no llegue a tus manos.",
  ui_story_5082_50820700_35_dialog_content = "...",
  ui_story_5082_50820700_36_dialog_content = "Teniente Reinhardt? ¿A dónde vas?",
  ui_story_5082_50820700_37_dialog_content = "Solo dando un paseo, eso es todo.",
  ui_story_5082_50820700_38_dialog_content = "<color=#e8d9bb>Las puertas del salón central de reuniones se abren de par en par mientras el Comandante de la 2.ª Legión Pango y el Comandante Adjunto del Batallón Barton salen a la tormenta.</color>",
  ui_story_5082_50820700_39_dialog_content = "Oye, ustedes dos. ¿Supongo que las cosas no salieron muy bien allí?",
  ui_story_5082_50820700_40_dialog_content = "¿Con ese cobarde a cargo de la 1ra Legión? ¡Por supuesto que no!",
  ui_story_5082_50820700_41_dialog_content = "¡No te vayas aún! Estoy aquí para entregar nuevas órdenes.",
  ui_story_5082_50820700_42_dialog_content = "\"Con efecto inmediato, la 2ª Legión debe desplegarse en las Subciudades 13 y 19 para proporcionar refuerzos, con el Teniente Reinhardt y una parte de la 1ra Legión también brindando apoyo.\"",
  ui_story_5082_50820700_43_dialog_content = "Esa es más o menos la esencia de esto. ¿Cómo suena?",
  ui_story_5082_50820700_44_dialog_content = "¿Estás pensando seriamente en falsificar órdenes militares?",
  ui_story_5082_50820700_45_dialog_content = "Si no estás dispuesto a ayudar, entonces lo manejaremos por nuestra cuenta.",
  ui_story_5082_50820700_46_dialog_content = "Puedo enviar a algunos escuadrones de la 1ra Legión; el resto de ellos son más que capaces de defender Gannon City junto con la 3ra Legión.",
  ui_story_5082_50820700_47_dialog_content = "Podemos tener mucho impacto aquí, pero nuestra presencia en esas Ciudades Subterráneas podría marcar la diferencia entre la vida y la muerte.",
  ui_story_5082_50820700_48_dialog_content = "Desafortunadamente, no tengo suficientes soldados para esta misión. Por eso quería pedir ayuda a la 2da Legión.",
  ui_story_5082_50820700_49_dialog_content = "Sabes lo que te sucederá si seguimos adelante con esto, ¿no?",
  ui_story_5082_50820700_50_dialog_content = "Aprecio su preocupación, comandante... Pero salvar vidas sigue siendo más importante para mí.",
  ui_story_5082_50820700_51_dialog_content = "... Eres solo un teniente de bajo rango. ¿Qué te dio la confianza para acercarte a nosotros con una hazaña como esta?",
  ui_story_5082_50820700_52_dialog_content = "Mi creencia es que ninguno de ustedes abandonaría jamás a sus camaradas.",
  ui_story_5082_50820700_53_dialog_content = "¿Todavía no te has decidido, Comandante Pango? Porque de cualquier manera, yo voy con ella.",
  ui_story_5082_50820700_54_dialog_content = "Primero desobedeciste las órdenes y ahora las estás falsificando? Tienes una audacia seria, Reinhardt.",
  ui_story_5082_50820700_55_dialog_content = "¿Eso es todo lo que tienes que decir después de seguirme todo este camino?",
  ui_story_5082_50820700_56_dialog_content = "¡Ja! ¿Crees que simplemente voy a quedarme parado y dejarte hacer lo que quieras?",
  ui_story_5082_50820700_57_dialog_content = "Interesante... Parece que no somos los únicos hartos de los de arriba, ¿verdad? ¡Bien! Ya es hora de que tomemos las decisiones por aquí!",
  ui_story_5082_50820700_58_dialog_content = "Apenas puedo creer que eso realmente sucedió... Aunque eso suena a ti, Reinhardt.",
  ui_story_5082_50820700_59_dialog_content = "Desafortunadamente, todavía no llegamos a tiempo.",
  ui_story_5082_50820700_60_dialog_content = "La Subciudad 13 fue prácticamente aniquilada, y la Subciudad 19 no estaba en mucho mejor estado.",
  ui_story_5082_50820700_61_dialog_content = "Al menos, logramos rescatar a algunas personas... Y aunque muchas personas elogiaron nuestras acciones, también llamamos la atención del Comité.",
  ui_story_5082_50820700_62_dialog_content = "Irónicamente, los resultados de nuestras acciones nos evitaron ser acusados de insubordinación. De hecho, Wrath y yo tuvimos la suerte de ser promovidos a Comandantes de Batallón!",
  ui_story_5082_50820700_63_dialog_content = "La suerte no tiene nada que ver con este tipo de cosas. No en Illumina.",
  ui_story_5082_50820700_64_dialog_content = "El Comandante Pango te había estado entrenando para tomar su lugar durante mucho tiempo. El incidente simplemente lo obligó a adelantar sus planes para ti.",
  ui_story_5082_50820700_65_dialog_content = "Todavía eras muy joven en ese momento, y aún no tenías muchos logros en tu haber. Estoy seguro de que también tuviste tu buena cantidad de dificultades en aquel entonces, ¿no es así??",
  ui_story_5082_50820700_66_dialog_content = "Tú eres el que lo ha tenido más difícil que nadie, Reinhardt. Tus acciones no autorizadas y órdenes falsificadas realmente enfadaron al comandante de la 1ra Legión en ese momento.",
  ui_story_5082_50820700_67_dialog_content = "Te degradaron al rango más bajo posible, despojándote de toda autoridad y enviándote a realizar el entrenamiento básico de nuevo.",
  ui_story_5082_50820700_68_dialog_content = "¡Jajaja! Pero incluso ahora, cada vez que pienso en ti enfrentándote a nuestros superiores por mi causa—",
  ui_story_5082_50820700_69_dialog_content = "Siempre hace que mi sangre bombee, ¡justo como antes! Incluso apareciste con toda una multitud de personas cantando, \"¡Esplendor Illumina\"!",
  ui_story_5082_50820700_70_dialog_content = "¿...?",
  ui_story_5082_50820700_71_dialog_content = "Espera... ¿El que se enfrentó a tus superiores...",
  ui_story_5082_50820700_72_dialog_content = "<color=#e8d9bb>Federación Illumina, Ciudad Gannon, Año 1986</color>",
  ui_story_5082_50820700_73_dialog_content = "¡Oye, Reinhardt! ¡Este equipo de entrenamiento todavía está cubierto de polvo! ¿No has estado holgazaneando, verdad?!",
  ui_story_5082_50820700_74_dialog_content = "Lo limpiaré de nuevo.",
  ui_story_5082_50820700_75_dialog_content = "Mi cantimplora también está vacía. Ve a llenarla mientras estás en ello.",
  ui_story_5082_50820700_76_dialog_content = "De inmediato.",
  ui_story_5082_50820700_77_dialog_content = "Oye... ¿No crees que estamos yendo un poco demasiado lejos con esto?",
  ui_story_5082_50820700_78_dialog_content = "¿De qué estás hablando? Ella falsificó órdenes solo para hacerse un nombre, ¿y aún crees que merece algo mejor?",
  ui_story_5082_50820700_79_dialog_content = "El comandante también está de acuerdo...",
  ui_story_5082_50820700_80_dialog_content = "¡Esos tipos están yendo demasiado por la borda!",
  ui_story_5082_50820700_81_dialog_content = "No te alteres tanto por esto, Colonia. Rompí las reglas y ahora estoy pagando por ello.",
  ui_story_5082_50820700_82_dialog_content = "No vale la pena que te arrastren por mi culpa, así que simplemente déjalo pasar.",
  ui_story_5082_50820700_83_dialog_content = "¿Cómo puedes decir eso, Reinhardt?! Todos conocíamos la verdad cuando acordamos ir contigo!",
  ui_story_5082_50820700_84_dialog_content = "No deberías ser el único castigado, ¡y eso es exactamente lo que le voy a decir al comandante!",
  ui_story_5082_50820700_85_dialog_content = "Oye, ¿no son esos chicos de la 2ª Legión? ¿No recuerdo tener que compartir el campo de entrenamiento con esos perdedores hoy?",
  ui_story_5082_50820700_86_dialog_content = "¿En serio? Qué fastidio.",
  ui_story_5082_50820700_87_dialog_content = "Y ese nuevo todavía es el Comandante del Batallón. Escuché que estaba en liga con Reinhardt cuando todo sucedió.",
  ui_story_5082_50820700_88_dialog_content = "¡Ellos son los que saquearon el almacén de equipo! Mucha gente resultó herida porque querían acaparar toda la gloria!",
  ui_story_5082_50820700_89_dialog_content = "Sí, pero también salvaron Subciudad 19... ¿Crees que los otros rumores sobre ellos son ciertos?",
  ui_story_5082_50820700_90_dialog_content = "Si no lo fueran, el Gran Mariscal ya habría aclarado las cosas. Eso significa que probablemente sea cierto lo que escuchamos sobre ellos ahora.",
  ui_story_5082_50820700_91_dialog_content = "Los rumores están empezando a salirse de control, comandante. ¿No deberíamos hacer algo al respecto?",
  ui_story_5082_50820700_92_dialog_content = "Para nada. Ellos se han buscado esto, después de todo.",
  ui_story_5082_50820700_93_dialog_content = "Nunca pensé que el soldado más prometedor de la 2ª Legión sería así...",
  ui_story_5082_50820700_94_dialog_content = "Dicen que el Comandante Pango lo promovió personalmente, pero al final...",
  ui_story_5082_50820700_95_dialog_content = "...",
  ui_story_5082_50820700_96_dialog_content = "¡Sé que puedes oírlos, Comandante Barton! ¡La 1ra legión está completamente fuera de línea!",
  ui_story_5082_50820700_97_dialog_content = "Solo sigue moviéndote.",
  ui_story_5082_50820700_98_dialog_content = "...",
  ui_story_5082_50820700_99_dialog_content = "¿Qué crees que estás haciendo?",
  ui_story_5082_50820700_100_dialog_content = "¿Vas a quedarte ahí parado y mirar?",
  ui_story_5082_50820700_101_dialog_content = "¿Es todo esto totalmente justo y aceptable?",
  ui_story_5082_50820700_102_dialog_content = "...",
  ui_story_5082_50820700_103_dialog_content = "...¡Hmph!",
  ui_story_5082_50820700_104_dialog_content = "Barton!",
  ui_story_5082_50820700_105_dialog_content = "¡No hicimos nada malo!",
  ui_story_5082_50820700_106_dialog_content = "?",
  ui_story_5082_50820700_107_dialog_content = "<color=#e8d9bb>En el repentino silencio, ella avanza a través de la multitud con la cabeza en alto y se sitúa en el centro del alboroto.</color>",
  ui_story_5082_50820700_108_dialog_content = "Todos ustedes no son más que marionetas sin valor.",
  ui_story_5082_50820700_109_dialog_content = "¡Si alguien es culpable de hacer algo malo, son ustedes!",
  ui_story_5082_50820700_110_dialog_content = "¿Estuve mal por no querer dejar atrás a mis camaradas?",
  ui_story_5082_50820700_111_dialog_content = "¿Estuve mal por querer salvar a las personas que fueron abandonadas a morir?!",
  ui_story_5082_50820700_112_dialog_content = "Tú—",
  ui_story_5082_50820700_113_dialog_content = "Usen sus cabezas y piensen en lo que habrían hecho. ¿O acaso ustedes han perdido la capacidad de hacer eso?",
  ui_story_5082_50820700_114_dialog_content = "Luchamos para derrotar a los Eclipsites y proteger a nuestros aliados.",
  ui_story_5082_50820700_115_dialog_content = "Y sin embargo, algunas personas piensan que deberíamos ser castigados por hacer lo que siempre tienen demasiado miedo de hacer.",
  ui_story_5082_50820700_116_dialog_content = "Lo único para lo que sirven ahora es para obedecer.",
  ui_story_5082_50820700_117_dialog_content = "Por eso, todo lo que se necesita es una sola orden para hacer que te vuelvas contra tus camaradas y los envíes a su muerte.",
  ui_story_5082_50820700_118_dialog_content = "...",
  ui_story_5082_50820700_119_dialog_content = "Lo diré de nuevo.",
  ui_story_5082_50820700_120_dialog_content = "No hicimos nada malo.",
  ui_story_5082_50820700_121_dialog_content = "Y si tuviéramos que hacerlo todo de nuevo, tomaríamos exactamente la misma decisión.",
  ui_story_5082_50820700_122_dialog_content = "Eso es porque tú o yo podríamos ser los próximos atrapados en una situación sin esperanza.",
  ui_story_5082_50820700_123_dialog_content = "¡Pero mientras seamos aliados, ninguno de nosotros tiene el derecho o la razón para darle la espalda al otro sin siquiera intentarlo!",
  ui_story_5082_50820700_124_dialog_content = "¡Lo diré por última vez!",
  ui_story_5082_50820700_125_dialog_content = "Sí, violamos nuestras órdenes, pero nosotros—",
  ui_story_5082_50820700_126_dialog_content = "¡No hizo nada malo!",
  ui_story_5082_50820700_127_dialog_content = "...",
  ui_story_5082_50820700_128_dialog_content = "¿Tienes algo más que decir, Barton?",
  ui_story_5082_50820700_129_dialog_content = "Hmph.",
  ui_story_5082_50820700_130_dialog_content = "<color=#e8d9bb>Sin decir una palabra, Barton avanza entre la multitud que se abre a su paso y se coloca frente a ella.</color>",
  ui_story_5082_50820700_131_dialog_content = "No soy tan bueno hablando como tú, pero en este momento, no hace falta decir más palabras.",
  ui_story_5082_50820700_132_dialog_content = "<color=#e8d9bb>Barton hincha su pecho.</color>",
  ui_story_5082_50820700_133_dialog_content = "¡Esplendor Illumina!",
  ui_story_5082_50820700_134_dialog_content = "Je, no hace falta más palabras, ¿eh?",
  ui_story_5082_50820700_135_dialog_content = "<color=#e8d9bb>Ella toma una respiración profunda y equipara su intensidad con su propio llamado.</color>",
  ui_story_5082_50820700_136_dialog_content = "¡Esplendor Illumina!",
  ui_story_5082_50820700_137_dialog_content = "<color=#e8d9bb>Los soldados que los rodean se miran entre sí, inseguros de qué deberían hacer. Los dos continúan manteniéndose firmes, como si ni los mismísimos cielos pudieran hacerlos moverse.</color>",
  ui_story_5082_50820700_138_dialog_content = "<color=#e8d9bb>Antes de que alguien recobre sus sentidos, dos figuras más emergen de la multitud.</color>",
  ui_story_5082_50820700_139_dialog_content = "¡Esplendor Illumina!",
  ui_story_5082_50820700_140_dialog_content = "<color=#e8d9bb>Después de ellos, los que lucharon en esa batalla avanzan.</color>",
  ui_story_5082_50820700_141_dialog_content = "¡Esplendor Illumina!",
  ui_story_5082_50820700_142_dialog_content = "<color=#e8d9bb>En poco tiempo, cada vez más personas se unen al canto.",
  ui_story_5082_50820700_143_dialog_content = "¡Esplendor Illumina!",
  ui_story_5082_50820700_144_dialog_content = "<color=#e8d9bb>El espacio que una vez dividió a la multitud ahora está lleno de soldados unidos bajo una sola causa.</color>",
  ui_story_5082_50820700_145_dialog_content = "<color=#e8d9bb>Aquellos que habían luchado juntos, y aquellos que no lo habían hecho.</color>",
  ui_story_5082_50820700_146_dialog_content = "<color=#e8d9bb>Aquellos que se conocían por nombre y aquellos que eran completos desconocidos.</color>",
  ui_story_5082_50820700_147_dialog_content = "<color=#e8d9bb>Cada soldado se paró orgulloso entre sus compañeros.</color>",
  ui_story_5082_50820700_148_dialog_content = "¡Esplendor Illumina!",
  ui_story_5082_50820700_149_dialog_content = "Esplendor Ilumina!!!",
  ui_story_5082_50820700_150_dialog_content = "¿Qué deberíamos hacer, comandante? La multitud va a perder el control a este ritmo.",
  ui_story_5082_50820700_151_dialog_content = "... Así que ahora ella está interpretando a la heroína, ¿eh?",
  ui_story_5082_50820700_152_dialog_content = "¡Cálmense, todos ustedes!!!",
  ui_story_5082_50820700_153_dialog_content = "...",
  ui_story_5082_50820700_154_dialog_content = "Comandante del Batallón Barton! El trato preferencial de Pango hacia usted no se aplica fuera de la 2ª Legión, así que por favor absténgase de interrumpir más el entrenamiento de la 1ra Legión.",
  ui_story_5082_50820700_155_dialog_content = "¡Atención, todos los miembros de la 1ra Legión! Como castigo por sus acciones de hoy, se les asigna limpiar cada campo de entrenamiento en la ciudad de Gannon, ¡efectivo inmediatamente!",
  ui_story_5082_50820700_156_dialog_content = "¡Ese castigo es completamente irrazonable!",
  ui_story_5082_50820700_157_dialog_content = "¡Seguirás tus órdenes, soldado!!!",
  ui_story_5082_50820700_158_dialog_content = "Una vez que la limpieza esté completa, toda la 1ra Legión será reorganizada y se le prohibirá participar en cualquier evento militar futuro.",
  ui_story_5082_50820801_1_dialog_content = "Cuando lo pienso... Todos simplemente iban con la corriente, pero ella fue la que expresó las palabras que estaban en sus corazones.",
  ui_story_5082_50820801_2_dialog_content = "Espera, ¿a qué te refieres con eso?",
  ui_story_5082_50820801_3_dialog_content = "¡No recuerdo a ninguna chica de rojo en aquel entonces!",
  ui_story_5082_50820801_4_dialog_content = "Nunca olvidaré un momento de lo que sucedió ese día. ¡El que dijo todas esas palabras fuiste tú, Reinhardt!",
  ui_story_5082_50820801_5_dialog_content = "... ¿Yo?",
  ui_story_5082_50820801_6_dialog_content = "¿No perdiste tus recuerdos en esa explosión del laboratorio, verdad? En todos mis años de conocerte, nunca he visto a nadie como la persona que estás describiendo.",
  ui_story_5082_50820801_7_dialog_content = "Pero estos recuerdos... Cuanto más avanzamos en esta base, más siguen resurgiendo... Y no parecen falsos en absoluto.",
  ui_story_5082_50820801_8_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5082_50820801_9_dialog_content = "Agh, maldita sea...",
  ui_story_5082_50820801_10_dialog_content = "¡Cuidado con tu paso! Este lugar está cubierto de electrónicos viejos y rotos, así que intenta no tropezar con ellos.",
  ui_story_5082_50820801_11_dialog_content = "¡Aquí, observa de cerca! La próxima vez que estés a punto de caerte, simplemente impúlsate hacia adelante así, y...",
  ui_story_5082_50820801_12_dialog_content = "Gracias Philyshy, pero estoy bastante seguro de que solo un gato puede lograr eso...",
  ui_story_5082_50820801_13_dialog_content = "Oye, esta cosa con la que tropecé... ¿Por qué parece que se supone que debe llevarse en la cabeza?",
  ui_story_5082_50820801_14_dialog_content = "¡Miau! ¡He visto esto antes!",
  ui_story_5082_50820801_15_dialog_content = "El doctor Chandra usó esta cosa para tratarme a mí y a Yumi desde el principio. Ella dijo que también era bastante valiosa.",
  ui_story_5082_50820801_16_dialog_content = "Aparentemente no hay muchos como él, y se usaban para entrenar a los soldados de élite de Illumina.",
  ui_story_5082_50820801_17_dialog_content = "Hay uno aquí también. Están dañados más allá de la reparación, pero el diseño original aún se puede ver en las partes restantes.",
  ui_story_5082_50820801_18_dialog_content = "Déjame echar un vistazo...",
  ui_story_5082_50820801_19_dialog_content = "Espera...",
  ui_story_5082_50820801_20_dialog_content = "<color=#e8d9bb>El grupo solo logra ver el dispositivo brevemente antes de que Barton lo aplaste en pedazos.</color>",
  ui_story_5082_50820801_21_dialog_content = "... No hay manera de que algo así se pueda usar para entrenar a soldados de élite, ¿verdad?",
  ui_story_5082_50820801_22_dialog_content = "¿Estas cosas son realmente tan raras y valiosas? Porque ya logramos encontrar tres de ellas aquí.",
  ui_story_5082_50820801_23_dialog_content = "Este todavía está mayormente intacto, pero está cubierto de óxido... ¿Eh?",
  ui_story_5082_50820801_24_dialog_content = "Esta máquina...",
  ui_story_5082_50820801_25_dialog_content = "... Puedo sentir la vida fluyendo a través de él.",
  ui_story_5082_50820801_26_dialog_content = "!",
  ui_story_5082_50820801_27_dialog_content = "Oh...",
  ui_story_5082_50820801_28_dialog_content = "¿Reinhardt?",
  ui_story_5082_50820801_29_option_content = "¡Potencia de fuerza!",
  ui_story_5082_50820801_30_dialog_content = "...",
  ui_story_5082_50820801_31_dialog_content = "Ya no se detectan signos vitales...",
  ui_story_5082_50820801_32_dialog_content = "<color=#e8d9bb>Glub, glub, glub...</color>",
  ui_story_5082_50820801_33_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820801_34_dialog_content = "La corneta... Es hora de entrenar.",
  ui_story_5082_50820801_35_dialog_content = "¡Rugido!",
  ui_story_5082_50820801_36_dialog_content = "Gran Mariscal!",
  ui_story_5082_50820801_37_dialog_content = "Esta máquina... La he visto antes... La he usado...",
  ui_story_5082_50820801_38_dialog_content = "Pero... Por qué...",
  ui_story_5082_50820801_39_dialog_content = "¡Aguanta, Gran Mariscal!",
  ui_story_5082_50820801_40_dialog_content = "PlayerName! ¡Deshazte de esa cosa!",
  ui_story_5082_50820801_41_dialog_content = "Espera, esa presencia de ahora... ¿Recordaste algo, Reinhardt?",
  ui_story_5082_50820801_42_dialog_content = "Es vago, pero definitivamente tiene algo que ver con esa cosa... Ahora depende de ti, PlayerName...",
  ui_story_5082_50820801_43_dialog_content = "Gran Mariscal...!",
  ui_story_5082_50820801_44_dialog_content = "Esto es muy importante para mí, Vivian.",
  ui_story_5082_50820801_45_dialog_content = "Manténganse en alerta, todos. Necesito que mantengan a esos monstruos alejados de nosotros.",
  ui_story_5082_50820801_46_dialog_content = "Estoy a punto de entrar en la conciencia de Reinhardt para descubrir qué hay detrás de este extraño dispositivo.",
  ui_story_5082_50820901_1_dialog_content = "(Parece que estoy en un laboratorio de Illumina, pero se siente tan opresivo aquí.)",
  ui_story_5082_50820901_2_dialog_content = "Sujeto #1, por favor entra a las habitaciones uno a tres y usa tu Luminatics de acuerdo a sus instrucciones.",
  ui_story_5082_50820901_3_dialog_content = "Entendido.",
  ui_story_5082_50820901_4_dialog_content = "Sujeto #2, por favor entra a las habitaciones uno a tres y usa tus Luminatics de acuerdo a sus instrucciones.",
  ui_story_5082_50820901_5_dialog_content = "...",
  ui_story_5082_50820901_6_dialog_content = "(¿Qué están haciendo?)",
  ui_story_5082_50820901_7_dialog_content = "Sujeto #2, por favor cumple con tus órdenes.",
  ui_story_5082_50820901_8_dialog_content = "Me gustaría saber el verdadero propósito de este experimento.",
  ui_story_5082_50820901_9_dialog_content = "Si mi dominio de Luminatics es el tema de prueba, debería estar al tanto del entorno de prueba para hacer los ajustes necesarios.",
  ui_story_5082_50820901_10_dialog_content = "Sería preferible para mí simplemente desatar mi Lumina en una habitación oscura sin un objetivo claro en mente.",
  ui_story_5082_50820901_11_dialog_content = "Solo ten en cuenta que este experimento te ayudará en tu camino para convertirte en un investigador, Denier.",
  ui_story_5082_50820901_12_dialog_content = "...",
  ui_story_5082_50820901_13_dialog_content = "Sujeto #3, por favor entra a las habitaciones uno a tres y usa tus Lumináticas de acuerdo a sus instrucciones.",
  ui_story_5082_50820901_14_dialog_content = "No me informaron sobre ningún cambio en mi entrenamiento hoy.",
  ui_story_5082_50820901_15_dialog_content = "No tenemos ninguna obligación de revelarte ninguna información. No es más que una pequeña serie de pruebas, ahora por favor coopera.",
  ui_story_5082_50820901_16_dialog_content = "Creo que tengo derecho a saber sobre cualquier cosa que me concierne.",
  ui_story_5082_50820901_17_dialog_content = "¿PlayerName?",
  ui_story_5082_50820901_18_dialog_content = "¿Te sientes mejor? Realmente me asustaste hace un momento...",
  ui_story_5082_50820901_19_dialog_content = "¿Qué tipo de experimento fue ese? ¿Y por qué estaban allí los tres?",
  ui_story_5082_50820901_20_dialog_content = "\"¿Todos nosotros tres\"? ¿Qué quieres decir?",
  ui_story_5082_50820901_21_dialog_content = "¿No te viste hace un momento? Estabas parado justo aquí...",
  ui_story_5082_50820901_22_dialog_content = "Yo no...",
  ui_story_5082_50820901_23_dialog_content = "<color=#e8d9bb>Reinhardt se detiene por un momento, con el ceño fruncido en pensamiento. Da dos pasos adelante y se para donde se encontraba en su memoria.</color>",
  ui_story_5082_50820901_24_dialog_content = "¿Qué viste, PlayerName?",
  ui_story_5082_50820901_25_dialog_content = "Te vi a ti y a tu yo del pasado en su uniforme de la academia.",
  ui_story_5082_50820901_26_dialog_content = "Pero vi a alguien más.",
  ui_story_5082_50820901_27_dialog_content = "Una chica con cabello negro corto y desordenado, cuyos ojos agudos parecían estar listos para desafiar a cualquiera.",
  ui_story_5082_50820901_28_dialog_content = "Tenía cicatrices por todas sus manos y brazos, pero no se molestó en cubrirlas en absoluto. Llevaba una camisa roja y un abrigo colgado sobre sus hombros como una capa.",
  ui_story_5082_50820901_29_dialog_content = "Se veía tan desenfrenada e indomable, como un fuego furioso que amenazaba con quemar todo a su paso. Una vista aterradora—",
  ui_story_5082_50820901_30_dialog_content = "Y sin embargo, de alguna manera se sintió tan liberador.",
  ui_story_5082_50820901_31_dialog_content = "Entonces, esa chica de rojo brillante que mencionaste antes...",
  ui_story_5082_50820901_32_dialog_content = "Es correcto.",
  ui_story_5082_50820901_33_dialog_content = "Para ser honesto, también tengo problemas para creerlo. Pero después de ver este recuerdo, ya no se puede negar.",
  ui_story_5082_50820901_34_dialog_content = "Esa chica—",
  ui_story_5082_50820901_35_dialog_content = "Soy yo.",
  ui_story_5082_50820901_36_dialog_content = "(La escena está cambiando de nuevo.)",
  ui_story_5082_50820901_37_dialog_content = "Todos los sujetos de prueba, por favor hagan los ajustes necesarios a su equipo y concéntrense.",
  ui_story_5082_50820901_38_dialog_content = "Esas tres máquinas... Parecen las que acabamos de encontrar.",
  ui_story_5082_50820901_39_dialog_content = "Así que ustedes los usaron en el pasado. No es de extrañar que Philyshy dijera que se usaban para entrenar a soldados de élite.",
  ui_story_5082_50820901_40_dialog_content = "¿Pero por qué no tengo recuerdo de estas cosas...?",
  ui_story_5082_50820901_41_dialog_content = "Urgh... ¿Por qué me duele tanto la cabeza? ¿Podría tener algo que ver con estas máquinas?",
  ui_story_5082_50820901_42_dialog_content = "Un dispositivo que estimula el cerebro para desencadenar el potencial oculto...",
  ui_story_5082_50820901_43_dialog_content = "¡Si se meten con mi cerebro, más les vale estar listos para pagar por ello—!",
  ui_story_5082_50820901_44_dialog_content = "Espera un minuto, ¡este no es mi latido del corazón! Estas emociones complicadas tampoco son mías... ¿Escucho algo? No... Lo siento...",
  ui_story_5082_50820901_45_dialog_content = "Siento la presencia de alguien más.",
  ui_story_5082_50820901_46_dialog_content = "... ¿Hermana?",
  ui_story_5082_50820901_47_dialog_content = "... Negador.",
  ui_story_5082_50820901_48_dialog_content = "Nunca esperé tener una conversación contigo de esta manera.",
  ui_story_5082_50820901_49_dialog_content = "O tenerlo aquí, de todos los lugares... ¿Qué estás haciendo aquí?",
  ui_story_5082_50820901_50_dialog_content = "La capacidad de percibir los pensamientos y emociones de otras personas... ¿Están intentando replicar el poder de los Celestitas?",
  ui_story_5082_50820901_51_dialog_content = "Pero si estás aquí, eso significa que alguien más también debería estar aquí.",
  ui_story_5082_50820901_52_dialog_content = "¡¿Qué es esto?!",
  ui_story_5082_50820901_53_dialog_content = "Parece que tenía razón.",
  ui_story_5082_50820901_54_dialog_content = "... Dijeron que querían probar nuestro control de Luminatics, pero esto no tiene nada que ver con eso.",
  ui_story_5082_50820901_55_dialog_content = "¿Quizás están intentando mejorar nuestra eficiencia de combate como una unidad cohesiva?",
  ui_story_5082_50820901_56_dialog_content = "Si solo fuera tan simple. ¿No sienten curiosidad por qué nos eligieron a nosotros tres?",
  ui_story_5082_50820901_57_dialog_content = "...",
  ui_story_5082_50820901_58_dialog_content = "Además, los investigadores probablemente mencionaron que habría más pruebas como esta, ¿verdad?",
  ui_story_5082_50820901_59_dialog_content = "No he olvidado cómo se veía Reinhardt después de regresar de esas llamadas \"pruebas\".",
  ui_story_5082_50820901_60_dialog_content = "No somos tan poderosos como Reinhardt, así que quizás nuestras pruebas no sean tan... ¡Ugh!",
  ui_story_5082_50820901_61_dialog_content = "¿Helios?!",
  ui_story_5082_50820901_62_dialog_content = "Ya no siento su conciencia. Tal vez él—¡Ack!",
  ui_story_5082_50820901_63_dialog_content = "¡Negador! ¿Qué está pasando?!",
  ui_story_5082_50820901_64_dialog_content = "¡Rugido!",
  ui_story_5082_50820901_65_dialog_content = "... Ustedes son la próxima parte de su \"pequeña serie de pruebas\", ¿verdad?",
  ui_story_5082_50820902_1_dialog_content = "(Después de ese día, noté que me seguían constantemente, sin importar a dónde fuera.)",
  ui_story_5082_50820902_2_dialog_content = "...",
  ui_story_5082_50820902_3_dialog_content = "Uf, los contendientes de hoy fueron bastante duros.",
  ui_story_5082_50820902_4_dialog_content = "¿Ves? Te dije que ella estaría bien. Dijo que no nos dejaría plantados de nuevo, ¿recuerdas?",
  ui_story_5082_50820902_5_dialog_content = "¿Entonces te encontraste con algún problema, Reinhardt?",
  ui_story_5082_50820902_6_dialog_content = "Nah, solo siendo observado constantemente como de costumbre. ¿Y ustedes dos? Desde que terminó el experimento, no los he visto hablar entre ustedes.",
  ui_story_5082_50820902_7_dialog_content = "...",
  ui_story_5082_50820902_8_dialog_content = "Si tienes algo en mente, deberías hablar de ello. Conocer la verdad es la única forma en que podemos tomar las decisiones correctas.",
  ui_story_5082_50820902_9_dialog_content = "... Tienes razón. Crecimos juntos y no deberíamos guardar secretos sobre esto el uno del otro.",
  ui_story_5082_50820902_10_dialog_content = "La verdad es que mi cabeza ha estado doliendo desde el experimento de ese día.",
  ui_story_5082_50820902_11_dialog_content = "Por alguna razón, nunca más me incluyeron en las actividades grupales para mi entrenamiento de explorador. Incluso mi comandante no me da una respuesta directa cuando le pregunto al respecto.",
  ui_story_5082_50820902_12_dialog_content = "¿Ya te has hecho un chequeo?",
  ui_story_5082_50820902_13_dialog_content = "Dijeron que no hay nada malo conmigo y que no debería preocuparme tanto ya que no afecta seriamente mi vida o habilidades de combate.",
  ui_story_5082_50820902_14_dialog_content = "¿Y tú, negador?",
  ui_story_5082_50820902_15_dialog_content = "... Este lugar ha sido descubierto.",
  ui_story_5082_50820902_16_dialog_content = "!",
  ui_story_5082_50820902_17_dialog_content = "Es mi culpa.",
  ui_story_5082_50820902_18_dialog_content = "Necesitaba algunos materiales, así que me acerqué a mis superiores con una propuesta para un proyecto en el que estaba trabajando, pero me ignoraron.",
  ui_story_5082_50820902_19_dialog_content = "Y luego, hace solo unos días, mi proyecto fue rechazado por completo. Me rastrearon hasta aquí bajo sospecha de llevar a cabo experimentos peligrosos.",
  ui_story_5082_50820902_20_dialog_content = "Me ordenaron cerrar el laboratorio y entregar todo mi equipo e investigación.",
  ui_story_5082_50820902_21_dialog_content = "Eso no es un problema. Construimos este lugar antes y podemos construirlo de nuevo.",
  ui_story_5082_50820902_22_dialog_content = "Perder tu investigación es la verdadera pérdida aquí... Lo que me recuerda, ¿en qué estabas trabajando aquí?",
  ui_story_5082_50820902_23_dialog_content = "... Tenemos algo más importante de lo que hablar en este momento.",
  ui_story_5082_50820902_24_dialog_content = "\"Ningún sujeto de prueba ha completado con éxito este programa, pero tus datos podrían ser la clave para un avance científico para Illumina.\"",
  ui_story_5082_50820902_25_dialog_content = "\"Anota todo lo que experimentes durante este experimento... Lo que escuchas... Lo que sientes...\"",
  ui_story_5082_50820902_26_dialog_content = "\"Ya sea que busques promoción o acceso a la tecnología más avanzada disponible, todo estará a tu alcance.\"",
  ui_story_5082_50820902_27_dialog_content = "Ustedes dos también fueron informados de algo similar después de ese experimento, ¿verdad?",
  ui_story_5082_50820902_28_dialog_content = "...",
  ui_story_5082_50820902_29_dialog_content = "Así que ahora es el momento de decidir. Todos a favor de rechazar sus promesas de grandeza y fracasar a propósito en su experimento, levanten la mano.",
  ui_story_5082_50820902_30_dialog_content = "Lo que Denier dijo ese día me hizo darme cuenta de que los tres estamos conectados por este experimento.",
  ui_story_5082_50820902_31_dialog_content = "No sé cuál es su objetivo, pero me preocupa que mis resultados puedan representar un riesgo para ustedes dos.",
  ui_story_5082_50820902_32_dialog_content = "Es por eso que no puedo ni tomaré ninguna decisión sobre esto por mi cuenta.",
  ui_story_5082_50820902_33_dialog_content = "<color=#e8d9bb>Helios levanta su mano.</color>",
  ui_story_5082_50820902_34_dialog_content = "También tengo más que decir.",
  ui_story_5082_50820902_35_dialog_content = "Espera, es mi turno de hablar. Soy un experto cuando se trata de ser \"probado\", así que muchas de estas cosas son ahora una segunda naturaleza para mí.",
  ui_story_5082_50820902_36_dialog_content = "Mientras sigas mostrándoles tus límites, ellos seguirán empujándote a superarlos.",
  ui_story_5082_50820902_37_dialog_content = "Incluso arrastrarán a tus amigos a esto. Ningún precio es demasiado grande a sus ojos, ni siquiera nuestras propias vidas.",
  ui_story_5082_50820902_38_dialog_content = "<color=#e8d9bb>Reinhardt levanta su mano.</color>",
  ui_story_5082_50820902_39_dialog_content = "He estado investigando un poco por mi cuenta estos últimos días.",
  ui_story_5082_50820902_40_dialog_content = "Para aumentar la fuerza militar de Illumina, van a comenzar experimentos para activar un Coloso conocido como \"Spearhead\".",
  ui_story_5082_50820902_41_dialog_content = "Un Colossus...",
  ui_story_5082_50820902_42_dialog_content = "Has oído hablar de ello, ¿verdad? Lo excavaron de una de las Ciudades Subterráneas cercanas. Aparentemente, incluso es anterior a los Colossus de Eraveil.",
  ui_story_5082_50820902_43_dialog_content = "Es posible que el objetivo del experimento fuera encontrar un piloto adecuado para el Colossus.",
  ui_story_5082_50820902_44_dialog_content = "Pero no tengo ganas de perder el tiempo en experimentos sin sentido, y definitivamente no quiero que se interpongan en nuestras reuniones diarias.",
  ui_story_5082_50820902_45_dialog_content = "Entonces-",
  ui_story_5082_50820902_46_dialog_content = "<color=#e8d9bb>Denier levanta su mano.</color>",
  ui_story_5082_50820902_47_dialog_content = "Todos estamos de acuerdo.",
  ui_story_5082_50820902_48_dialog_content = "Felicidades a todos. El experimento de selección del Navegante ya es un fracaso total y absoluto.",
  ui_story_5082_50820902_49_dialog_content = "Lo que significa que somos libres de hacer lo que tenemos que hacer ahora. Vamos a llamarlo por hoy.",
  ui_story_5082_50820902_50_dialog_content = "¿Podría tener otro segundo, por favor? Todavía tengo más que decir, y creo que podría estar relacionado con nuestra situación.",
  ui_story_5082_50820902_51_dialog_content = "No he tenido mucho que hacer últimamente, y he estado pensando en ese experimento, así que decidí investigar ese laboratorio.",
  ui_story_5082_50820902_52_dialog_content = "Las pruebas que nos hicieron fueron solo en una pequeña sección del laboratorio. Toda la instalación es mucho más grande de lo que imaginábamos.",
  ui_story_5082_50820902_53_dialog_content = "Eso explica por qué tuvieron que construirlo en una de las Subciudades vecinas. Aparte del sector de investigación, el laboratorio cuenta con un centro médico inusualmente bien abastecido y equipos completamente funcionales.",
  ui_story_5082_50820902_54_dialog_content = "La seguridad era estricta, así que no pude echar un vistazo más detallado al interior.",
  ui_story_5082_50820902_55_dialog_content = "Pero a juzgar por la cantidad de comida que se asigna a la instalación, supongo que están manteniendo a muchos pacientes allí.",
  ui_story_5082_50820902_56_dialog_content = "Entonces, ¿estás diciendo que tus dolores de cabeza no son únicos para ti y que otras personas podrían haber necesitado hospitalización por sus propios síntomas?",
  ui_story_5082_50820902_57_dialog_content = "Quizás, pero lo que más quiero mencionar es...",
  ui_story_5082_50820902_58_dialog_content = "He visto a personas llevando niños dentro y fuera de la guardería allí.",
  ui_story_5082_50820902_59_dialog_content = "Da miedo pensarlo, pero debido a los repetidos fracasos de los sujetos de prueba adultos, es posible que hayan comenzado a llevar su investigación en una dirección diferente...",
  ui_story_5082_50820902_60_dialog_content = "¿Quieres decir que ahora están experimentando con huérfanos?!",
  ui_story_5082_50820902_61_dialog_content = "Siéntate, Reinhardt.",
  ui_story_5082_50820902_62_dialog_content = "Todo lo que hemos hablado hoy debía permanecer clasificado.",
  ui_story_5082_50820902_63_dialog_content = "Sabes cómo están las cosas ahora; no tenemos espacio para jugar a ser héroes cuando ni siquiera podemos garantizar nuestra propia seguridad.",
  ui_story_5082_50820902_64_dialog_content = "Así que solo cálmate. El experimento de ese día me dio algunas ideas sobre cómo avanzar en mi investigación y resolver nuestro problema.",
  ui_story_5082_50820902_65_dialog_content = "Con un poco de suerte, podrá protegernos e incluso sacarnos de este lugar para siempre. Pero ahora mismo...",
  ui_story_5082_50820902_66_dialog_content = "Como alguien que ha pasado por innumerables sesiones de \"entrenamiento especial\", sé por experiencia personal que ninguna persona común puede sobrevivir a este tipo de infierno!",
  ui_story_5082_50820902_67_dialog_content = "Me llevaron a todo tipo de lugares ocultos para mis \"pruebas\", incluyendo edificios abandonados y antiguos campos de batalla..",
  ui_story_5082_50820902_68_dialog_content = "Marcaré sus ubicaciones exactas en un mapa. Podrías ser capaz de usar uno de esos lugares como un laboratorio temporal.",
  ui_story_5082_50820902_69_dialog_content = "Pero es posible que tengas que ir allí solo.",
  ui_story_5082_50820902_70_dialog_content = "¿No escuchaste nada de lo que acabo de decir?",
  ui_story_5082_50820902_71_dialog_content = "Es muy probable que tu \"entrenamiento\" estuviera al servicio de un objetivo aún mayor—",
  ui_story_5082_50820902_72_dialog_content = "¡Aún así!",
  ui_story_5082_50820902_73_dialog_content = "Hermana...",
  ui_story_5082_50820902_74_dialog_content = "Entiendo tu preocupación, Denier. Pero huir no resolverá nada.",
  ui_story_5082_50820902_75_dialog_content = "¿Estás dispuesto a ayudarme a investigar un poco más, Helios?",
  ui_story_5082_50820902_76_dialog_content = "No tienes que preguntar. Pero si nuestras suposiciones son correctas, ¿qué estás dispuesto a hacer al respecto?",
  ui_story_5082_50820902_77_dialog_content = "¿Qué piensas?",
  ui_story_5082_50820902_78_dialog_content = "D-Digamos que logramos rescatar a las personas dentro... ¿Y luego qué?",
  ui_story_5082_50820902_79_dialog_content = "No he planeado tan lejos.",
  ui_story_5082_50820902_80_dialog_content = "Pero si simplemente me aparto, sabiendo que están sucediendo estas cosas terribles...",
  ui_story_5082_50820902_81_dialog_content = "Entonces, ¿cuál sería el punto de todos mis esfuerzos hasta este momento?",
  ui_story_5082_50820902_82_dialog_content = "Quiero llegar a ser Gran Mariscal y convertirme algún día en el soldado más fuerte de Illumina. Cuando ocurra un desastre, quiero estar en la vanguardia de la batalla y proteger a todos.",
  ui_story_5082_50820902_83_dialog_content = "No quiero ser alguien que vacila cuando sus aliados están en peligro, o se acobarda ante una nueva amenaza—",
  ui_story_5082_50820902_84_dialog_content = "Y me niego a ser cómplice de los planes de autoengrandecimiento de personas que experimentan con niños pequeños.",
  ui_story_5082_50820902_85_dialog_content = "Si todos los líderes de Illumina son así, entonces necesito preguntarles...",
  ui_story_5082_50820902_86_dialog_content = "Cuando cantan Esplendor Illumina mientras envían a nuestros soldados de primera línea a sus muertes, o secuestran y torturan a personas inocentes...",
  ui_story_5082_50820902_87_dialog_content = "¿Es solo para garantizar la estabilidad de sus intereses?",
  ui_story_5082_50820902_88_dialog_content = "Espera, Reinhardt! ¿Siquiera sabes lo que estás diciendo?",
  ui_story_5082_50820902_89_dialog_content = "La alta dirección ya te ve como un extremista y una amenaza después de que falsificaste órdenes la última vez.",
  ui_story_5082_50820902_90_dialog_content = "¿¡Vas a traicionar a Illumina esta vez de verdad?!",
  ui_story_5082_50820902_91_dialog_content = "¿Traicionar? Para nada.",
  ui_story_5082_50820902_92_dialog_content = "Los verdaderos traidores son los cobardes a cargo del ejército y los tontos que les obedecen.",
  ui_story_5082_50820902_93_dialog_content = "Los verdaderos traidores son las personas que experimentan con niños inocentes, así como las personas que simplemente se quedan de brazos cruzados y lo permiten.",
  ui_story_5082_50820902_94_dialog_content = "Me niego a seguir con esto y me niego a pensar solo en mi propia seguridad.",
  ui_story_5082_50820902_95_dialog_content = "Negador, Helios, lamento haberlos envuelto a ambos en este lío.",
  ui_story_5082_50820902_96_dialog_content = "Pero si comprometo mis ideales para preservar el statu quo, nunca lograré mis sueños.",
  ui_story_5082_50820902_97_dialog_content = "Es por eso que voy a hacer todo lo que esté a mi alcance para derrocar este sistema podrido e hipócrita.",
  ui_story_5082_50821001_1_dialog_content = "No puedo creerlo... ¿La propia Gran Mariscal intentó derrocar a Illumina en el pasado?!",
  ui_story_5082_50821001_2_dialog_content = "El extraño vínculo telepático entre esos tres soldados aumentados no fue para nada un accidente...",
  ui_story_5082_50821001_3_dialog_content = "Pensaron que estarían seguros siempre y cuando mantuvieran los resultados de su investigación ocultos, pero solo atrajo aún más la atención de sus superiores.",
  ui_story_5082_50821001_4_dialog_content = "Derrocar a Illumina... fue una empresa audaz, por decir lo menos...",
  ui_story_5082_50821001_5_dialog_content = "Pero cuando se dio cuenta de que su potencial era real, y que su poder era el resultado de un plan cuidadosamente construido, supo que podía hacerlo.",
  ui_story_5082_50821001_6_dialog_content = "... Hablas de tu yo pasado como si fuera una persona completamente diferente.",
  ui_story_5082_50821001_7_dialog_content = "Eso es porque, en lo que a mí respecta, ella es una persona totalmente diferente.",
  ui_story_5082_50821001_8_dialog_content = "La academia, el entrenamiento y los experimentos, la guardería... Todo este tiempo, pensé que mis recuerdos de estas cosas estaban completos.",
  ui_story_5082_50821001_9_dialog_content = "Notaba pequeñas lagunas en mis recuerdos de vez en cuando, pero nunca supe que había tantos detalles desconocidos escondidos en ellos.",
  ui_story_5082_50821001_10_dialog_content = "Especialmente la prueba por la que pasamos los tres. Parece que mis recuerdos de ese día fueron completamente borrados.",
  ui_story_5082_50821001_11_dialog_content = "¿Podría ser que mis recuerdos del pasado sean completamente diferentes a lo que realmente sucedió...?",
  ui_story_5082_50821001_12_dialog_content = "Estoy seguro de que a Vice también le parece lo mismo...",
  ui_story_5082_50821001_13_dialog_content = "Es bueno que hayamos podido obtener un poco de la verdad de estas máquinas, ¿verdad?",
  ui_story_5082_50821001_14_dialog_content = "Dado que también fuiste elegido para sus experimentos, es probable que hayas perdido tus recuerdos por una razón similar.",
  ui_story_5082_50821001_15_dialog_content = "No exactamente. Después de ver mi pasado, deberías saber que no fui elegido para pilotar el Colossus. Mis recuerdos no indican lo contrario de todos modos.",
  ui_story_5082_50821001_16_dialog_content = "Aun así, realmente me gustaría saber qué le pasó después.",
  ui_story_5082_50821001_17_dialog_content = "Tus corazonadas fueron mayormente correctas.",
  ui_story_5082_50821001_18_dialog_content = "Según los últimos informes del laboratorio, están oficialmente listos para activar el Colossus Spearhead.",
  ui_story_5082_50821001_19_dialog_content = "La piloto que han seleccionado actualmente es una niña de cuatro años de la guardería—",
  ui_story_5082_50821001_20_dialog_content = "Su compatibilidad con los sistemas de respaldo es la más alta de cualquier otro sujeto de prueba.",
  ui_story_5082_50821001_21_dialog_content = "¿Me estás tomando el pelo? ¿Están obligando a una niña pequeña a hacer esto?!",
  ui_story_5082_50821001_22_dialog_content = "No la subestimes por su edad.",
  ui_story_5082_50821001_23_dialog_content = "Antes de este proyecto, parece que el Comité la había estado entrenando durante un año entero. Es posible que ella tenga incluso más experiencia que cualquiera de nosotros.",
  ui_story_5082_50821001_24_dialog_content = "Incluso logró una tasa de éxito del 20% en su prueba inicial.",
  ui_story_5082_50821001_25_dialog_content = "Negador, tú...",
  ui_story_5082_50821001_26_dialog_content = "... No lo pongas de esa manera.",
  ui_story_5082_50821001_27_dialog_content = "Solo estoy siendo realista. ¿Has visto cómo va nuestra lucha contra los Eclipsites?",
  ui_story_5082_50821001_28_dialog_content = "Dado el estado actual del experimento, arriesgar la vida de un solo niño por el bien de innumerables otros ofrece una alta probabilidad de éxito.",
  ui_story_5082_50821001_29_dialog_content = "¡Eso aún no es motivo para jugar con la vida de un niño! ¡No podemos esperar más; tenemos que hacer algo!",
  ui_story_5082_50821001_30_dialog_content = "Dejando de lado la pregunta de por dónde empezar, acabas de recuperar tus privilegios de comando. Denier y yo también estamos siendo aislados de ti, lo que significa que no tienes a nadie más en quien confiar.",
  ui_story_5082_50821001_31_dialog_content = "Aunque solo recuperé algunos de mis privilegios anteriores, eso no significa que esté comenzando de nuevo desde cero.",
  ui_story_5082_50821001_32_dialog_content = "Los soldados más fuertes de la 1ra Legión ya han acordado seguirme.",
  ui_story_5082_50821001_33_dialog_content = "Haré todo lo posible para eludir la vigilancia y establecer correspondencia en una de las Subciudades cercanas.",
  ui_story_5082_50821001_34_dialog_content = "Comunícate con Barton si necesitas contactarme. Él también ha aceptado ayudarnos.",
  ui_story_5082_50821001_35_dialog_content = "Puede que estés aislado ahora mismo, pero eso solo significa que tienes más libertad para recopilar información.",
  ui_story_5082_50821001_36_dialog_content = "Denier puede manejar el progreso del laboratorio. Mientras tanto, Helios, necesitamos que averigües cuántos más de estos experimentos secretos se están llevando a cabo en Illumina.",
  ui_story_5082_50821001_37_dialog_content = "Ya sean los altos mandos militares o los investigadores, tenemos que estar preparados para el peor escenario posible. Después de todo, estamos en guerra.",
  ui_story_5082_50821001_38_dialog_content = "Y cuando me convierta en Gran Mariscal, mi primera orden del día será luchar por las vidas de cada víctima inocente de estos experimentos.",
  ui_story_5082_50821001_39_dialog_content = "Pero aún no sabemos cuán poderoso es el Comité en este momento. ¿No crees que esto es demasiado arriesgado?",
  ui_story_5082_50821001_40_dialog_content = "Si tienen otro Reinhardt en espera en algún lugar, nuestras posibilidades de éxito serán aún más escasas.",
  ui_story_5082_50821001_41_dialog_content = "Entonces simplemente iremos con el Plan B.",
  ui_story_5082_50821001_42_dialog_content = "Los Aurorianos pueden sobrevivir casi en cualquier lugar, incluso en una Subciudad abandonada...",
  ui_story_5082_50821001_43_dialog_content = "Siempre que haya suficiente comida, agua, espacio y luz, se puede construir un asentamiento para que se reúnan los Aurorianos.",
  ui_story_5082_50821001_44_dialog_content = "Y dondequiera que se reúnan los Aurorianos, siempre habrá necesidad de un Gran Mariscal.",
  ui_story_5082_50821001_45_dialog_content = "¡Jajaja! Estás pensando demasiado adelante, negador. No tengo ninguna intención de dejar que las cosas lleguen a ese punto.",
  ui_story_5082_50821001_46_dialog_content = "Después de todo, nuestro objetivo original era proporcionar un lugar de refugio para cada Auroriano afectado por la crisis...",
  ui_story_5082_50821001_47_dialog_content = "Para proteger a los niños que, como nosotros, no tienen recuerdo de sus propios padres y deben confiar en sus puños para sobrevivir.",
  ui_story_5082_50821001_48_dialog_content = "...",
  ui_story_5082_50821001_49_dialog_content = "Muchas personas en Illumina comparten la misma historia, ¿eh...",
  ui_story_5082_50821001_50_dialog_content = "Solo sabía sobre Vice antes, pero después de ver esto... Siento mucho por todos...",
  ui_story_5082_50821001_51_dialog_content = "Nadie lo tenía mejor que nadie en aquel entonces. Apostaría a que muchas personas tuvieron experiencias similares a las de esa niña de cuatro años.",
  ui_story_5082_50821001_52_dialog_content = "En cuanto a Vice, estoy empezando a pensar... Que sus recuerdos de estos experimentos podrían no ser del todo reales.",
  ui_story_5082_50821001_53_dialog_content = "Tú, por otro lado, pareces simpatizar mucho con esa chica.",
  ui_story_5082_50821001_54_dialog_content = "... Entonces, ¿tu plan funcionó al final?",
  ui_story_5082_50821001_55_dialog_content = "Si tienes que preguntar, entonces todo lo que puedo hacer es recordarte que ahora soy el Gran Mariscal de Illumina.",
  ui_story_5082_50821001_56_dialog_content = "¿Todavía estamos hablando del mismo tú? ¿O de la misma Illumina, para el caso?",
  ui_story_5082_50821001_57_dialog_content = "¿Es eso realmente importante? Es obvio que \"su\" plan finalmente fracasó, ¿no es así?",
  ui_story_5082_50821001_58_dialog_content = "Creo que es muy importante.",
  ui_story_5082_50821001_59_dialog_content = "Tengo curiosidad por conocer el resultado, aunque todo haya quedado en el pasado.",
  ui_story_5082_50821001_60_dialog_content = "Pero lo que estás diciendo ahora suena como si viniera del Reinhardt de hoy.",
  ui_story_5082_50821001_61_dialog_content = "Parte de ello implica tu victoria sobre \"ella\", mientras que el resto implica el fracaso de \"ella\" hacia Illumina.",
  ui_story_5082_50821001_62_dialog_content = "Así que tengo que preguntar: ¿dónde te encuentras exactamente ahora, Reinhardt?",
  ui_story_5082_50821001_63_dialog_content = "¿Te mataría ser más directo a veces?",
  ui_story_5082_50821001_64_dialog_content = "Solo estoy complicando las cosas porque de quien estamos hablando es de ti.",
  ui_story_5082_50821001_65_dialog_content = "Entonces parece que necesito ser más honesto contigo.",
  ui_story_5082_50821001_66_dialog_content = "Para decirte la verdad, estoy un poco confundido yo mismo. ¿Crees que \"Reinhardt\" se parece más a mí, o que yo me parezco más a ella?",
  ui_story_5082_50821001_67_dialog_content = "Yo...",
  ui_story_5082_50821001_68_dialog_content = "No necesitas evitar la pregunta. No me molestaré sin importar lo que digas, lo prometo.",
  ui_story_5082_50821001_69_dialog_content = "E-Eso no es lo que tengo en mente.",
  ui_story_5082_50821001_70_dialog_content = "Ella simplemente parece mucho más libre y desinhibida, y...",
  ui_story_5082_50821001_71_dialog_content = "Lo siento, realmente no sé cómo describirlo mejor en este momento.",
  ui_story_5082_50821001_72_dialog_content = "No te preocupes. Ya has dado en el clavo.",
  ui_story_5082_50821001_73_dialog_content = "Como puedes ver, somos muy diferentes el uno del otro.",
  ui_story_5082_50821001_74_dialog_content = "En cualquier momento, alguien en Illumina podría estar pasando por el mismo infierno por el que pasé en aquel entonces.",
  ui_story_5082_50821001_75_dialog_content = "¿Crees que después de todos estos años de ver la brutalidad de la Zona Oscura por mí mismo, no he sido cambiado por ella?",
  ui_story_5082_50821001_76_dialog_content = "Pensé que no lo había hecho. Con todo mi corazón, deseaba no haberlo hecho.",
  ui_story_5082_50821001_77_dialog_content = "Cuando era joven, pensaba que podía proteger toda la Federación por mi cuenta.",
  ui_story_5082_50821001_78_dialog_content = "Pero después de perder a tantos camaradas, comencé a preguntarme, \"Incluso si pudiera proteger a todos por mi cuenta, ¿cuánto tiempo podría durar realmente?\"",
  ui_story_5082_50821001_79_dialog_content = "Si alguien joven y enojado como ella se parara frente a mí en este momento y me llamara inútil y corrupto...",
  ui_story_5082_50821001_80_dialog_content = "Y juraron derribarme y construir un brillante mundo nuevo en mi lugar...",
  ui_story_5082_50821001_81_dialog_content = "No sé si la detendría, la apoyaría...",
  ui_story_5082_50821001_82_dialog_content = "O incluso...",
  ui_story_5082_50821001_83_dialog_content = "Puede que no entienda la carga del liderazgo como tú, pero como tu amigo, sé con certeza que no eres ese tipo de persona...",
  ui_story_5082_50821001_84_dialog_content = "También estás lejos de ser el único que apoya a Illumina.",
  ui_story_5082_50821001_85_dialog_content = "Sé lo que estás tratando de decir, pero después de verla y recordar todo lo que sucedió en aquel entonces... No puedo evitar sentir un poco de descontento.",
  ui_story_5082_50821001_86_dialog_content = "Aun así, no tengo miedo de compartir estas cosas contigo. Verme así debe ser un poco decepcionante, ¿verdad?",
  ui_story_5082_50821001_87_dialog_content = "Para nada...",
  ui_story_5082_50821001_88_dialog_content = "Regresemos. Los demás deben estar cansados de esperarnos ya.",
  ui_story_5082_50821001_89_dialog_content = "... ¿Entonces la Gran Mariscal se veía a sí misma en sus recuerdos pasados?",
  ui_story_5082_50821001_90_dialog_content = "... ¿Y tú, Barton? ¿Cuánto sabes sobre lo que pasó en aquel entonces?",
  ui_story_5082_50821001_91_dialog_content = "Mi entendimiento es que Reinhardt, Forsakin y Helios estaban planeando algo en secreto en aquel entonces.",
  ui_story_5082_50821001_92_dialog_content = "...",
  ui_story_5082_50821001_93_dialog_content = "También te dije que te apoyaría sin importar qué, pero nunca recibí noticias de nada hasta el final.",
  ui_story_5082_50821001_94_dialog_content = "Solo sabía que de alguna manera estabas involucrado en la explosión del laboratorio, pero en ese momento no tenía forma de investigar el asunto.",
  ui_story_5082_50821001_95_dialog_content = "Nuestras manos ya estaban atadas con la Crisis de Darkover, y había un mundo de trabajo por hacer en las secuelas de la lucha.",
  ui_story_5082_50821001_96_dialog_content = "Todavía no habías llegado a ser comandante cuando nos volvimos a ver, pero ya estabas preparado para ascender mucho más allá de ese rango.",
  ui_story_5082_50821001_97_dialog_content = "Entonces, incluso después de todo lo que pasó... ¿Reinhardt fue promovido de nuevo?",
  ui_story_5082_50821001_98_dialog_content = "Es cierto, y para entonces ella era una persona completamente diferente también: firme, imponente y un terror absoluto en el campo de batalla. Su ya impresionante poder parecía crecer con cada día que pasaba.",
  ui_story_5082_50821001_99_dialog_content = "En comparación con ella y su crecimiento explosivo, yo no era más que un simple soldado chapoteando en el barro.",
  ui_story_5082_50821001_100_dialog_content = "Así que mientras llevaba a cabo mis misiones, también me sometí a mi propio tipo de entrenamiento especial. ¡Ese también fue el momento en que comencé a ser más duro con mis subordinados!",
  ui_story_5082_50821001_101_dialog_content = "Ya veo. Así que fue entonces cuando la 2ª Legión desarrolló una reputación por sus métodos de entrenamiento duros e implacables.",
  ui_story_5082_50821001_102_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_5082_50821001_103_dialog_content = "¡Miau! ¡Y aquí pensé que ya había terminado!",
  ui_story_5082_50821001_104_dialog_content = "¿Por qué siguen chocando contra las paredes?",
  ui_story_5082_50821001_105_dialog_content = "¡Este lugar es demasiado estructuralmente inestable para resistir sus colisiones! ¡Necesitamos detenerlos antes de que las paredes se derrumben y nos entierren vivos!",
  ui_story_5082_50821101_1_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821101_2_dialog_content = "¿Todos están bien?",
  ui_story_5082_50821101_3_dialog_content = "¡Estoy bien! Pero preferiría no volver a caer desde esa altura tan pronto.",
  ui_story_5082_50821101_4_dialog_content = "Estoy bien, Gran Mariscal.",
  ui_story_5082_50821101_5_dialog_content = "Tú que tal, PlayerName?",
  ui_story_5082_50821101_6_dialog_content = "Estoy bien... Gracias por el rescate, Barton. Me habría aplastado justo ahora si no fuera por ti.",
  ui_story_5082_50821101_7_dialog_content = "¡Un poco de entrenamiento extra y no tendrías que depender tanto de mí, sabes!",
  ui_story_5082_50821101_8_dialog_content = "¡Cuando todo esto termine, me aseguraré de agregar el entrenamiento en altitud a tu régimen diario!",
  ui_story_5082_50821101_9_dialog_content = "Parece que aterrizamos en el nivel más bajo del centro de investigación.",
  ui_story_5082_50821101_10_dialog_content = "¿Por qué necesitaban un espacio tan enorme aquí abajo?",
  ui_story_5082_50821101_11_dialog_content = "Puedo responder a eso sin tener que escarbar en mis recuerdos. Aquí es donde lo guardaban.",
  ui_story_5082_50821101_12_dialog_content = "Todo lo que veo es un montón de huesos enormes... ¡Espera! ¡Este es el Coloso que sentí antes!",
  ui_story_5082_50821101_13_dialog_content = "... Dado su estado actual, no es sorpresa que la Subciudad haya comenzado a colapsarse sobre sí misma.",
  ui_story_5082_50821101_14_dialog_content = "... ¿Todavía puedes recordar lo que sucedió durante esos experimentos en aquel entonces, Reinhardt?",
  ui_story_5082_50821101_15_dialog_content = "Mis recuerdos de esa época no son del todo claros, pero sé a ciencia cierta que ella nunca volvió a aparecer después de que me convertí en Comandante de la Legión.",
  ui_story_5082_50821101_16_dialog_content = "Aun así, tengo una buena suposición de lo que pasó aquí.",
  ui_story_5082_50821101_17_dialog_content = "Mis recuerdos de esa época no son del todo claros, pero sé a ciencia cierta que ella nunca volvió a aparecer después de que me convertí en Comandante de la Legión.",
  ui_story_5082_50821101_18_dialog_content = "Aun así, tengo una buena suposición de lo que pasó aquí.",
  ui_story_5082_50821101_19_dialog_content = "Deben haber pensado que enterraron todo, incluido mi pasado...",
  ui_story_5082_50821101_20_dialog_content = "Pero ella sigue persistiendo aquí por alguna razón, como si quisiera decirme algo.",
  ui_story_5082_50821101_21_dialog_content = "Creo que este lugar, o más bien el accidente que ocurrió aquí, es la última pieza del rompecabezas relacionada con ella.",
  ui_story_5082_50821101_22_dialog_content = "Lo que sea que pasó aquí hizo que ella se separara de mi cuerpo...",
  ui_story_5082_50821101_23_dialog_content = "Y también me otorgó el poder abrumador que me hizo el Gran Mariscal que soy hoy.",
  ui_story_5082_50821101_24_dialog_content = "Después de conocer la verdad detrás del Programa Phospherus, ya no me sorprende nada sobre mí mismo.",
  ui_story_5082_50821101_25_dialog_content = "Ulysses una vez dijo que traje una década de paz a todo Illumina... Je, parece que después de todo me convertí en su perfecto súper-soldado.",
  ui_story_5082_50821101_26_dialog_content = "...",
  ui_story_5082_50821101_27_dialog_content = "... No saquemos conclusiones precipitadas todavía. Aún tenemos mucho que investigar.",
  ui_story_5082_50821101_28_dialog_content = "¡Incluso podríamos desenterrar algunas nuevas pruebas que demuestran que tu poder provino de descubrir tu verdadero potencial!",
  ui_story_5082_50821101_29_dialog_content = "¡Mi pelo erizado significa que no estamos solos aquí abajo!",
  ui_story_5082_50821101_30_dialog_content = "<color=#e8d9bb>¡Zumbido—!</color>",
  ui_story_5082_50821101_31_dialog_content = "(Ese ruido... Sé lo que es...)",
  ui_story_5082_50821101_32_option_content = "Enlace mental!",
  ui_story_5082_50821101_33_dialog_content = "... ¡Punta de lanza!",
  ui_story_5082_50821101_34_dialog_content = "Viniste, tal como prometiste.",
  ui_story_5082_50821101_35_dialog_content = "No prometí nada. Eres tú quien me pidió que te encontrara.",
  ui_story_5082_50821101_36_dialog_content = "Pero ahora que estoy aquí, necesito hacerte algunas preguntas.",
  ui_story_5082_50821101_37_dialog_content = "Sé lo que buscas. Deseas aprender más sobre el pasado de una cierta chica, o los pasados de dos chicas diferentes.",
  ui_story_5082_50821101_38_dialog_content = "(¡Lo sabía! Las memorias perdidas de Vice y Reinhardt están vinculadas a los experimentos de selección del Navegante que tuvieron lugar aquí!)",
  ui_story_5082_50821101_39_dialog_content = "¡Dime qué les pasó en ese entonces!",
  ui_story_5082_50821101_40_dialog_content = "Lo que buscas es solo una pequeña cantidad de datos almacenada en este lugar.",
  ui_story_5082_50821101_41_dialog_content = "Pero, los datos están dispersos y fragmentados. En mi actual estado de deterioro, no puedo recuperarlos ni siquiera verlos claramente.",
  ui_story_5082_50821101_42_dialog_content = "¿Me estás pidiendo que te ayude a recuperarlo?",
  ui_story_5082_50821101_43_dialog_content = "Eres tú el que busca los datos, no yo.",
  ui_story_5082_50821101_44_dialog_content = "... ¿Entonces, qué debería hacer?",
  ui_story_5082_50821101_45_dialog_content = "Los que me desgarraron intentaron remodelar mis sistemas utilizando su tecnología obsoleta.",
  ui_story_5082_50821101_46_dialog_content = "Como tal, ya no puedo restaurarlos a su estado original, Caelestite.",
  ui_story_5082_50821101_47_dialog_content = "Ese dispositivo, sin embargo, te permitirá conectarte conmigo y encontrar lo que buscas.",
  ui_story_5082_50821101_48_dialog_content = "Solo tengo que ponérmelo, ¿verdad?",
  ui_story_5082_50821101_49_dialog_content = "Espera PlayerName, ¿qué estás haciendo?",
  ui_story_5082_50821101_50_dialog_content = "Acabo de hacer contacto con la conciencia de Spearhead. Dice que podría ser capaz de encontrar lo que estamos buscando si me pongo esto.",
  ui_story_5082_50821101_51_dialog_content = "¿No recuerdas lo que me dijiste antes de que bajáramos aquí?",
  ui_story_5082_50821101_52_dialog_content = "Lo hago, pero con las cosas como están ahora, esta es nuestra última pista restante.",
  ui_story_5082_50821101_53_dialog_content = "Luchamos tan duro para llegar hasta aquí. No quiero que los esfuerzos de todos sean en vano.",
  ui_story_5082_50821101_54_dialog_content = "Sé que es un poco peligroso, pero todos nos cubrimos las espaldas, ¿no es así?",
  ui_story_5082_50821101_55_dialog_content = "Esto es también a lo que me refería cuando dije que no eres el único que apoya a Illumina. También puedes contar con nosotros, Reinhardt.",
  ui_story_5082_50821101_56_dialog_content = "Incluso si Spearhead intenta hacer algo, estoy seguro de que todos aquí pueden detenerlo. Después de todo, Illumina ya lo derrotó una vez antes, ¿verdad?",
  ui_story_5082_50821101_57_dialog_content = "¡Bien dicho, niño! ¡Nunca me canso de verte defendiendo a tus amigos en su momento de necesidad! Entonces, ¿qué dices, Gran Mariscal?",
  ui_story_5082_50821101_58_dialog_content = "Entendido. Sólo ten cuidado, ¿de acuerdo?",
  ui_story_5082_50821101_59_dialog_content = "Lo haré.",
  ui_story_5082_50821101_60_dialog_content = "(Entonces primero, tengo que poner esto en mi cabeza, y luego...)",
  ui_story_5082_50821101_61_option_content = "Psíquico–",
  ui_story_5082_50821101_62_dialog_content = "Los ajustes al Colossus están casi completos. Notificaré al Oficial de Tecnología de inmediato.",
  ui_story_5082_50821101_63_dialog_content = "Todo lo que necesitamos hacer ahora es encontrar un \"Navegante\" adecuado, y podemos comenzar las pruebas.",
  ui_story_5082_50821101_64_dialog_content = "¿Cuál de los sujetos tiene la mayor compatibilidad?",
  ui_story_5082_50821101_65_dialog_content = "Después de las pruebas que realizamos en nuestros tres candidatos anteriores, comenzaron a omitir información personal para el resto de nuestros sujetos de prueba. Ahora solo sus datos son visibles para nosotros.",
  ui_story_5082_50821101_66_dialog_content = "Recuerdo a esos tres. Sus datos eran bastante prometedores, si recuerdo correctamente, ¿verdad?",
  ui_story_5082_50821101_67_dialog_content = "En efecto. Después de todo, provienen del proyecto Sol Artificial.",
  ui_story_5082_50821101_68_dialog_content = "Sin embargo, hubo diferencias notables entre sus actuaciones y los resultados de las pruebas. El Comité tiene razones para sospechar que tergiversaron deliberadamente sus capacidades durante el experimento.",
  ui_story_5082_50821101_69_dialog_content = "¿En serio?",
  ui_story_5082_50821101_70_dialog_content = "Entonces, independientemente de su compatibilidad con el Coloso, si están dispuestos a mentirnos durante las pruebas, no nos sirven para nada.",
  ui_story_5082_50821101_71_dialog_content = "Si el Comité los encuentra culpables de esto, necesitarán toda la suerte que puedan conseguir.",
  ui_story_5082_50821101_72_dialog_content = "(Uf, no soporto la forma en que hablan estos científicos.)",
  ui_story_5082_50821101_73_dialog_content = "(... Pero tengo que seguir observando.)",
  ui_story_5082_50821101_74_dialog_content = "¿Cuándo llegaremos a la parte de esas dos chicas, Spearhead?",
  ui_story_5082_50821101_75_dialog_content = "Pronto. Lo prometo.",
  ui_story_5082_50821101_76_dialog_content = "Espera a que se extienda la señal, Celestita. ¡Busca un botón especial y luego presiónalo!",
  ui_story_5082_50821101_77_dialog_content = "Un botón especial, ¿eh...",
  ui_story_5082_50821101_78_dialog_content = "¡Ahí! ¡Rápido, Caelestita!",
  ui_story_5082_50821101_79_dialog_content = "(¿Por qué la escena de repente...?)",
  ui_story_5082_50821101_80_dialog_content = "Rápidamente... ¡Presiona el botón! ¡Apúrate—!",
  ui_story_5082_50821101_81_dialog_content = "Urgh, mi cabeza... ¿Qué crees que estás haciendo, Spearhead?!",
  ui_story_5082_50821101_82_dialog_content = "¡Presiona el botón y déjame ser libre!",
  ui_story_5082_50821101_83_dialog_content = "¡Como arma de Eclipse, destruiré a todos los Aurorians en nombre de mis maestros!",
  ui_story_5082_50821101_84_dialog_content = "!",
  ui_story_5082_50821101_85_dialog_content = "¡Muerte a Illumina! ¡Muerte a esos insolentes tontos, y especialmente a ese hombre!",
  ui_story_5082_50821101_86_dialog_content = "Por dejarme en un estado tan lamentable... ¡Juré vengarme de ellos, incluso a costa de mi existencia!",
  ui_story_5082_50821101_87_dialog_content = "(Tanto odio poderoso... ¿Todavía estoy en los archivos de memoria de Spearhead, o es esta su conciencia real?",
  ui_story_5082_50821101_88_dialog_content = "(... Si me está permitiendo ver esto, significa que la mente del Coloso ya está demasiado inestable.)",
  ui_story_5082_50821101_89_dialog_content = "(¡Esta podría ser mi oportunidad para buscar su punto débil!)",
  ui_story_5082_50821101_90_option_content = "¡Alcance Telepático!",
  ui_story_5082_50821101_91_dialog_content = "<color=#e8d9bb>Pero en lugar del punto débil de Spearhead, un grito penetrante resuena aún más claramente.</color>",
  ui_story_5082_50821101_92_dialog_content = "(¡Ese grito... Es ella!)",
  ui_story_5082_50821101_93_dialog_content = "¿Estás ahí? ¿¡Puedes escucharme!?",
  ui_story_5082_50821101_94_dialog_content = "¡Reinhardt!",
  ui_story_5082_50821101_95_dialog_content = "Es extraño. Eres mi primer visitante en este lugar.",
  ui_story_5082_50821101_96_dialog_content = "¡Finalmente tengo la oportunidad de hablar contigo!",
  ui_story_5082_50821101_97_dialog_content = "\"¿Finalmente\"?",
  ui_story_5082_50821101_98_dialog_content = "Reinhardt y yo... ¡El otro tú, quiero decir! ¡Te hemos estado buscando todo este tiempo!",
  ui_story_5082_50821101_99_dialog_content = "...",
  ui_story_5082_50821101_100_dialog_content = "El niño ha estado usando eso durante mucho tiempo. ¿Por qué aún no se ha movido?",
  ui_story_5082_50821101_101_dialog_content = "¡Solo han pasado unos treinta segundos, Comandante Barton! ¡No te apresures tanto!",
  ui_story_5082_50821101_102_dialog_content = "PlayerName dijo que el tiempo fluye de manera diferente dentro del mundo subconsciente. Simplemente sigamos esperando.",
  ui_story_5082_50821101_103_dialog_content = "PlayerName puso su confianza en nosotros, así que deberíamos hacer lo mismo por él.",
  ui_story_5082_50821101_104_dialog_content = "...",
  ui_story_5082_50821101_105_dialog_content = "Mientras tanto, necesitamos estar listos para la batalla en todo momento si vamos a protegerlo.",
  ui_story_5082_50821101_106_dialog_content = "¡Mira tus 3 en punto, Barton!",
  ui_story_5082_50821101_107_dialog_content = "¡Ah! ¡Justo lo que estaba esperando!",
  ui_story_5082_50821101_108_dialog_content = "<color=#e8d9bb>¡Bang, bang, bang!</color>",
  ui_story_5082_50821101_109_dialog_content = "<color=#e8d9bb>De repente, docenas de pequeñas máquinas salen volando de los restos del Coloso.</color>",
  ui_story_5082_50821101_110_dialog_content = "¡Este grandullón solo estaba fingiendo estar muerto!",
  ui_story_5082_50821101_111_dialog_content = "¡Protege PlayerName, y prepárate para luchar!",
  ui_story_5082_50821201_1_dialog_content = "Y eso es más o menos lo que está pasando afuera.",
  ui_story_5082_50821201_2_dialog_content = "¿Reinhardt? ¿No me escuchaste?",
  ui_story_5082_50821201_3_dialog_content = "Hice.",
  ui_story_5082_50821201_4_dialog_content = "Estoy asombrado de que ese terco tonto realmente se convirtiera en Gran Mariscal.",
  ui_story_5082_50821201_5_dialog_content = "Dices eso como si estuvieras hablando de una persona diferente.",
  ui_story_5082_50821201_6_dialog_content = "No está tan lejos de la verdad. Después de todo, hay un mundo de diferencias entre nosotros.",
  ui_story_5082_50821201_7_dialog_content = "Realmente te estás pareciendo mucho a ella en este momento...",
  ui_story_5082_50821201_8_dialog_content = "Debes ser un caelestita, ¿verdad?",
  ui_story_5082_50821201_9_dialog_content = "¿Yo? S-Sí, eso es correcto.",
  ui_story_5082_50821201_10_dialog_content = "¿Crees que puedes usar tus poderos para permitirme hablar con ella?",
  ui_story_5082_50821201_11_dialog_content = "Tengo algo que quiero decirle.",
  ui_story_5082_50821201_12_dialog_content = "Normalmente eso estaría bien, pero en este momento estoy usando uno de los dispositivos de Spearhead para comunicarme contigo.",
  ui_story_5082_50821201_13_dialog_content = "No puedo permitirme desestabilizar aún más la conciencia de Spearhead, o será aún más difícil detenerlo.",
  ui_story_5082_50821201_14_dialog_content = "Y después de descubrir su conexión con los Eclipsites, traer a Reinhardt aquí sería demasiado peligroso.",
  ui_story_5082_50821201_15_dialog_content = "Lo que me recuerda... ¿Qué exactamente te hizo quedarte aquí?",
  ui_story_5082_50821201_16_dialog_content = "¿Estás diciendo que si podemos desviar la atención del Colossus, tendrás una forma de trabajar alrededor de él?",
  ui_story_5082_50821201_17_dialog_content = "Supongo que eso es posible... Pero, ¿cómo vas a llamar la atención de Spearhead?",
  ui_story_5082_50821201_18_dialog_content = "¡Así, por supuesto—!",
  ui_story_5082_50821201_19_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821201_20_dialog_content = "<color=#e8d9bb>Mientras las llamas salvajes se propagan rápidamente por todo el espacio, ella comienza a reírse maniáticamente en medio del furioso infierno.</color>",
  ui_story_5082_50821201_21_dialog_content = "¡Ah, hace tanto tiempo que no me sentía tan bien!",
  ui_story_5082_50821201_22_dialog_content = "Lo siento Colossus, pero después de escuchar que eres amigo de los Eclipsites, ya no siento ni un ápice de simpatía por ti.",
  ui_story_5082_50821201_23_dialog_content = "No puedo lastimar tu cuerpo físico, ¡así que tendré que incendiar toda tu mente! Duele, ¿verdad?!",
  ui_story_5082_50821201_24_dialog_content = "¡Tú! ¡Cómo te atreves—!",
  ui_story_5082_50821201_25_dialog_content = "¡No eres más que datos residuales en mi conciencia! ¡Puedo borrar tu existencia cuando quiera!",
  ui_story_5082_50821201_26_dialog_content = "El espacio está desapareciendo... ¡Spearhead debe estar borrando los datos!",
  ui_story_5082_50821201_27_dialog_content = "Tu conciencia también está siendo almacenada aquí, ¿no es así? ¿Estás seguro de que esto está bien?",
  ui_story_5082_50821201_28_dialog_content = "Estaré bien siempre que no me atrape.",
  ui_story_5082_50821201_29_dialog_content = "¿Qué significa eso?",
  ui_story_5082_50821201_30_dialog_content = "Lo que quiero decir es—",
  ui_story_5082_50821201_31_dialog_content = "¡Corre!",
  ui_story_5082_50821201_32_dialog_content = "¡Sonabas tan seguro hace un momento! ¿Es esta realmente la mejor idea que se te pudo ocurrir?!",
  ui_story_5082_50821201_33_dialog_content = "¡Jajajaja!",
  ui_story_5082_50821201_34_dialog_content = "¡Miau!",
  ui_story_5082_50821201_35_dialog_content = "¡Philyshy! ¿Cómo puedes estar jugando con esas cosas cuando nos están atacando?!",
  ui_story_5082_50821201_36_dialog_content = "¡Lo siento, simplemente parecen una cola grande y larga cuando se unen así! ¡No pude evitarlo!",
  ui_story_5082_50821201_37_dialog_content = "Tiene sentido cuando lo dices de esa manera. El Coloso debe estar controlando cada una de esas \"colas\" para atacarnos...",
  ui_story_5082_50821201_38_dialog_content = "Incluso si no puede mover su cuerpo, su centro de comando sigue siendo lo suficientemente funcional para atacarnos con sus restos esqueléticos!",
  ui_story_5082_50821201_39_dialog_content = "¡Esos son exactamente mis pensamientos!",
  ui_story_5082_50821201_40_dialog_content = "¡Hmph! Por lo que a mí respecta, este Colossus desgastado solo sirve para mover la cola ante nosotros ahora!",
  ui_story_5082_50821201_41_dialog_content = "<color=#e8d9bb>Pozo, pat, pozo, pat—!</color>",
  ui_story_5082_50821201_42_dialog_content = "¿Eh? ¿PlayerName?!",
  ui_story_5082_50821201_43_dialog_content = "De todas las veces para aparecer— ¡Espera, no te muevas!",
  ui_story_5082_50821201_44_dialog_content = "<color=#e8d9bb>Crepitar-</color>",
  ui_story_5082_50821201_45_dialog_content = "... ¿Una corriente eléctrica?",
  ui_story_5082_50821201_46_dialog_content = "¡Aléjate de esa cola, Philyshy! ¡Algo no está bien con ella!",
  ui_story_5082_50821201_47_dialog_content = "Buzz Buzz-",
  ui_story_5082_50821201_48_dialog_content = "¡Los huesos se están multiplicando! Manténganse alerta, todos; el Coloso podría atacar pronto—",
  ui_story_5082_50821201_49_dialog_content = "<color=#e8d9bb>¡Boom! ¡Boom! ¡Boom!</color>",
  ui_story_5082_50821201_50_dialog_content = "¡Puedo oler explosiones que vienen desde dentro de las paredes!",
  ui_story_5082_50821201_51_dialog_content = "¡La estructura va a colapsar! Necesitamos despejar estos cables y encontrar un lugar para resguardarnos!",
  ui_story_5082_50821201_52_dialog_content = "¿Pero qué pasa con PlayerName? Olvídalo, ¡simplemente lo llevaré yo mismo!",
  ui_story_5082_50821201_53_dialog_content = "¡Oye! ¡Gran Mariscal! Ahora no es el momento de—",
  ui_story_5082_50821201_54_dialog_content = "... Puedo escuchar una cuenta regresiva.",
  ui_story_5082_50821201_55_dialog_content = "¡Reinhardt!",
  ui_story_5082_50821201_56_dialog_content = "... Una corriente eléctrica, una explosión, y... sus gritos.",
  ui_story_5082_50821201_57_dialog_content = "Reinhardt!!!",
  ui_story_5082_50821201_58_dialog_content = "Lo mismo sucedió en aquel entonces.",
  ui_story_5082_50821201_59_dialog_content = "<color=#e8d9bb>Una pared cercana explota, enviando cables y rocas estrellándose contra el suelo.</color>",
  ui_story_5082_50821201_60_dialog_content = "¡Corte interminable!",
  ui_story_5082_50821201_61_dialog_content = "<color=#e8d9bb>Barton parte en dos un enorme pedazo de escombros que cae antes de que le caiga encima.</color>",
  ui_story_5082_50821201_62_dialog_content = "<color=#e8d9bb>Entonces él mantiene su impulso en marcha.</color>",
  ui_story_5082_50821201_63_dialog_content = "Barton...",
  ui_story_5082_50821201_64_dialog_content = "¡Ahora no es el momento para soñar despierto! Además, ¿qué te pareció mi técnica hace un momento?",
  ui_story_5082_50821201_65_dialog_content = "¡Jajaja, fue tan feroz como siempre! Gracias, Barton.",
  ui_story_5082_50821201_66_dialog_content = "¡Gracias por siempre luchar a mi lado!",
  ui_story_5082_50821201_67_dialog_content = "Es natural, ¿no es así? Vamos, este lugar es demasiado peligroso para—",
  ui_story_5082_50821201_68_dialog_content = "No te preocupes, estoy bien ahora.",
  ui_story_5082_50821201_69_dialog_content = "Solo necesito repasar lo que sucedió en aquel entonces una última vez.",
  ui_story_5082_50821201_70_dialog_content = "<color=#e8d9bb>El edificio retumba y se derrumba mientras las paredes caen al suelo.</color>",
  ui_story_5082_50821201_71_dialog_content = "<color=#e8d9bb>Como el ojo de una tormenta, Reinhardt se mantiene completamente imperturbable en el centro del caos; incluso el aire a su alrededor parece perfectamente quieto.</color>",
  ui_story_5082_50821201_72_dialog_content = "Ve a cubrirte.",
  ui_story_5082_50821201_73_dialog_content = "Todavía le debo una revancha a este chico.",
  ui_story_5082_50821202_1_dialog_content = "¿Qué es este lugar...?",
  ui_story_5082_50821202_2_dialog_content = "Es un espacio creado por ese dispositivo. Utiliza los datos del sistema de Spearhead como su fundamento.",
  ui_story_5082_50821202_3_dialog_content = "Gracias a que heriste a Spearhead desde el exterior, pudimos refugiarnos aquí de manera segura.",
  ui_story_5082_50821202_4_dialog_content = "Tus poderes son mucho más impresionantes de lo que imaginaba.",
  ui_story_5082_50821202_5_dialog_content = "No solo podrías ayudarme a controlar la conciencia de Spearhead, sino que también podrías traerla aquí tan pronto como desatara su Lumina.",
  ui_story_5082_50821202_6_dialog_content = "Resuelve los combates en el exterior mientras también asegura que la operación del dispositivo permanezca ininterrumpida.",
  ui_story_5082_50821202_7_dialog_content = "Estoy seguro de que lograrás cosas aún más increíbles con este poder en el futuro.",
  ui_story_5082_50821202_8_dialog_content = "Gracias, pero tú fuiste quien ideó este plan... ¡que aún creo que era demasiado peligroso! ¿Y si tus datos se hubieran eliminado?!",
  ui_story_5082_50821202_9_dialog_content = "No existe tal cosa como una batalla sin riesgos.",
  ui_story_5082_50821202_10_dialog_content = "Además, todo salió bien al final, ¿no es así?",
  ui_story_5082_50821202_11_dialog_content = "Logramos poner fin a la lucha aquí y allá, y pude aprender más sobre tus habilidades de Caelestite.",
  ui_story_5082_50821202_12_dialog_content = "Y ahora que sé que puedo confiar en ti, puedo decir con seguridad...",
  ui_story_5082_50821202_13_dialog_content = "Que esta persona no ha cambiado mucho de cómo la recuerdo.",
  ui_story_5082_50821202_14_dialog_content = "Mucho tiempo sin verlo, Reinhardt.",
  ui_story_5082_50821202_15_dialog_content = "Se siente un poco extraño escuchar eso, considerando que solo empecé a recordarte hoy...",
  ui_story_5082_50821202_16_dialog_content = "Pero hace mucho tiempo que no te veo, Reinhardt.",
  ui_story_5082_50821202_17_dialog_content = "Uh, Reinhardt...?",
  ui_story_5082_50821202_18_dialog_content = "¿Si?",
  ui_story_5082_50821202_19_dialog_content = "...",
  ui_story_5082_50821202_20_dialog_content = "¡Jajajaja! Si te facilita las cosas, puedes llamarme \"Renegado\"!",
  ui_story_5082_50821202_21_dialog_content = "Eso es lo que todos solían llamarme a mis espaldas. Sé que no lo decían con buena intención, pero siempre me gustó el nombre.",
  ui_story_5082_50821202_22_dialog_content = "Simplemente no sé si aún recuerdas algo de eso, Reinhardt.",
  ui_story_5082_50821202_23_dialog_content = "Ya veo. No estás seguro si aún soy la misma persona que conociste, y apenas recordé que tú existías.",
  ui_story_5082_50821202_24_dialog_content = "Entonces, ¿por qué no nos conocemos de nuevo?",
  ui_story_5082_50821202_25_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821202_26_dialog_content = "¿Qué significa este retumbar, PlayerName?",
  ui_story_5082_50821202_27_dialog_content = "¡Es Spearhead... nos encontró!",
  ui_story_5082_50821202_28_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821202_29_option_content = "¡Potencia de fuerza!",
  ui_story_5082_50821202_30_dialog_content = "¡Fue tu gente!",
  ui_story_5082_50821202_31_dialog_content = "¡Ustedes fueron los que destruyeron mi cuerpo! ¡Ustedes fueron los que me enterraron vivo durante trece años!",
  ui_story_5082_50821202_32_dialog_content = "¡Ahora muere—!",
  ui_story_5082_50821202_33_option_content = "¡Potencia de fuerza!",
  ui_story_5082_50821202_34_dialog_content = "¡Urgh!",
  ui_story_5082_50821202_35_dialog_content = "Puedo crear una barrera para mantener a Spearhead a raya por ahora, pero este sigue siendo su dominio.",
  ui_story_5082_50821202_36_dialog_content = "Con lo caótico que se ha vuelto su conciencia, no estoy seguro de cuánto tiempo puedo seguir así—",
  ui_story_5082_50821202_37_dialog_content = "¿Quién te está pidiendo que lo detengas?",
  ui_story_5082_50821202_38_dialog_content = "Si alguien te golpea, ¿no debería ser tu primera reacción golpearlos de vuelta?",
  ui_story_5082_50821202_39_dialog_content = "¡No!",
  ui_story_5082_50821202_40_dialog_content = "¡Tus datos aún se están almacenando aquí! Si contraatacamos ahora—",
  ui_story_5082_50821202_41_dialog_content = "No hay nada más inútil que ser indeciso en la batalla.",
  ui_story_5082_50821202_42_dialog_content = "Si tienes una forma de ganar, entonces úsala.",
  ui_story_5082_50821202_43_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5082_50821202_44_dialog_content = "¡Renegado!",
  ui_story_5082_50821202_45_dialog_content = "... ¡Maldita sea!",
  ui_story_5082_50821202_46_dialog_content = "<color=#e8d9bb>Las llamas abrasadoras se levantan una vez más.</color>",
  ui_story_5082_50821202_47_dialog_content = "<color=#e8d9bb>Aunque el incendio es simplemente una representación de los datos de Spearhead siendo destruidos dentro de un espacio mental, sus llamas son más deslumbrantes que las de un fuego real.</color>",
  ui_story_5082_50821202_48_dialog_content = "<color=#e8d9bb>Como un tirano imparable, ella maneja el poder del fuego para consumir todo en su camino.</color>",
  ui_story_5082_50821202_49_dialog_content = "¡¿Te has vuelto loco?! ¡Tu existencia no es más que una cadena de código dentro de mi sistema! ¡Sin un cuerpo físico, desaparecerás!",
  ui_story_5082_50821202_50_dialog_content = "Pero también ganaremos. Tu cuerpo fue destruido hace mucho tiempo, y tu mente nunca pudo seguirme el ritmo.",
  ui_story_5082_50821202_51_dialog_content = "Realmente #%%^$&... Has perdido la cabeza ￥%#......%......%！",
  ui_story_5082_50821202_52_dialog_content = "¡Jajajaja! Lo siento Spearhead, pero ganamos.",
  ui_story_5082_50821202_53_dialog_content = "#%%^$&......!!!",
  ui_story_5082_50821202_54_dialog_content = "Sé que no nos queda mucho tiempo, PlayerName, pero ¿podrías prestarme tu poder una última vez?",
  ui_story_5082_50821202_55_dialog_content = "Antes de irme, me gustaría conocer un poco mejor al otro yo.",
  ui_story_5082_50821202_56_dialog_content = "¡Seguro!",
  ui_story_5082_50821202_57_dialog_content = "No, espera, eso no está bien.",
  ui_story_5082_50821202_58_dialog_content = "<color=#e8d9bb>Renegade camina directamente hacia Reinhardt. Desde esta distancia, pueden verse sus reflejos en los ojos del otro.</color>",
  ui_story_5082_50821202_59_dialog_content = "Creo que hay una mejor manera para que nos entendamos.",
  ui_story_5082_50821202_60_dialog_content = "...",
  ui_story_5082_50821202_61_dialog_content = "¿Recuerdas ese año en que fuiste al chequeo para ingresar a la academia?",
  ui_story_5082_50821202_62_dialog_content = "Eso fue cuando nos conocimos por primera vez.",
  ui_story_5082_50821202_63_dialog_content = "Todos los demás ya se habían ido a casa después de sus exámenes.",
  ui_story_5082_50821202_64_dialog_content = "Pero el doctor me pidió que me quedara.",
  ui_story_5082_50821202_65_dialog_content = "¿Qué pasa?",
  ui_story_5082_50821202_66_dialog_content = "No lo sé.",
  ui_story_5082_50821202_67_dialog_content = "Pero... tengo fiebre todo el tiempo, ¿quizás hay algo malo en mí?",
  ui_story_5082_50821202_68_dialog_content = "Espero que no me impida entrar a la academia.",
  ui_story_5082_50821202_69_dialog_content = "No lo hará.",
  ui_story_5082_50821202_70_dialog_content = "... ¿Cómo sabes eso?",
  ui_story_5082_50821202_71_dialog_content = "Porque puedo verlo.",
  ui_story_5082_50821202_72_dialog_content = "?",
  ui_story_5082_50821202_73_dialog_content = "No estás enfermo ni nada. La fuente de tus fiebres—",
  ui_story_5082_50821202_74_dialog_content = "¿El dragón carmesí está ardiendo en tu espalda?",
  ui_story_5082_50821301_1_dialog_content = "<color=#e8d9bb>Simulacro de fuego real</color>",
  ui_story_5082_50821301_2_dialog_content = "Dime, ¿qué duele más ahora mismo? ¿Tus heridas o tu hambre?",
  ui_story_5082_50821301_3_dialog_content = "Callarse la boca.",
  ui_story_5082_50821301_4_dialog_content = "Oh, ya veo. Apenas puedes mantenerte de pie ahora, ¿verdad? Pobrecito.",
  ui_story_5082_50821301_5_dialog_content = "¡Dije cállate!",
  ui_story_5082_50821301_6_dialog_content = "¿Es esto realmente todo lo que puedes tomar?",
  ui_story_5082_50821301_7_dialog_content = "Si pierdes de manera tan vergonzosa en la batalla, ser ridiculizado será el menor de tus problemas.",
  ui_story_5082_50821301_8_dialog_content = "No volveré a cometer el mismo error nunca más.",
  ui_story_5082_50821301_9_dialog_content = "¿En serio? Porque creo que tus habilidades están defectuosas en su nivel más fundamental.",
  ui_story_5082_50821301_10_dialog_content = "Si pudiera engañarte así, ¿qué te hace pensar que tienes una oportunidad en una batalla real contra los verdaderos Eclipsites? Son mil veces más despiadados que yo, te lo prometo.",
  ui_story_5082_50821301_11_dialog_content = "Si los Aurorianos pudieran usar el conocimiento de los libros de texto para derrotarlos, habríamos ganado la guerra hace mucho tiempo.",
  ui_story_5082_50821301_12_dialog_content = "Esa línea de pensamiento solo conduce a un callejón sin salida.",
  ui_story_5082_50821301_13_dialog_content = "Así que si quieres sobrevivir y realizar tus ambiciones, entonces necesitarás ser más fuerte. Más fuerte que los Aurorians más fuertes del mundo.",
  ui_story_5082_50821301_14_dialog_content = "Y necesitarás ser más astuto que los Eclipsites más malvados en la noche eterna.",
  ui_story_5082_50821301_15_dialog_content = "Solo cuando alcances las alturas más inimaginables podrás asestar el golpe final.",
  ui_story_5082_50821301_16_dialog_content = "¿Lo entiendes?",
  ui_story_5082_50821301_17_dialog_content = "<color=#e8d9bb>Terreno de Entrenamiento de la Academia Militar</color>",
  ui_story_5082_50821301_18_dialog_content = "El entrenamiento de hoy ha terminado, ¡ahora regresa a tu cuartel! El toque de queda está en efecto, ¡así que no salgas después de oscurecer!",
  ui_story_5082_50821301_19_dialog_content = "¡Shhh! Ven a ver qué está pasando en las puertas de la academia, ¡y no dejes que el instructor te vea!",
  ui_story_5082_50821301_20_dialog_content = "Es la 1ra Legión... ¿Qué están haciendo en la academia?",
  ui_story_5082_50821301_21_dialog_content = "¿Y por qué se van con nuestras tiendas de armas?",
  ui_story_5082_50821301_22_dialog_content = "Muchos oficiales han estado entrando y saliendo desde esta tarde.",
  ui_story_5082_50821301_23_dialog_content = "Están reuniendo una gran cantidad de recursos y equipos. Incluso algunos de los instructores más fuertes de la academia aún no han regresado después de irse con ellos.",
  ui_story_5082_50821301_24_dialog_content = "Si mi corazonada es correcta, va a haber una batalla en Gannon City esta noche.",
  ui_story_5082_50821301_25_dialog_content = "...",
  ui_story_5082_50821301_26_dialog_content = "Vi un mapa de defensa en la oficina hace un rato.",
  ui_story_5082_50821301_27_dialog_content = "Hay una zona mal custodiada justo al oeste de las puertas de la ciudad. No resistirá si es atacada.",
  ui_story_5082_50821301_28_dialog_content = "¡Es el lugar perfecto para mostrarle a la Federación lo que podemos hacer!",
  ui_story_5082_50821301_29_dialog_content = "Voy, pero no por ese tipo de razón.",
  ui_story_5082_50821301_30_dialog_content = "Como soldado de Illumina, mis órdenes son proteger a nuestra gente a toda costa.",
  ui_story_5082_50821301_31_dialog_content = "<color=#e8d9bb>Sala de Operaciones Especiales 3</color>",
  ui_story_5082_50821301_32_dialog_content = "¡Rugido!",
  ui_story_5082_50821301_33_dialog_content = "Urgh...",
  ui_story_5082_50821301_34_dialog_content = "(Mi mente... Se está volviendo confusa...)",
  ui_story_5082_50821301_35_dialog_content = "La frecuencia cardíaca y la presión arterial del sujeto están disminuyendo, y su respiración se está volviendo irregular-",
  ui_story_5082_50821301_36_dialog_content = "(¿Cómo pude permitirme morir en un experimento estúpido como este...?)",
  ui_story_5082_50821301_37_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5082_50821301_38_dialog_content = "Ya no se detectan signos vitales. Ahora se confirma la muerte del sujeto.",
  ui_story_5082_50821301_39_dialog_content = "...",
  ui_story_5082_50821301_40_dialog_content = "—!",
  ui_story_5082_50821301_41_dialog_content = "¡¿Qué crees que estás haciendo?!",
  ui_story_5082_50821301_42_dialog_content = "¡Aún no es tu momento de morir!",
  ui_story_5082_50821301_43_dialog_content = "¡Abre ya los ojos! ¡Esos científicos desalmados solo están observando todo esto suceder, murmurando para sí mismos sin un ápice de remordimiento!",
  ui_story_5082_50821301_44_dialog_content = "¡Te están tratando como una herramienta para su conveniencia! Comparado con los datos que buscan, ¡tu vida no vale nada!",
  ui_story_5082_50821301_45_dialog_content = "Si no quieres morir una muerte tan sin sentido, ¡levántate ahora mismo!",
  ui_story_5082_50821301_46_dialog_content = "<color=#e8d9bb>... ¡Bip! Bip... Bip... Bip...</color>",
  ui_story_5082_50821301_47_dialog_content = "... ¿Sigue viva?",
  ui_story_5082_50821301_48_dialog_content = "Oh...",
  ui_story_5082_50821301_49_dialog_content = "Realmente aumentaron la dificultad para este entrenamiento llamado \"fuerza explosiva\".",
  ui_story_5082_50821301_50_dialog_content = "Pero al menos... Por fin ha terminado.",
  ui_story_5082_50821301_51_dialog_content = "Interesante. Sus signos vitales habían desaparecido completamente hace un momento, y sin embargo, fue capaz de recuperar la conciencia y continuar luchando...",
  ui_story_5082_50821301_52_dialog_content = "Lo viste, ¿verdad?",
  ui_story_5082_50821301_53_dialog_content = "Ese imbécil parece aún más decepcionado ahora que cuando pensaba que estabas muerto.",
  ui_story_5082_50821301_54_dialog_content = "Así que no mueras tan fácilmente nunca más.",
  ui_story_5082_50821301_55_dialog_content = "(Mmm...)",
  ui_story_5082_50821301_56_dialog_content = "<color=#e8d9bb>Laboratorio Secreto</color>",
  ui_story_5082_50821301_57_dialog_content = "Siempre nos dices que seamos más honestos contigo, y sin embargo, nunca nos dices cuando algo te va mal.",
  ui_story_5082_50821301_58_dialog_content = "... ¿Es tan obvio?",
  ui_story_5082_50821301_59_dialog_content = "Helios también lo ve. Simplemente no dice nada porque no quiere molestarte.",
  ui_story_5082_50821301_60_dialog_content = "Pero no soy tan considerado como él, por eso te estoy preguntando ahora mismo.",
  ui_story_5082_50821301_61_dialog_content = "¿Qué demonios está pasando, Reinhardt?",
  ui_story_5082_50821301_62_dialog_content = "¿Qué tipo de pruebas te están haciendo que sigues apareciendo con heridas por todo el cuerpo?",
  ui_story_5082_50821301_63_dialog_content = "Eres la persona más fuerte entre tus compañeros, sin lugar a dudas. Entonces, ¿por qué te están haciendo esto?",
  ui_story_5082_50821301_64_dialog_content = "...",
  ui_story_5082_50821301_65_dialog_content = "Porque aunque eres fuerte, tienes la tendencia a volverte rebelde cuando necesitan que sigas órdenes.",
  ui_story_5082_50821301_66_dialog_content = "Querían embotar tu filo, aplastar tu orgullo y convertirte en un buen soldado pequeño como todos los demás.",
  ui_story_5082_50821301_67_dialog_content = "Pero no les diste lo que querían, y ahora te temen. No tienen uso para una espada que corta a su portador.",
  ui_story_5082_50821301_68_dialog_content = "Si no quieres ser arrojado al horno, para ser remodelado a su antojo, debes mantenerte firme. Recuerda quién eres y sigue aferrándote.",
  ui_story_5082_50821301_69_dialog_content = "Todavía no he comprendido toda la situación.",
  ui_story_5082_50821301_70_dialog_content = "¿Podemos posponer la respuesta a esa pregunta, negador? Te prometo que te contaré todo una vez que conozca la verdad.",
  ui_story_5082_50821301_71_dialog_content = "Bueno, es una falta de conducta científica entrometerse en los asuntos confidenciales de otras personas sin permiso.",
  ui_story_5082_50821301_72_dialog_content = "Pero si algo te sucede, entonces voy a tirar esos escrúpulos por la ventana sin importar quién me haga responsable.",
  ui_story_5082_50821301_73_dialog_content = "Prometo que seré cuidadoso.",
  ui_story_5082_50821301_74_dialog_content = "(Lo mismo va para ustedes dos.)",
  ui_story_5082_50821301_75_dialog_content = "<color=#e8d9bb>¿¿¿???</color>",
  ui_story_5082_50821301_76_dialog_content = "Dónde estoy...?",
  ui_story_5082_50821301_77_dialog_content = "¿Qué estoy haciendo...?",
  ui_story_5082_50821301_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_79_dialog_content = "!",
  ui_story_5082_50821301_80_dialog_content = "¡Rooooooor!",
  ui_story_5082_50821301_81_dialog_content = "Tengo que... ¡Luchar contra los Eclipsites...!",
  ui_story_5082_50821301_82_dialog_content = "Graaah—",
  ui_story_5082_50821301_83_dialog_content = "Lucha...",
  ui_story_5082_50821301_84_dialog_content = "¡Rugido!",
  ui_story_5082_50821301_85_dialog_content = "¡Lucha!",
  ui_story_5082_50821301_86_dialog_content = "Aún no ha terminado...",
  ui_story_5082_50821301_87_dialog_content = "¡Tengo que seguir—!",
  ui_story_5082_50821301_88_dialog_content = "¡Despierta!",
  ui_story_5082_50821301_89_dialog_content = "¡Sal de eso! ¡No permitas que te conviertan en otra herramienta a su disposición!",
  ui_story_5082_50821301_90_dialog_content = "... Lo sé.",
  ui_story_5082_50821301_91_dialog_content = "Es solo un mal reflejo del que aún no me he deshecho. No dejaré que este tipo de cosas me controle.",
  ui_story_5082_50821301_92_dialog_content = "Pero, ¿qué estás haciendo tú también aquí?",
  ui_story_5082_50821301_93_dialog_content = "¡Espera, qué hora es!? El plan...",
  ui_story_5082_50821301_94_dialog_content = "Hoy es el día en que van a usar a esa pequeña niña para activar el Colossus.",
  ui_story_5082_50821301_95_dialog_content = "Tengo que apegarme al plan— ¡Nngh!",
  ui_story_5082_50821301_96_dialog_content = "El agente adormecedor aún no ha terminado su efecto, así que deja de balbucear.",
  ui_story_5082_50821301_97_dialog_content = "Después de todo, es obvio que alguien descubrió nuestro plan.",
  ui_story_5082_50821301_98_dialog_content = "... ¿Dónde están los demás?",
  ui_story_5082_50821301_99_dialog_content = "¿Qué parezco, un sistema de vigilancia de Illumina? Solo puedo vigilarte.",
  ui_story_5082_50821301_100_dialog_content = "Todavía estamos cerca de la base. Tu entrenamiento diario hace que sea fácil para ellos seguirte la pista, pero tus amigos aún tienen tiempo para retroceder.",
  ui_story_5082_50821301_101_dialog_content = "Si quieres verificar cómo están, tu única opción es escapar.",
  ui_story_5082_50821301_102_dialog_content = "¡Ahora apúrate! Una vez que esos investigadores lleguen aquí, será demasiado tarde.",
  ui_story_5082_50821301_103_dialog_content = "...",
  ui_story_5082_50821301_104_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5082_50821301_105_dialog_content = "¿Oh? Ya despierto, veo. Parece que tu cuerpo se ha vuelto mucho más fuerte recientemente.",
  ui_story_5082_50821301_106_dialog_content = "Adelante, acuéstate de nuevo. Pronto te inyectaremos con tu próximo tratamiento.",
  ui_story_5082_50821301_107_dialog_content = "... Disculpa, pero los tratamientos que he estado recibiendo últimamente...",
  ui_story_5082_50821301_108_dialog_content = "Supresor #05... Ronda 13 de tratamiento...",
  ui_story_5082_50821301_109_dialog_content = "¿Qué es esa mirada patética en tu cara?! ¡Ella tiene una pistola, así que tómala y mátala! ¡Esa será nuestra oportunidad para escapar!",
  ui_story_5082_50821301_110_dialog_content = "<color=#e8d9bb>Reinhardt se levanta y agarra al investigador por el brazo, pero inmediatamente se siente aturdido por una sensación abrumadora de mareo.</color>",
  ui_story_5082_50821301_111_dialog_content = "<color=#e8d9bb>Dos investigadores más entran corriendo a la sala. Mientras uno de ellos somete a Reinhardt, el otro mantiene el arma lejos de ella—</color>",
  ui_story_5082_50821301_112_dialog_content = "(¡No—!)",
  ui_story_5082_50821301_113_dialog_content = "<color=#e8d9bb>Se inyecta un gran volumen de supresor en el cuerpo de Renegade.</color>",
  ui_story_5082_50821301_114_dialog_content = "Tú...",
  ui_story_5082_50821301_115_dialog_content = "¡Corre!",
  ui_story_5082_50821301_116_dialog_content = "¡No dejes que te roben tu poder! ¡Ahora corre—!!",
  ui_story_5082_50821301_117_dialog_content = "<color=#e8d9bb>Reinhardt aprieta los dientes mientras se apresura a salir por la puerta.</color>",
  ui_story_5082_50821301_118_dialog_content = "Huff... Huff...",
  ui_story_5082_50821301_119_dialog_content = "Mi cuerpo... Se está quemando...",
  ui_story_5082_50821301_120_dialog_content = "(Y mi mente... ¿Por qué es así...?)",
  ui_story_5082_50821301_121_dialog_content = "(No, esto no está bien... No estoy en el campo de entrenamiento, pero estoy...)",
  ui_story_5082_50821301_122_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_5082_50821301_123_dialog_content = "!",
  ui_story_5082_50821301_124_dialog_content = "¡No te detengas!",
  ui_story_5082_50821301_125_dialog_content = "¡Eres tú! ¡¿Estás bien?!",
  ui_story_5082_50821301_126_dialog_content = "¡Deja de hablar y corre!",
  ui_story_5082_50821301_127_dialog_content = "... Bien.",
  ui_story_5082_50821301_128_dialog_content = "Ya no podemos volver atrás. Tendremos que seguir adentrándonos más.",
  ui_story_5082_50821301_129_dialog_content = "Helios marcó en su mapa la habitación donde están guardando el Colossus. Está en el otro extremo de la base de investigación, y está cerca del exterior.",
  ui_story_5082_50821301_130_dialog_content = "Podemos buscar una salida desde allí, y luego encontrar otra Entrañas—",
  ui_story_5082_50821301_131_dialog_content = "\"Plan B\"...",
  ui_story_5082_50821301_132_dialog_content = "Apuesto a que te arrepientes de no haber escuchado a Denier o de no haber pensado más en su plan, ¿verdad?",
  ui_story_5082_50821301_133_dialog_content = "Me culpo a mí mismo más que a cualquier otra cosa.",
  ui_story_5082_50821301_134_dialog_content = "Todo esto es debido a mi ignorancia y orgullo.",
  ui_story_5082_50821301_135_dialog_content = "Mi ignorancia me llevó a seguir órdenes ciegamente...",
  ui_story_5082_50821301_136_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_137_dialog_content = "Reinhardt, listo para el deber.",
  ui_story_5082_50821301_138_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_139_dialog_content = "Lo siento, estoy un poco cansado así que iré directo a la cama.",
  ui_story_5082_50821301_140_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_141_dialog_content = "...",
  ui_story_5082_50821301_142_dialog_content = "Y mi orgullo me engañó haciéndome pensar que podría lograr mis sueños algún día mientras lo soportara.",
  ui_story_5082_50821301_143_dialog_content = "Los Eclipsites a los que te enfrentas actualmente son los especímenes más débiles en el experimento.",
  ui_story_5082_50821301_144_dialog_content = "Este entrenamiento está diseñado para convertirte en el soldado más poderoso de Illumina. Si no puedes derrotarlos, tendremos que reconsiderar tu candidatura para el programa.",
  ui_story_5082_50821301_145_dialog_content = "Je... ¿Quién dijo que no podía vencerlos?!",
  ui_story_5082_50821301_146_dialog_content = "¡Vamos de nuevo!",
  ui_story_5082_50821301_147_dialog_content = "Resulta que cuando las personas están atrapadas en una red, sus llamadas \"luchas\" no hacen más que estrangularlas aún más rápido.",
  ui_story_5082_50821301_148_dialog_content = "¡Guarda ese tipo de charla! ¡Este no es el momento ni el lugar para tu autocompasión!",
  ui_story_5082_50821301_149_dialog_content = "Sabes, los sueños no tienen que ser imposibles de alcanzar.",
  ui_story_5082_50821301_150_dialog_content = "?",
  ui_story_5082_50821301_151_dialog_content = "No soporto seguir una rutina, y odio la sensación de vivir la vida como si estuviera leyendo un guion.",
  ui_story_5082_50821301_152_dialog_content = "Si siguen intentando encasillarme, seguiré rompiendo esa caja, incluso si tengo que quemarla hasta convertirla en cenizas.",
  ui_story_5082_50821301_153_dialog_content = "Pero tú eres diferente.",
  ui_story_5082_50821301_154_dialog_content = "Aunque todos te admiren y alaben tu fuerza e inteligencia, eres tan tonto como cualquier otro.",
  ui_story_5082_50821301_155_dialog_content = "Ser terco es ser inflexible, tolerante a un defecto y no estar dispuesto a ceder incluso cuando te encuentras con un muro.",
  ui_story_5082_50821301_156_dialog_content = "Te lo dije tantas veces, esas pruebas estaban destinadas a matarte, no a hacerte más fuerte.",
  ui_story_5082_50821301_157_dialog_content = "Pero nunca escuchaste, y por eso terminamos en este lío.",
  ui_story_5082_50821301_158_dialog_content = "Yo...",
  ui_story_5082_50821301_159_dialog_content = "Pero es porque no escuchas...",
  ui_story_5082_50821301_160_dialog_content = "Que te has afinado a ti mismo en la hoja más afilada y brillante de Illumina.",
  ui_story_5082_50821301_161_dialog_content = "Por eso esos bastardos harán cualquier cosa para controlarte, incluso si eso significa ponerse en peligro a sí mismos.",
  ui_story_5082_50821301_162_dialog_content = "Son cobardes, pero su codicia supera su miedo. Quieren podar tus ramas hasta que te conviertas en su soldado perfecto.",
  ui_story_5082_50821301_163_dialog_content = "En cuanto a mí, solo soy una de esas ramas.",
  ui_story_5082_50821301_164_dialog_content = "¡Eso es suficiente! No necesito escuchar el resto.",
  ui_story_5082_50821301_165_dialog_content = "Sé que piensas que soy terco, pero eso solo significa que nunca me rendiré en las cosas que más me importan.",
  ui_story_5082_50821301_166_dialog_content = "Jaja, esta podría ser la primera vez que te escucho admitir esto a ti mismo.",
  ui_story_5082_50821301_167_dialog_content = "Desafortunadamente para ti, todavía no soy del tipo que sigue las órdenes de otras personas.",
  ui_story_5082_50821301_168_dialog_content = "La razón por la que todos esos tratamientos supresores no pudieron hacerme desaparecer es porque no los dejé.",
  ui_story_5082_50821301_169_dialog_content = "Pero ahora que quieres que me quede, he decidido cambiar de opinión.",
  ui_story_5082_50821301_170_dialog_content = "Lograste hacerlo sin mí. Incluso lograste tu sueño de convertirte en Gran Mariscal.",
  ui_story_5082_50821301_171_dialog_content = "¡No digas eso! No sería la misma persona si no fuera por ti.",
  ui_story_5082_50821301_172_dialog_content = "<color=#e8d9bb>¡Bip-bip-bip-bip-bip!!!!</color>",
  ui_story_5082_50821301_173_dialog_content = "¿Una alarma?",
  ui_story_5082_50821301_174_dialog_content = "El sitio de activación del Colossus está justo adelante. Algo debe haber salido mal.",
  ui_story_5082_50821301_175_dialog_content = "—!",
  ui_story_5082_50821301_176_dialog_content = "Este grito... ¡Es esa chica pidiendo ayuda!",
  ui_story_5082_50821301_177_dialog_content = "¡Oye!",
  ui_story_5082_50821301_178_dialog_content = "<color=#e8d9bb>Sala de Control</color>",
  ui_story_5082_50821301_179_dialog_content = "<color=#e8d9bb>Bip-bip-bip-bip—</color>",
  ui_story_5082_50821301_180_dialog_content = "... ¿Su compatibilidad disminuyendo?",
  ui_story_5082_50821301_181_dialog_content = "¿Ha ocurrido algo malo, Oficial de Tecnología?",
  ui_story_5082_50821301_182_dialog_content = "Los <color=#FFB400>parámetros</color> reales para el Navegante de Reserva son diferentes a los del informe. ¿Alguien ha visto al sujeto de prueba en persona?",
  ui_story_5082_50821301_183_dialog_content = "No, señora... El Comité no lo permitirá, pero sé que leí los parámetros en el informe—",
  ui_story_5082_50821301_184_dialog_content = "¡No importa ahora! El Coloso está a punto de perder el control—",
  ui_story_5082_50821301_185_dialog_content = "¡O-Oficial de Tecnología! ¿¡Adónde vas!?",
  ui_story_5082_50821301_X185_dialog_content = "¡Necesito estar allí ahora! ¡El sujeto está en peligro!",
  ui_story_5082_50821301_186_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821301_187_dialog_content = "<color=#e8d9bb>—!</color>",
  ui_story_5082_50821301_188_dialog_content = "¡Todo el personal, evacúe inmediatamente! ¡Todo el personal, evacúe inmediatamente!",
  ui_story_5082_50821301_189_dialog_content = "... ¡E-El Coloso se ha vuelto loco!",
  ui_story_5082_50821301_190_dialog_content = "¡Ajustar los parámetros ya no está haciendo nada!",
  ui_story_5082_50821301_191_dialog_content = "A este ritmo, la chica dentro de la sala de pilotaje...",
  ui_story_5082_50821301_192_dialog_content = "Sacar al piloto de allí ahora solo empeorará las cosas.",
  ui_story_5082_50821301_193_dialog_content = "Este lío está ahora en manos del Oficial de Tecnología, no en las nuestras. Estoy seguro de que el Comité encontrará una solución.",
  ui_story_5082_50821301_194_dialog_content = "Además, la única forma en que podemos obtener los datos que necesitamos para futuros intentos de activación es manteniendo a ese niño allí dentro.",
  ui_story_5082_50821301_195_dialog_content = "...",
  ui_story_5082_50821301_196_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821301_197_dialog_content = "Mira ahí abajo... ¿Qué le pasó a este lugar?",
  ui_story_5082_50821301_198_dialog_content = "...",
  ui_story_5082_50821301_199_dialog_content = "¡Detente! Sé lo que estás pensando, ¡pero acabas de evitar la muerte por poco!",
  ui_story_5082_50821301_200_dialog_content = "Si bajas allí en tu estado actual, puedes olvidarte de convertirte en Gran Mariscal, ¡o cualquier otra cosa, para el caso!",
  ui_story_5082_50821301_201_dialog_content = "Si simplemente me quedo de brazos cruzados y veo morir a esa pobre pequeña niña, entonces tampoco merezco convertirme en Gran Mariscal.",
  ui_story_5082_50821301_202_dialog_content = "Quería decirte algo antes. Sé que siempre te has mostrado ante mí de esta manera...",
  ui_story_5082_50821301_203_dialog_content = "Pero al final, siempre seremos la misma persona.",
  ui_story_5082_50821301_204_dialog_content = "¡Así que deja de mirarme como si fuera una gran decepción! Incluso yo—",
  ui_story_5082_50821301_205_dialog_content = "¡Puedo tener mis momentos rebeldes!",
  ui_story_5082_50821301_206_dialog_content = "Dijeron que mi sueño de convertirme en Gran Mariscal era como un pozo sin fondo, uno que constantemente me atraía y absorbía mi espíritu...",
  ui_story_5082_50821301_207_dialog_content = "Un sueño que me consumiría y finalmente me mataría.",
  ui_story_5082_50821301_208_dialog_content = "Pero el Gran Mariscal al que aspiro ser no se preocupa por el estatus o la gloria.",
  ui_story_5082_50821301_209_dialog_content = "Todo lo que necesita es la fuerza y autoridad para proteger a los heridos y sufrientes bajo su cuidado.",
  ui_story_5082_50821301_210_dialog_content = "Por eso no importa si Illumina me acepta o no.",
  ui_story_5082_50821301_211_dialog_content = "¡Como mínimo, voy a ser el Gran Mariscal de esa pequeña niña!!!",
  ui_story_5082_50821301_212_dialog_content = "Cuando nos conocimos por primera vez, dijiste que había un dragón ardiente en mi espalda.",
  ui_story_5082_50821301_213_dialog_content = "Todavía no entiendo completamente lo que quisiste decir con eso, pero si tengo el poder de convertirme en fuego...",
  ui_story_5082_50821301_214_dialog_content = "¡Entonces déjame ser el fuego que queme este podrido status quo!",
  ui_story_5082_50821301_215_dialog_content = "...",
  ui_story_5082_50821301_216_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5082_50821301_217_dialog_content = "(¡Todavía puedo escuchar su voz! ¡Está en algún lugar dentro del Colossus!)",
  ui_story_5082_50821301_218_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5082_50821301_219_dialog_content = "(Pero si no me ocupo de su cola primero— ¡¿Eh?!)",
  ui_story_5082_50821301_220_dialog_content = "(¿El supresor que me inyectaron... también está suprimiendo mis Luminatics?!)",
  ui_story_5082_50821301_221_dialog_content = "Realmente eres un tonto...",
  ui_story_5082_50821301_222_dialog_content = "Me llamaron tu alter ego y dijeron que soy el lado rebelde de tu personalidad que por lo demás es obediente.",
  ui_story_5082_50821301_223_dialog_content = "Intentaron deshacerse de mí para que solo quedara tu lado \"útil\".",
  ui_story_5082_50821301_224_dialog_content = "Pero a pesar de toda su supuesta inteligencia, nunca nos vieron por lo que realmente somos.",
  ui_story_5082_50821301_225_dialog_content = "La rebelión y la obediencia son solo dos tipos diferentes de leña. Con la cantidad correcta de calor—",
  ui_story_5082_50821301_226_dialog_content = "¡Ambos se encenderán y se convertirán en una bola de fuego imparable!",
  ui_story_5082_50821301_227_dialog_content = "¡Hola! Reinhardt!",
  ui_story_5082_50821301_228_dialog_content = "<color=#e8d9bb>El borde carmesí de su vestido ondeaba en el calor de la batalla</color>",
  ui_story_5082_50821301_229_dialog_content = "<color=#e8d9bb>Con una sonrisa desenfrenada y desafiante, se gira y mira a su otro yo desde lejos.</color>",
  ui_story_5082_50821301_230_dialog_content = "Mi poder está ahora en tus manos. ¡Úsalo bien!",
  ui_story_5082_50821301_231_dialog_content = "<color=#e8d9bb>Auge-!!!</color>",
  ui_story_5082_50821301_232_dialog_content = "<color=#e8d9bb>Una ola de Lumina surge a través de las llamas danzantes.</color>",
  ui_story_5082_50821301_233_dialog_content = "<color=#e8d9bb>Partículas brillantes se dispersan a través del calor abrasador, y comienzan a converger en el siguiente instante...</color>",
  ui_story_5082_50821301_234_dialog_content = "<color=#e8d9bb>Un enorme dragón de pura llama rodea a Reinhardt mientras atraviesa la cola del Coloso.</color>",
  ui_story_5082_50821301_235_dialog_content = "<color=#e8d9bb>Renegade desaparece con un estruendo, pero su risa y mirada ardiente perduran.</color>",
  ui_story_5082_50821301_236_dialog_content = "¡Quémalo todo a gusto de tu corazón!",
  ui_story_5082_50821301_237_dialog_content = "¡Nunca dejes que ninguno de ellos robe tu poder!",
  ui_story_5082_50821301_238_dialog_content = "¡Claro!",
  ui_story_5082_50821301_239_dialog_content = "¡¡—Final iluminado!!",
  ui_story_5082_50821400_1_dialog_content = "¿Estamos afuera de nuevo?",
  ui_story_5082_50821400_2_dialog_content = "¡Ah! ¿Pero qué pasa con Spearhead y los otros Reinhardt?!",
  ui_story_5082_50821400_3_dialog_content = "Ese grandote se convirtió en un montón de chatarra hace mucho tiempo.",
  ui_story_5082_50821400_4_dialog_content = "Solo podía luchar contra nosotros con una sola cola. El resto de su cuerpo estaba completamente fuera de servicio.",
  ui_story_5082_50821400_5_dialog_content = "¡Si esa cosa todavía pudiera moverse, nunca habríamos tenido una oportunidad!",
  ui_story_5082_50821400_6_dialog_content = "En cuanto a Reinhardt, ¿no es ella la de allí?",
  ui_story_5082_50821400_7_dialog_content = "No, no estoy hablando de...",
  ui_story_5082_50821400_8_dialog_content = "<color=#e8d9bb>Reinhardt camina en silencio. En sus manos está la máquina que había unido los destinos de tantas personas.</color>",
  ui_story_5082_50821400_9_dialog_content = "... Ella ya no está aquí, ¿verdad?",
  ui_story_5082_50821400_10_dialog_content = "No, pero ella ganó. Siempre gana, incluso contra mi yo actual.",
  ui_story_5082_50821400_11_dialog_content = "Uh... ¿Qué pasó exactamente allí?",
  ui_story_5082_50821400_12_dialog_content = "Tal vez fue solo mi suerte...",
  ui_story_5082_50821400_13_dialog_content = "De acuerdo con el procedimiento normal, ella debería haber desaparecido de mi vida después de que mi fiebre disminuyó en aquel entonces.",
  ui_story_5082_50821400_14_dialog_content = "Pero ella nunca desapareció en absoluto...",
  ui_story_5082_50821400_15_dialog_content = "Lograron matarme, pero no lograron destruirnos.",
  ui_story_5082_50821400_16_dialog_content = "...",
  ui_story_5082_50821400_17_dialog_content = "<color=#e8d9bb>Bzzt, bzzt—</color>",
  ui_story_5082_50821400_18_dialog_content = "(Es la punta de lanza...)",
  ui_story_5082_50821400_19_dialog_content = "Morir... Todos ustedes...",
  ui_story_5082_50821400_20_dialog_content = "¿Todavía no has aceptado la derrota?",
  ui_story_5082_50821400_21_dialog_content = "Tu actitud me disgusta, Caelestite.",
  ui_story_5082_50821400_22_dialog_content = "No tengo razón para ser amigable con alguien que me ha engañado y ha dañado a mis aliados.",
  ui_story_5082_50821400_23_dialog_content = "Los aurorianos no tienen forma de recibir mi poder.",
  ui_story_5082_50821400_24_dialog_content = "Fue su hambre de ese poder, que nunca les perteneció, lo que llevó a su desaparición final.",
  ui_story_5082_50821400_25_dialog_content = "Pero ella y esa pequeña niña eran diferentes...",
  ui_story_5082_50821400_26_dialog_content = "Sus poderes eran mayores que los de cualquier otro Auroriano, y por eso también me vi obligado a pagar un precio.",
  ui_story_5082_50821400_27_dialog_content = "¿Realmente crees que puedes compararte con Reinhardt...?",
  ui_story_5082_50821400_28_dialog_content = "¿Qué pasa con Vice? ¿Qué tipo de poder estaba escondido dentro de esa niña de cuatro años?",
  ui_story_5082_50821400_29_dialog_content = "El poder para pilotarme...",
  ui_story_5082_50821400_30_dialog_content = "... ¿Piloto tú?",
  ui_story_5082_50821400_31_dialog_content = "Mi último aterrizaje forzoso me quitó las alas.",
  ui_story_5082_50821400_32_dialog_content = "Y mi última batalla me quitó el cuerpo.",
  ui_story_5082_50821400_33_dialog_content = "Nada queda de mi antiguo yo. No puedo lograr nada en mi estado actual.",
  ui_story_5082_50821400_34_dialog_content = "Solo porque simpatizo contigo no significa que pueda perdonarte por las cosas que has hecho en el pasado.",
  ui_story_5082_50821400_35_dialog_content = "Sin embargo, puedo entregar un mensaje en tu lugar.",
  ui_story_5082_50821400_36_dialog_content = "Debes saber mucho sobre los Eclipsites, ¿verdad? A cambio de esa información, Illumina podría estar dispuesto a construir un nuevo cuerpo para ti.",
  ui_story_5082_50821400_37_dialog_content = "... ¿Deseas ordenarme? Comparado con mi anterior Navegante, no eres ni remotamente digno.",
  ui_story_5082_50821400_38_dialog_content = "¿Tu Navegante anterior... también era un Celestita?",
  ui_story_5082_50821400_39_dialog_content = "Hmph. Mi último Navegador fue un traidor, nada más.",
  ui_story_5082_50821400_40_dialog_content = "¡No! ¡Ustedes son los que siguen órdenes! Esas dos chicas y yo seguimos nuestros propios caminos ahora. ¡Somos fieles a nosotras mismas!",
  ui_story_5082_50821400_41_dialog_content = "¿Ustedes mismos?",
  ui_story_5082_50821400_42_dialog_content = "Hmm. Ya no estoy seguro de quién soy yo mismo.",
  ui_story_5082_50821400_43_dialog_content = "Bueno, quienquiera que seas, no tienes permitido lastimar a más personas, sin importar tus razones.",
  ui_story_5082_50821400_44_dialog_content = "Di lo que quieras, pero aún no tengo ninguna razón para obedecerte.",
  ui_story_5082_50821400_45_dialog_content = "%$^#$^%^!......",
  ui_story_5082_50821400_46_dialog_content = "...",
  ui_story_5082_50821400_47_dialog_content = "Entonces, el otro Gran Mariscal y Yumi... No son los mismos, ¿verdad? Tiene sentido, ya que solo el Gran Mariscal puede verla...",
  ui_story_5082_50821400_48_dialog_content = "Espera...",
  ui_story_5082_50821400_49_dialog_content = "Vice, una niña de cuatro años, y Reinhardt, la estrella en ascenso de la Federación en ese momento... Ambos estaban involucrados en esos experimentos...",
  ui_story_5082_50821400_50_dialog_content = "Entonces, ¿por qué no estaba al tanto de eso...?",
  ui_story_5082_50821400_51_dialog_content = "¡D-Dame un segundo! Yo... Yo necesito arreglar algunas cosas...",
  ui_story_5082_50821400_52_dialog_content = "Sé que la Oficial Técnico Gronru fue nombrada para su puesto durante la Crisis de Darkover, y su primera orden del día fue activar el Colossus.",
  ui_story_5082_50821400_53_dialog_content = "Intenté preguntarle sobre eso una vez... ¡Incluso fui discreto al respecto!",
  ui_story_5082_50821400_54_dialog_content = "Pero ella simplemente continuó ignorándome y escribiendo la palabra \"parámetros\" una y otra vez en su computadora...",
  ui_story_5082_50821400_55_dialog_content = "¡Bueno, parece que he encontrado más o menos la información que estaba buscando!",
  ui_story_5082_50821400_56_dialog_content = "Aparte de la participación de Gronru en el incidente... muchos otros sujetos de prueba resultaron gravemente heridos.",
  ui_story_5082_50821400_57_dialog_content = "Ni siquiera quiero pensar en lo que habría pasado si el Gran Mariscal no hubiera salvado a Vice en aquel entonces...",
  ui_story_5082_50821400_58_dialog_content = "Teniendo en cuenta todo lo que había hecho hasta ese momento, salvar a Vice fue simplemente el gran final de mi historia.",
  ui_story_5082_50821400_59_dialog_content = "No sabía quién era Vice en ese momento. Todo lo que quería hacer era convertirme en su Gran Mariscal en ese instante.",
  ui_story_5082_50821400_60_dialog_content = "...",
  ui_story_5082_50821400_61_dialog_content = "En tus ojos, el Gran Mariscal es alguien con \"la fuerza y autoridad para proteger a los heridos y sufrientes bajo su vigilancia.\"",
  ui_story_5082_50821400_62_dialog_content = "¿No te convierte eso en la única persona apta para el trabajo, Reinhardt?",
  ui_story_5082_50821400_63_dialog_content = "Pero esta fuerza es la misma marca que nos ha impuesto nuestra rebelión inquebrantable.",
  ui_story_5082_50821400_64_dialog_content = "En ese entonces, era solo un cabeza caliente, completamente alimentado por la ira. No entendía lo que significaba ser el Gran Mariscal, todo lo que me importaba era impartir mi propia marca de justicia y nada más.",
  ui_story_5082_50821400_65_dialog_content = "En cuanto a mi autoridad...",
  ui_story_5082_50821400_66_dialog_content = "No tenía idea de que esos experimentos unirían nuestros destinos de esta manera.",
  ui_story_5082_50821400_67_dialog_content = "Helios, Negador y yo... Nos volvimos sorprendentemente cercanos el uno al otro.",
  ui_story_5082_50821400_68_dialog_content = "Pero al final, tuvimos que ir por caminos separados.",
  ui_story_5082_50821400_69_dialog_content = "Helios pasó por tanto sufrimiento. Cologne y Vaughn fueron enviados a los frentes de batalla más peligrosos y nunca se supo de ellos de nuevo.",
  ui_story_5082_50821400_70_dialog_content = "Pero en comparación con ellos, Denier... o más bien Forsakin, fue quien más alineó su decisión con nuestras intenciones originales.",
  ui_story_5082_50821400_71_dialog_content = "Observé cómo cada uno de mis aliados más cercanos desaparecía uno por uno.",
  ui_story_5082_50821400_72_dialog_content = "Y ahora que todos se han ido, finalmente me he convertido en el Gran Mariscal de Illumina. Esa es la ironía de mi autoridad.",
  ui_story_5082_50821400_73_dialog_content = "Eso no es cierto, Reinhardt.",
  ui_story_5082_50821400_74_dialog_content = "Todo lo que veo es a alguien que nunca renunció a sus ideales pasados.",
  ui_story_5082_50821400_75_dialog_content = "Todavía proteges a los débiles e indefensos a toda costa. Eso en ti no ha cambiado.",
  ui_story_5082_50821400_76_dialog_content = "¿Incluso si estoy empezando a parecerme más a uno de esos \"grandes personajes\" de los viejos tiempos?",
  ui_story_5082_50821400_X76_dialog_content = "El yo que ves ante ti ahora es el yo que hizo un compromiso por el bien de Illumina. Me he desviado de mis ideales iniciales, sin lograr otorgarles la iluminación que merecían.",
  ui_story_5082_50821400_X77_dialog_content = "Correcto, incluso tú has sacrificado bastante... por eso eres el Gran Mariscal. Has pagado tus deudas... ¿no es suficiente?",
  ui_story_5082_50821400_77_dialog_content = "...",
  ui_story_5082_50821400_78_dialog_content = "Reinhardt, he estado pensando en los viejos tiempos... Tengo que admitir, todo es un poco confuso ahora.",
  ui_story_5082_50821400_79_dialog_content = "Si no hubiera experimentado todo esto hoy, nunca lo habría sabido... Lo diferente que eres ahora en comparación con tu yo adolescente.",
  ui_story_5082_50821400_80_dialog_content = "Potente, decisivo e inevitablemente en el corazón de cada batalla.",
  ui_story_5082_50821400_81_dialog_content = "Todavía recuerdo un tiempo en el que no teníamos tantas responsabilidades que soportar... Las cosas que teníamos que hacer, la forma en que las cosas tenían que terminar...",
  ui_story_5082_50821400_82_dialog_content = "¡Incluso pensamos que podríamos conquistar todo Astra!",
  ui_story_5082_50821400_83_dialog_content = "... No estoy seguro de lo que intento decir, pero como Gran Mariscal y nuestro compañero soldado, todo lo que has ganado hasta hoy fue gracias a tu propia fuerza.",
  ui_story_5082_50821400_84_dialog_content = "Independientemente de si sabía o no lo que estaba pasando detrás de escena, vi tu poder crecer con cada día que pasaba...",
  ui_story_5082_50821400_85_dialog_content = "Y observé cómo liderabas a tus soldados en innumerables batallas que permanecerían grabadas en los corazones del pueblo de Illumina por el resto de sus vidas.",
  ui_story_5082_50821400_86_dialog_content = "Así que cuando la noticia de tu promoción a Gran Mariscal comenzó a difundirse, cada persona en la Federación no sintió nada más que alegría por ti.",
  ui_story_5082_50821400_87_dialog_content = "Al menos a mis ojos, la mirada que me das como Gran Mariscal no es diferente a la mirada que me das cuando luchamos uno al lado del otro.",
  ui_story_5082_50821400_88_dialog_content = "... ¿No crees que todo esto es parte del plan del Comité?",
  ui_story_5082_50821400_89_dialog_content = "Cuando fui promovido a Gran Mariscal durante la última Crisis de Darkover, parecía como si el Comité no tuviera otra opción...",
  ui_story_5082_50821400_90_dialog_content = "Pero para una bomba de tiempo enfriada como yo, la mejor manera de controlarme es dejar el detonador en mis manos.",
  ui_story_5082_50821400_91_dialog_content = "En lo que respecta a los científicos del Comité, este curso de acción fue completamente adecuado.",
  ui_story_5082_50821400_92_dialog_content = "Al enviar a Wrath a luchar esa terrible batalla en Crepúsculo.",
  ui_story_5082_50821400_93_dialog_content = "De hecho, creo que el intento del Comité de destruir a alguien tan poderoso como tú fue su mayor error.",
  ui_story_5082_50821400_94_dialog_content = "Incluso si se niegan a admitirlo, cada soldado en Illumina e incluso los nobles de Lumopolis lo vieron...",
  ui_story_5082_50821400_95_dialog_content = "Durante la crisis de Darkover, tú eras la única opción realista para convertirte en el próximo Gran Mariscal.",
  ui_story_5082_50821400_96_dialog_content = "Si tuvieras la mínima intención de hacerlo, nadie podría impedirte derrocar al Comité y convertirte en el líder supremo de Illumina.",
  ui_story_5082_50821400_97_dialog_content = "¡Jajajaja! Eso podría ser algo que Renegade hubiera hecho, pero yo soy un tipo diferente de Gran Mariscal, Barton.",
  ui_story_5082_50821400_98_dialog_content = "No estás decepcionado conmigo, ¿verdad?",
  ui_story_5082_50821400_99_dialog_content = "¿Decepcionado?",
  ui_story_5082_50821400_100_dialog_content = "Para nada. He visto todo lo que has logrado hasta ahora, y sé que esos experimentos no te convirtieron en ningún tipo de monstruo.",
  ui_story_5082_50821400_101_dialog_content = "Y después de ver lo que Forsakin ha hecho en los últimos años... Digamos que me alegra que ese tipo de poder esté en tus manos y no en las de alguien más...",
  ui_story_5082_50821400_102_dialog_content = "Te elegí como mi Gran Mariscal, Reinhardt. Mi vida ha estado en tus manos durante mucho tiempo ahora.",
  ui_story_5082_50821400_103_dialog_content = "¿Decepcionado contigo? ¡Ja! Me conoces mejor que eso!",
  ui_story_5082_50821400_104_dialog_content = "Miau... Algo me dice que el Comandante Barton está un poco molesto...",
  ui_story_5082_50821400_105_dialog_content = "¡Eso es porque estoy molesto, principalmente conmigo mismo!",
  ui_story_5082_50821400_106_dialog_content = "Cuanto más pienso en estas cosas, peor me siento... Mis aliados más cercanos estaban pasando por tanto dolor, ¿pero qué hice al respecto?",
  ui_story_5082_50821400_107_dialog_content = "¡Debería haber hecho más preguntas! Debería haber... ¡Argh!",
  ui_story_5082_50821400_108_dialog_content = "Barton.",
  ui_story_5082_50821400_109_dialog_content = "Gracias.",
  ui_story_5082_50821400_110_dialog_content = "...",
  ui_story_5082_50821400_111_dialog_content = "Independientemente del tipo de Gran Mariscal que puedas ser... ¡Sigues siendo el Gran Mariscal de Illumina!",
  ui_story_5082_50821400_112_dialog_content = "¡Y hasta un Gran Mariscal rebelde puede provocar un cambio muy necesario en la Federación y mejorar la vida de todos!",
  ui_story_5082_50821400_113_dialog_content = "¡A Yumi le encanta el pescado seco tanto como a mí, lo que la hace igual a mí!",
  ui_story_5082_50821400_114_dialog_content = "Y siempre estaré agradecido de que te hayas convertido en nuestro Gran Mariscal. De hecho, ¡espero que siga siendo así para siempre!",
  ui_story_5082_50821400_115_dialog_content = "Jaja, no puedo prometer algo así; después de todo, cada nuevo día trae nuevos cambios. Puede llegar un día en que ya no sea el Gran Mariscal de Illumina.",
  ui_story_5082_50821400_116_dialog_content = "Y podría ser tan inesperado como todo lo que sucedió aquí hoy.",
  ui_story_5082_50821400_117_dialog_content = "Pero incluso desde esa perspectiva, podremos presenciar cómo se desarrolla la historia con nuestros propios ojos.",
  ui_story_5082_50821400_118_dialog_content = "Todavía no siento que haya dominado completamente el poder que ella me dio en aquel entonces.",
  ui_story_5082_50821400_119_dialog_content = "Pero ahora, todavía tengo el título de Gran Mariscal, así que seguiré haciendo las cosas que solo yo puedo hacer.",
  ui_story_5082_50821400_120_dialog_content = "Es la única forma en que puedo evitar que esas tragedias vuelvan a ocurrir.",
  ui_story_5082_50821400_121_dialog_content = "Haré que nuestros ideales pasados se hagan realidad.",
  ui_story_5082_50821400_122_dialog_content = "Ya sean los Eclipsites o aquellos que buscan herir a nuestros camaradas, aún nos esperan muchas batallas largas y difíciles.",
  ui_story_5082_50821400_123_dialog_content = "¿Puedo contar con el apoyo de todos para mantener a Illumina moviéndose en la dirección correcta?",
  ui_story_5082_50821400_124_dialog_content = "¡Siempre estamos a tus órdenes, Gran Mariscal!",
  ui_story_5082_50821400_125_dialog_content = "Como siempre digo, ¡no tienes permitido descartarme de nada!",
  ui_story_5082_50821400_126_dialog_content = "¡Siempre eres bienvenido a preguntarme por la última inteligencia también, Gran Mariscal!",
  ui_story_5082_50821400_127_dialog_content = "Entonces, una vez que volvamos, comenzaremos investigando las secuelas de esos pasados experimentos con el Colossus.",
  ui_story_5082_50821400_128_dialog_content = "¡Entendido!",
  ui_story_5082_50821400_129_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5082_50821400_130_dialog_content = "Todos ya se han ido. ¿Por qué todavía estás aquí?",
  ui_story_5082_50821400_131_dialog_content = "Podría hacerte la misma pregunta.",
  ui_story_5082_50821400_132_dialog_content = "Todavía estás pensando en Renegade, ¿no es así?",
  ui_story_5082_50821400_133_dialog_content = "... Solo siento un poco de lástima, eso es todo.",
  ui_story_5082_50821400_134_dialog_content = "No esperaba ver una parte de mí morir de esa manera.",
  ui_story_5082_50821400_135_dialog_content = "Antes de irse, Renegado me confió una pregunta para ti.",
  ui_story_5082_50821400_136_dialog_content = "?",
  ui_story_5082_50821400_137_dialog_content = "Ella quería saber...",
  ui_story_5082_50821400_138_dialog_content = "Si todavía estás enojado por todo.",
  ui_story_5082_50821400_139_dialog_content = "...",
  ui_story_5082_50821400_140_dialog_content = "Cuando llegamos por primera vez, siempre escuchaba su grito cada vez que sentía su presencia.",
  ui_story_5082_50821400_141_dialog_content = "Pensé que estaba gritando de dolor o tristeza.",
  ui_story_5082_50821400_142_dialog_content = "Pero después de ver tus recuerdos, finalmente entendí. Ella no estaba gritando de dolor—",
  ui_story_5082_50821400_143_dialog_content = "Estaba aullando de rabia.",
  ui_story_5082_50821400_144_dialog_content = "Estaba enfadada, Reinhardt.",
  ui_story_5082_50821400_145_dialog_content = "Enojado por cada víctima inocente de injusticia, y por cada vida que ha sido tratada con crueldad y desprecio.",
  ui_story_5082_50821400_146_dialog_content = "Esa furia eterna estaba grabada en su corazón y en lo más profundo de su conciencia.",
  ui_story_5082_50821400_147_dialog_content = "Era una renegada nacida de los fuegos de la ira.",
  ui_story_5082_50821400_148_dialog_content = "Deberías darle una respuesta.",
  ui_story_5082_50821400_149_dialog_content = "Para ser honesto, no creo que a ella le guste mi respuesta.",
  ui_story_5082_50821400_150_dialog_content = "Y eso es porque ahora soy el Gran Mariscal de Illumina.",
  ui_story_5082_50821400_151_dialog_content = "Una vez escuché a alguien decir que el Gran Mariscal es como una llama.",
  ui_story_5082_50821400_152_dialog_content = "Uno que se enciende y se alimenta con los cuerpos de los soldados caídos.",
  ui_story_5082_50821400_153_dialog_content = "Pero una llama brillante y abrasadora no arderá por mucho tiempo cuando está cubierta.",
  ui_story_5082_50821400_154_dialog_content = "El fuego dentro de una sola persona nunca será lo suficientemente brillante o poderoso para iluminar la noche eterna.",
  ui_story_5082_50821400_155_dialog_content = "Es por eso que no puedo permitir que las expectativas de innumerables personas permanezcan atrapadas dentro de la persona conocida como Reinhardt.",
  ui_story_5082_50821400_156_dialog_content = "Pero sobre todo, no puedo considerarme únicamente como un salvador.",
  ui_story_5082_50821400_157_dialog_content = "Un mundo verdaderamente brillante que brilla con la luz de la iluminación... es un mundo que forjaremos juntos.",
  ui_story_5082_50821400_158_dialog_content = "Por eso necesito lijar algunos de mis propios bordes... bordes que todavía pueden ser un poco demasiado afilados.",
  ui_story_5082_50821400_159_dialog_content = "Y por eso debo enterrarla aquí.",
  ui_story_5082_50821400_160_dialog_content = "<color=#e8d9bb>Reinhardt se agacha y coloca el dispositivo en el suelo antes de esparcir un poco de tierra sobre él.</color>",
  ui_story_5082_50821400_161_dialog_content = "<color=#e8d9bb>Como si estuvieran dando el último adiós a alguien.</color>",
  ui_story_5082_50821400_162_dialog_content = "Después de hoy, realmente solo seré yo.",
  ui_story_5082_50821400_163_dialog_content = "Adiós, Reinhardt.",
  ui_story_5082_50821400_164_dialog_content = "Ojalá tuviéramos la oportunidad de hablar más antes del final.",
  ui_story_5082_50821400_165_dialog_content = "Pero siempre te recordaré. Tú fuiste quien me hizo sentir completo.",
  ui_story_5082_50821400_166_dialog_content = "May Nunca olvido la ira que una vez me impulsó y me llevó hasta este punto.",
  ui_story_5082_50821400_167_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5082_50821400_168_dialog_content = "<color=#e8d9bb>Como una respuesta final, el polvo en el casco es suavemente soplado.</color>",
  ui_story_5082_50821400_169_dialog_content = "no lo harás",
  ui_story_5082_50821400_170_dialog_content = "Así que has venido, mi \"ira\".",
  ui_story_5082_50821400_171_dialog_content = "Y aunque lo olvides, siempre estaré allí para recordártelo.",
  ui_story_5082_50821400_172_dialog_content = "Ahora soy parte de tu fuerza, y nadie te lo quitará jamás.",
  ui_story_5082_50821400_173_dialog_content = "¿Has llegado a aceptar en lo que me he convertido? He aprendido a comprometerme a lo largo de los años y he caído en el papel del malvado dragón que percibías.",
  ui_story_5082_50821400_174_dialog_content = "Pero que me recuerdes significa que realmente no has olvidado de dónde vino nuestra ira.",
  ui_story_5082_50821400_175_dialog_content = "Fuiste tú quien me derribó, sin embargo, las mismas llamas que me consumieron terminaron forjándote en lo que eres ahora: la iluminación que todos estábamos esperando.",
  ui_story_5082_50821400_176_dialog_content = "Sabiendo que todavía estás en el camino correcto, no guardo rencores.",
  ui_story_5082_50821400_177_dialog_content = "Siempre estaré observándote en tu corazón... Y si algún día empiezas a perderte—",
  ui_story_5082_50821400_178_dialog_content = "Me rebelaré contra ti.",
  ui_story_5082_50821400_179_dialog_content = "<color=#e8d9bb>Su sonrisa siempre llevaba una intensidad ardiente. Siempre que Reinhardt la veía, se sentía extrañamente tranquilizada.</color>",
  ui_story_5082_50821400_180_dialog_content = "¡Ahora estas hablando!",
  ui_story_5082_50821400_181_dialog_content = "Acuerdo."
}
return config
